/* 平成24年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h24.committeeSessions.push(...[{"id":"h24-20121004-4","meetingId":"h24-c-settlement","date":"2012年10月4日","dateIso":"2012-10-04","committee":"決算特別委員会","time":"午前１０時００分～午後５時３８分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を156件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"１３０ページの高齢福祉費のお祝い事業、１３１ページの同じ高齢福祉費の２４時間対応定期巡回・随時対応サービスモデル事業、それから１３６ページの障害者福祉費の発達障害児デイサービス運営費について、３カ所お伺いします。高齢福祉費のお祝い事業ですけれども、このお祝い事業の意味を簡単に教えてください。","respondent":"白鳥高齢者いきがい課長","answer":"長寿お祝い事業の趣旨、目的ですが、高齢者のご長寿、１００歳以上、白寿・卒寿・米寿・傘寿という方々をお祝いしまして、敬老の意を表することを目的といたしまして、お祝い費を贈呈するものです。","voiceIndex":4,"id":"exchange-001"},{"speaker":"沢田委員","kind":"質問・要望","question":"その辺のところをできれば、これから品川区に貢献する若い世代のほうにできるだけ、そういった意味ではお金を回していただきたいという、これは一言要望をします。高齢者も大切ですけれども、高齢者ということで、それはさせていただきたいと思います。続きまして、１３１ページの高齢福祉費の２４時間定期巡回のことでお伺いさせていただきたいと思います。","respondent":"原高齢者福祉課長","answer":"この事業を通じて、この４月に品川区としても実施をしてまいりました。現状ですけれども、この８月末時点で８名の方のご利用という状況です。","voiceIndex":6,"id":"exchange-002"},{"speaker":"沢田委員","kind":"意見","question":"今、そのようなご説明をいただきましたけれども、もともと夜間対応型ということでやってきたことと、日中事業者との連携ということでやっていらっしゃると思うのですが、そちらの状況も今どんな状況であるのか。他区でもこういった国のモデル事業として進められていると思うのですけれども、ほかの区の状況がもしわかれば、お聞かせください。","respondent":"原高齢者福祉課長","answer":"今まで実施しておりました夜間の訪問介護の状況ですけれども、約９０名の方にご利用いただいている状況です。","voiceIndex":8,"id":"exchange-003"},{"speaker":"沢田委員","kind":"質問・要望","question":"次に１３６ページの障害者福祉費の中の発達障害についてお伺いさせていただきたいと思います。","respondent":"永尾障害者福祉課長","answer":"この対応につきましても、年々研究が進んでいるところですので、こういう事業と、学校との連携もしながら進めていきたいと考えております。","voiceIndex":10,"id":"exchange-004"},{"speaker":"沢田委員","kind":"意見","question":"卒業するときに保護者の方から特別支援の学校に入れさせたいということで、理由はやはりそのほうが就労に有利になる部分もあるということで、一般の企業とかの特別支援学校の枠のほうが有利という話もあったということで、先生自身は全然気づかなかったというお話もされていたぐらい、保護者の方にしかわからない部分もあるかと思いますけれども、そういった中で、今後、発達障害が増えてきたりということで。","respondent":"永尾障害者福祉課長","answer":"健診につきましては、現在、保健センターでやっている３歳児健診の中でもかなりそういうお子さんが見つかって、相談室につながってきていたりしますので、保健センター、また学校とも今後の連携を強めまして、そういう方への支援をしていきたいと考えています。","voiceIndex":14,"id":"exchange-005"},{"speaker":"鶴委員","kind":"質問","question":"私からは１３２ページの障害者福祉費と、１４２ページ、児童センター運営費についてお伺いします。その中で、難病の方に関する現在の所管は保健センターで行われていて、来年４月の施行に際して、障害者福祉サービスを所管する障害福祉課として保健センターとの連携などを含めて、どのような対応の想定をしているか、このあたりを教えてください。","respondent":"永尾障害者福祉課長","answer":"来年４月に施行予定の障害者総合支援法ですけれども、難病につきまして新たに障害者の定義に入ることになっております。ただし、難病専用の手帳を発行するかどうかということは、今のところ何もそういう情報は入っていない状態です。","voiceIndex":17,"id":"exchange-006"},{"speaker":"鶴委員","kind":"質問・要望","question":"そうしたしっかりとしたあらゆる想定を考えていただいて、連携を密にしていただきたいと思います。同じ費目で、次に障害者の交流事業についてお尋ねいたします。現在、区で行っている交流事業を教えていただきたいと思います。","respondent":"永尾障害者福祉課長","answer":"そのほかに日常的な交流としまして、心身障害者福祉会館で地域活動支援事業を今年４月から開始しておりまして、そこではサロン的なものも、先日工事が終わりまして、開始しております。","voiceIndex":19,"id":"exchange-007"},{"speaker":"鶴委員","kind":"質問","question":"今、教えていただいた福祉まつりとかそのあたりは私もその都度参加させていただいたりしていますのであれですけれども、その上で、対象というのですか、障害者と地域の方とかいろいろな団体とかの交流という意味で、小中学校とか、ないし小中学生を対象とした、いわゆる障害のことについて学んでいくとか、また、そうしたことについての取り組みなどは今まであったのか。","respondent":"永尾障害者福祉課長","answer":"は施設では、近隣の地域の方や町会の方との交流というところも努力して進めてきているところですので、やっぱり健常者の方にも障害のことを知っていただく、障害者の方もいろいろな社会参加の機会を設けるということで重要になってきておりますので。","voiceIndex":21,"id":"exchange-008"},{"speaker":"鶴委員","kind":"提案","question":"特別支援学校とかで、今言っていただいた浅間台小学校とかをはじめとして、また各施設では地域の方との交流の中で障害について知っていただくという取り組みは非常に大事かなと思います。その上で１つ提案させていただきたいのが、これは八王子市でもう２０年くらい前から取り組んでいる取り組みなのですが、市内の小中学生を対象に、子ども点字・手話教室を実施しているそうです。","respondent":"永尾障害者福祉課長","answer":"ご提案されました点字や手話の教室ですけれども、お子さんを相手に教える支援者の方とか、どういう形でやるかというところは検討が必要になると思いますので、これに限らず、お子さんが参加できるものについては、いろいろな団体の意見も聞きながら考えていきたいと思います。","voiceIndex":23,"id":"exchange-009"},{"speaker":"鶴委員","kind":"質問・要望","question":"ぜひそういう各種障害者団体の方とも意見交換をやっていただきながら、本当に幅広い形でそういう取り組みをやっていただく、また、区が主導していただくことも大事な点かなと思いますので、ぜひご検討いただきたいと思います。次に移ります。児童センター運営費であります。維持管理に関してというところです。幼児のための部屋とかスペースがあるのか、これを簡単に教えていただければと思います。","respondent":"安井子育て支援課長","answer":"特に午前中は小学生も来ておりませんので、遊戯室等がありますので、そちらで少し大型のおもちゃ、さまざまなものがありますけれども、そういったもので遊べるような形で幼児たちの対応を行っている形になってあります。","voiceIndex":25,"id":"exchange-010"},{"speaker":"鶴委員","kind":"提案","question":"ここの中にも施設整備費とか設備充実費という費目がありますので、そういう範疇でできるのかなと思いますので、ぜひそういうクッション材のようなものをご検討いただいて、床に敷くようにしていただきたいなと、要望でとどめますけれども、お願いしたいと思います。次に、児童センターの事業に関して、最後確認します。東品川児童センターのチラシをこの間見ました。","respondent":"安井子育て支援課長","answer":"はいはいの競争については、子育てメッセでもやっていただいたことがあります。運動会は屋外でやっているものなので、そういった場所の問題とかそこら辺もあろうかと思いますので、研究させていただいて、それなりにうまく行くような形で検討させていただきたいと考えています。","voiceIndex":27,"id":"exchange-011"},{"speaker":"鶴委員","kind":"質問・要望","question":"やっぱりネーミングは非常に大事かなと思うのです。雰囲気づくりというか、そういった部分でも絡めてぜひやっていただきたいということと、もう１個大事なことが、やっぱりはいはいは言語能力とか脳の発達に非常に重要だと私も伺っておりますので、施設内でやる場所の検討もありますけれども、そういう楽しく取り組めることをやっていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-012"},{"speaker":"藤原委員","kind":"質問","question":"１３６ページのひとり親家庭支援事業のところと、１３９ページ児童関係各種の手当てについてお伺いしますが、まずはじめに、民生委員に平成２３年度に高齢者実態調査をしていただいたと思うのですけれども、まずその内容と、そこからわかってきたことは何かということと、わかってきたことによる課題、それとその課題をどう区政に反映していくか、この点についてお伺いします。","respondent":"原高齢者福祉課長","answer":"そういった中で、これから高齢者施策の中で、品川区の特徴でもありますけれども、ひとり暮らし高齢者あるいは高齢者世帯が年々増えているというところも、この状況の中で把握できておりますので、これをさまざまな施策に活かしていくという形で実施しているものです。","voiceIndex":31,"id":"exchange-013"},{"speaker":"藤原委員","kind":"質問・要望","question":"それと、その民生委員の改選が３年ごとにありますよね。そういう中において、改選時期の問題と、定年でどのくらいおやめになるかということと、新規といいますか、民生委員はお忙しいわけですから、なかなかなり手がいないとも伺っているのですけれども、その中で、区としてはどのような対策をしていくのか、教えてください。","respondent":"原高齢者福祉課長","answer":"そういう中で、どうやって負担軽減ができるか私どもは毎日考えているわけですけれども、１つとしまして、まず民生委員によって取り扱っている、見ているご利用者の数が大きく違うところについては、定数を変えずに、その人の持っている地図上での領分というのですか。","voiceIndex":33,"id":"exchange-014"},{"speaker":"藤原委員","kind":"質問・要望","question":"私もそうですが、民生委員に感謝しつつ、これからも区政を協働でしていっていただきたいと思います。よろしくお願いします。次に、児童育成手当と児童扶養手当についてお伺いしますが、たしか去年くらいから父子家庭の皆様にも手当を出していると思うのですけれども、まずこの数字を伺いますが、父子分の申請状況と申請率はどのくらいでしょうか。","respondent":"梶青少年育成課長","answer":"２,０００弱なのですが、そのうちの父子世帯の割合が４.８％となっています。児童育成手当、児童扶養手当の２つとも、ひとり親家庭の手当なのですが、こちらもはっきりした件数は言えないのですけれども、両方とも母子家庭だけではなくて父子家庭も対象になっているです。","voiceIndex":35,"id":"exchange-015"},{"speaker":"藤原委員","kind":"質問","question":"その申請状況を把握なされて、どういうふうに父子家庭の実情を区として把握されているでしょうか。","respondent":"梶青少年育成課長","answer":"先ほどのひとり親家庭ですけれども、全体から言うと５％未満ということで、もちろん少ないのですけれども、私どもで助成するものに関しましては、あくまでも１８歳に達する児童を育てている家庭ですので、なおかつ所得制限があります。","voiceIndex":37,"id":"exchange-016"},{"speaker":"藤原委員","kind":"質問","question":"昨日も伺いましたが、ＤＶについてお伺いしますけれども、物理的な暴力だけでなく、さまざまな暴力から逃げてこられて、対応されるのが子育て支援課だと思いますが、シェルターとかも含めて明らかにできないことがあると思いますので、秘密にしておかなければいけないことがあるならば答弁なさらないで結構ですから、よろしくお願いします。","respondent":"安井子育て支援課長","answer":"主要施策の成果報告書には移送が２件となっていますけれども、こちらについては、特にお子さんたちを連れているということで荷物を持ってという形で、こちらで交通手段を確保して、東京都の配偶者暴力相談支援センターという次に保護の対応をする場所へお連れするという。","voiceIndex":39,"id":"exchange-017"},{"speaker":"藤原委員","kind":"質問・要望","question":"共依存の問題もある、いろいろな問題はあると思うのですけれども、いわゆる役所ではなくて相談した方、まずＤＶを受けて相談をしている、例えば親御さんとか、そういう方たちが加害者に攻撃されているのではないかという心配感から出てくるというのもあると聞いておりますが、被害者だけではなくして、被害者に近い方を守るという形は今後どういう形で考えていくのか、教えてください。","respondent":"安井子育て支援課長","answer":"それについては、そういう相談があったことについても一切私どもは答えないという形で、被害者の保護を図るという対応をしています。","voiceIndex":41,"id":"exchange-018"},{"speaker":"藤原委員","kind":"質問","question":"最後に、被害者というと女性、お母さんというイメージがあるのですが、そこでお子さんです。お子さんは目の前で暴力を見たり、引っ越したり、知らない土地に行ったり、転校したりという大変な状況に置かれると思うのですが、お子さんへの対応をどうしていくのか教えてください。","respondent":"安井子育て支援課長","answer":"子どもにとってはこれ自体が大きな負担になっているですので、逃げた先のところには新たなそちらのいわゆる家庭支援センターであるとかそういったところにつないで、相当にお子さんのほうが虐待を受けていたという話をつなげることもやっているところです。","voiceIndex":43,"id":"exchange-019"},{"speaker":"木村委員","kind":"質問","question":"１３０ページの高齢福祉費８億７,５７４万円余について質問いたします。高齢福祉費、平成２２年度の約８億４,９７７万円余からすれば、約２,６００万円の増加になっています。ちなみに平成２４年度の予算は７億８,２６９万円余となっています。これは一時的なものなのか、それともここ数年はこのような予算とか決算になると予測できるのでしょうか、お答えください。","respondent":"原高齢者福祉課長","answer":"それから減額のところですけれども、こちらは少し事情がございまして、大きなところでは高齢福祉費、平成２３年度の決算の中で品川区シルバー人材センター支援事業があります。","voiceIndex":46,"id":"exchange-020"},{"speaker":"木村委員","kind":"質問","question":"１３１ページの上から５行目、認知症高齢者の支援とケアの充実８２８万２,４６７円についてですが、これはどのような事業で、事業の主な目的はどのようなことでしょうか、お願いします。","respondent":"原高齢者福祉課長","answer":"認知症といいましても幅が広いわけでございまして、認知症だからということで一概に言えるところはございませんけれども、高齢者が認知症になっても住み慣れた品川区の中で安心して暮らし続けられるまちを目指していくということで、この事業は実施しています。","voiceIndex":48,"id":"exchange-021"},{"speaker":"木村委員","kind":"質問","question":"認知症高齢者が１０年で現在の倍になるだろうと国では読んでいます。そう考えれば、現在、品川区には６,０００名の認知症の方がいらっしゃるということでありました。それに比例して、予算も約倍の１,６００万円から大体２,０００万円くらいになると考えられますが、区としてはどのような試算がなされているのか、また、この事業に対してどのような心構えでのぞむのでしょうか、お答えください。","respondent":"原高齢者福祉課長","answer":"今後についてもその基本的な考え方の中で施策を進めていこうと考えているところです。","voiceIndex":50,"id":"exchange-022"},{"speaker":"木村委員","kind":"質問","question":"家族や地域の皆さんが認知症とは何かをしっかりと理解をして接することが大事だということがよくわかりました。私たちが認知症に対して理解するのに一番手っ取り早い方法という、例えば勉強会だとかセミナーがあるとか、そのようなものが品川区で行われているのかどうか。そして、認知症の程度をあらわすランクですけれども、これが大体９ランクほどあるとお聞きしました。","respondent":"原高齢者福祉課長","answer":"その１つが、先週の土曜日に行いましたけれども、これは毎年実施しております認知症講演会で、荏原文化センターで今回も４００名、それから申し込みの段階でも定員を超えるということで多くの方をお断りさせていただいた状況です。","voiceIndex":52,"id":"exchange-023"},{"speaker":"木村委員","kind":"意見","question":"例で話を聞いたことがあるのですけれども、毎日、あるお米屋さんに通ってくる方がいて、いつも大量に注文するというような話を聞いたことがありました。そして、私たちの対応次第で、本人の自尊心を傷つけず、本人らしさを尊重してあげることが本人にとってどれほどの影響力があるのか、また、それを与えることができるのか、お答えください。","respondent":"原高齢者福祉課長","answer":"この中でどのくらいの方がというところは、家庭の環境でありますとか、介護の環境等々によって非常に変わってきますので、一概にこの中でどこから在宅は難しいとかいうことではなく、その地域の中で、あるいは家庭の中でどうやってその方を理解し。","voiceIndex":54,"id":"exchange-024"},{"speaker":"木村委員","kind":"質問・要望","question":"１３１ページの真ん中より下にありますけれども、高齢者熱中症等予防対策事業、３４２万円についてですが、今年も全国で多くの人が熱中症で病院に搬送されていました。熱中症と高齢者との関係について、理事者のお考えをお聞かせください。熱中症は真夏の暑いときだけに起きるわけでもないともお聞きします。こんなことがといった変わった例があったかどうかも教えていただきたいと思います。","respondent":"原高齢者福祉課長","answer":"いつも外に出て待っていらっしゃるのに出ていないということで、いろいろ電話をしても通じない、少しあいている窓から見たら中で倒れている、そういった中で救急対応をした事例等もあります。","voiceIndex":56,"id":"exchange-025"},{"speaker":"木村委員","kind":"意見","question":"時間がなくなってきました。品川区で高齢者の方々に扇風機などを貸し付ける事業があるかと思いますけれども、これは大体２０台くらいという話を聞いたわけですが、いつ貸し出して、どのタイミングで回収をするのか。今年１０月に入って３０度を超えるようなときがありますので大変難しいと思います。それを簡単にお願いします。","respondent":"原高齢者福祉課長","answer":"この時期につきましては、事務的にいつからいつということで決めているわけではございません。そういった状況にうまく対応できるようにしています。","voiceIndex":58,"id":"exchange-026"},{"speaker":"中塚委員","kind":"質問","question":"私からは１４３ページの生活保護費にかかわって、先日２８日に厚生労働省が特別部会に示したたたき台について、家族の扶養義務を強化する生活保護の受給権侵害について伺いたいと思います。私は生活に困窮し、必要な人が生活保護を受けることができないような状況を拡大させてはならないと思いますが、この扶養義務強化をいかがお考えでしょうか。","respondent":"竹田生活福祉課長","answer":"今後示されます国や都の方針を参考に、品川区の現状を踏まえて効果的な支援に取り組んでまいりたいと考えています。","voiceIndex":61,"id":"exchange-027"},{"speaker":"中塚委員","kind":"質問","question":"区はこの間のこうした生活保護バッシングをどう考えているのか。行政の責任者としての見解を伺いたいと思います。先ほどの扶養義務強化ですけれども、迷惑をかけてきた親や兄弟に扶養調査されるなら申請したくない、こうした話をよく伺います。家庭内暴力や虐待で親子関係や夫婦の縁を切った人に扶養を迫るなど間違っていると思いますが、改めて見解を伺いたいと思います。","respondent":"竹田生活福祉課長","answer":"実施要領においても、扶養の履行は努めて当事者間における話し合いによって解決し、円満に履行することを本旨として取り扱うとされております。必要な方に必要な援助が届きますよう、今後も国の動向や品川区の現状を踏まえて、法の趣旨に沿って適切に実施してまいる所存です。","voiceIndex":63,"id":"exchange-028"},{"speaker":"中塚委員","kind":"質問","question":"保護利用率で見ると、ヨーロッパでは５％から６％に対し、日本は１.６％。日本では最低生活費を下回る所得しかない世帯のうち、生活保護を利用している方は１５％程度だと言われています。生活に困窮しながら必要な人が利用できていない。こうした深刻な現状こそ解決が急がれていると思いますが、区の取り組みを伺いたいと思います。社会が克服すべき社会問題だと思いますが、いかがでしょうか。","respondent":"竹田生活福祉課長","answer":"先ほども申し上げましたけれども、必要な方に必要な支援が行き届き、そして生活困窮の方につきましても実りある人生を送っていただけるように、我々も保護制度の適切な実施に努めているところです。","voiceIndex":65,"id":"exchange-029"},{"speaker":"中塚委員","kind":"質問","question":"生活に困窮し、医療はもちろん食事も住むところも失いかける、または失っている、こうした方々から、私も相談をたくさん寄せられております。生活が厳しくなった経過について、例えば家族の１人が大きな病気にかかり、医療費、特に最近では高額な差額ベッド代がかさみ、貯金が一気になくなる。仕事も年齢で減ってくる。こうした改悪にしっかりと反対していくべきだと思いますが、いかがでしょうか。","respondent":"竹田生活福祉課長","answer":"保護義務関係にある者などの重点的扶養能力調査対象者に関しましては、扶養能力および扶養の履行状況の調査は国の指針に基づいて年間１回程度行っております。今後も国の方針に基づきまして適切に実行してまいりたいと考えています。","voiceIndex":67,"id":"exchange-030"},{"speaker":"中塚委員","kind":"質問","question":"現在の区の扶養についての調査なのですが、先ほどから指摘しましたが、例えば家庭内暴力や虐待、また、経済的な問題、さまざまな理由で親子関係や兄弟の縁を切らざるを得なかった方に対してまで扶養を迫るという対応はされているのでしょうか。それともそれについてはどのように対応されているのでしょうか、伺います。","respondent":"竹田生活福祉課長","answer":"生活保護を申請されて、生活保護を開始される方にはさまざまなご事情があります。一番多いものは経済的なものですが、扶養に関しては一律に扶養を調査したり強制したりすることはいたしておりません。それぞれの保護を要する事情に基づきまして対応しております。","voiceIndex":69,"id":"exchange-031"},{"speaker":"山内委員","kind":"質問","question":"私から、１３３ページの生活支援サービスの中で、まず精神障害者地域生活安定化支援事業、延べ１,６３７人、これらの方々は、ひきこもりや地域で孤立状態の重い精神障害を持つ方々であろうかと思います。その中で、区が把握している、現在の統合失調症の患者の人数がわかれば教えてください。","respondent":"永尾障害者福祉課長","answer":"保健センターでその数字自体は把握しているということですので、直接的な数字は手持ちには持っておりません。","voiceIndex":72,"id":"exchange-032"},{"speaker":"山内委員","kind":"質問・要望","question":"これは、２４時間対応するという前提のもとでこういった事業が、いわゆる精神科医、それから看護師、さらには精神保健福祉士といった方々を中心にチームをつくって、アウトリーチ型のそういった取り組みをするということでありますけれども、品川区で精神科医が中心になってこういった取り組みを行っているところでありますけれども、いろいろそういったチームを編成する中で。","respondent":"永尾障害者福祉課長、福島荏原保健センター所長","answer":"現在やっている内容といたしましては、専門の精神科医が月に１回精神障害者の方のところに訪問をして、現状のご相談を受けたり、服薬についてのご説明をしたりというところになっております。先ほど委員よりご質問のありました、統合失調症の方がどれくらいかという人数のことですが、自立支援医療費、精神通院医療費を申請なさっている方が全体で平成２３年は３,６２３人で。","voiceIndex":74,"id":"exchange-033"},{"speaker":"山内委員","kind":"質問","question":"そういうところから、一歩一歩というところなのですが、今は月１回、医療チームがアウトリーチという形で訪問しているという現状ですけれども、例えばこれを月に複数回やっていくとか、そういったことが所管で話し合いをされているのか。それと、そういった相談をされてこられる、いわゆる団体の方々、個人の方々、そういった方々には、どのように対応しているのかといったことを、改めて伺いたいと思います。","respondent":"永尾障害者福祉課長","answer":"複数回の訪問になったときに、医師が複数回というのはなかなか難しいところはありますので、例えば、今いる精神保健福祉士のほかのメンバーの人員確保を何とか、やっているＮＰＯとも相談しながら考えて増やしていくとか、そういう形で。","voiceIndex":77,"id":"exchange-034"},{"speaker":"山内委員","kind":"質問","question":"わかりました。次に、１２９ページの福祉人材確保・定着事業の中で、まず数字的なことを伺いたいのですが、この予算が９,７００万円に対して１億８００万円。１,０００万円上がった決算をされているというところの数字的なもの、それから財源はどのような形で確保しているのか、非常に大きい金額なのでそのあたりを伺いたいのと、これはどういう事業なのか。","respondent":"原高齢者福祉課長","answer":"その中で特別養護老人ホームにおけます看護スキルアップ事業になりますけれども、こちらにつきましては、人材派遣等から５０人雇用しまして、その雇用した部分で看護師があいた時間を施設の職員に、今、法改正等が行われました、たんの吸引の研修でありますとか。","voiceIndex":79,"id":"exchange-035"},{"speaker":"山内委員","kind":"質問・要望","question":"これから品川区は高齢者施設ができていく。定員が４０名ということでやっております。これはいろいろとありますけれども、そこで卒業された方は３年でしたっけ、区内の事業所へ勤めていただく。そこから人材を確保していくといった考え方も１つありなのかなという思いがいたしております。今、課長の答弁の中で人材不足ということを何度も聞いたので、そのあたりの答弁をいただきたいと思います。","respondent":"原高齢者福祉課長","answer":"ただ、委員ご指摘のとおり、品川区は平成７年から介護学校を区内に社会福祉協議会を通じてつくってあります。区の中で介護人材を育成していくといった取り組みはほかの自治体では全くない中で先駆的に実施しております。","voiceIndex":81,"id":"exchange-036"},{"speaker":"阿久津委員","kind":"質問・要望","question":"私からは１２８ページ、成年後見センター。１３１ページ、認知症高齢者の支援とケアの充実。そして１８９ページ、国民健康保険全般について、お伺いいたします。","respondent":"原高齢者福祉課長","answer":"認定を受けている方の中です。認定を受けている方が１万２,０００人ですので、その中の約半分という数字になろうかと思います。","voiceIndex":84,"id":"exchange-037"},{"speaker":"阿久津委員","kind":"確認","question":"本当に多いなと。当たり前ですね、１０人に１人がという内容ですから。中には本当に壮絶な話もあって、本当にこれは区としても、また私も議員として真剣に向かっていかないといけないと決意しているところですが、まず１つ確認をしたいのですが、病院の件です。拠点病院に指定されたと聞いているのですが、この病院ももちろん物忘れ外来は銘打っているのでしょうか。教えてください。","respondent":"原高齢者福祉課長","answer":"委員ご指摘のとおり、オレンジプランの中で二次医療圏に１カ所ずつということで、国も認知症に対応していくです。荏原病院がこの二次医療圏ということで、品川区および大田区ということで、その任を任されるです。","voiceIndex":86,"id":"exchange-038"},{"speaker":"阿久津委員","kind":"提案","question":"すみません、実は前もって調べていまして、物忘れ外来はあります。実は私も調べていて、これはいい方法があるなと、提案しようかななんて思ったら、随分前から品川区は取り入れられているということなのですが、議事録を見ていると、フィードバックのやり方に問題があるような議事録があったのですが、現在、これは現場での運用、また、その評価について教えていただけたらと思います。","respondent":"原高齢者福祉課長","answer":"その人らしさをこのアセスメントの中で導くということで、区はかなり前からこのセンター方式を取り入れてということで、研修も福祉カレッジを通じて、認知症の専門コースということで、まず認知症を理解するという取り組みの中の１つに。","voiceIndex":88,"id":"exchange-039"},{"speaker":"阿久津委員","kind":"質問","question":"いろいろと調べれば調べるほど、品川区は実は認知症対策が進んでいるのだなと実感しているのですが、その中で認知症サポーター養成事業、先ほども出てきましたけれども、先ほどはたしか５,４００人を超えるサポーターの方がいるということなのですが、今後どう活かしていくのかというところでお聞きしたいのですけれども、先ほど言った厚生労働省のオレンジプランを読みますと。","respondent":"原高齢者福祉課長","answer":"それからキャラバン・メイトは２５０名ということで、地域の中で認知症サポーターの講演、講習を担っていただくというものを１つのものにしていますし、この間、認知症の講演会をやりましたけれども、その席でも。","voiceIndex":90,"id":"exchange-040"},{"speaker":"阿久津委員","kind":"質問","question":"割合を出すのがなかなか難しい。よく理解できました。相談をしても契約数が少ない。時間がないので、最後に１８９ページ、国民健康保険についてお伺いします。生活保護受給者に対するジェネリック医薬品の使用促進の取り組みが始まっていますが、国としてもジェネリック医薬品を使用促進する取り組みを行っておりますけれども、それについての本区の認識についてお伺いいたします。","respondent":"間部国保医療年金課長","answer":"医療費につきましては、国民健康保険の構造的な問題ということで、やはり高齢者の率が高いということ、また、近年の医療の高度化等々につきまして、上昇しているものと認識しております。ジェネリック医薬品につきましては、まず医療費が保険給付費の約７割を占めています。","voiceIndex":94,"id":"exchange-041"},{"speaker":"阿久津委員","kind":"意見","question":"本年第１回定例会で、広島県呉市の例を挙げさせていただきまして、国民健康保険の被保険者に対する差額通知、つまり現在使っている先発医薬品をジェネリック医薬品に切りかえた場合の差額を照合して、これは呉市の例ですけれども、その上で薬代が高額となっている上位者を抽出して。","respondent":"間部国保医療年金課長","answer":"ジェネリック医薬品への対応ですけれども、平成２３年度、２３区におきまして実施しているのは、今のところ江東区のみです。平成２４年度、今年度中に実施が５区と伺っているところです。","voiceIndex":96,"id":"exchange-042"},{"speaker":"阿久津委員","kind":"意見","question":"先ほどパーセンテージにして、少ないパーセンテージであっても非常に大きな経済効果があると。これは我々、薬を使う者にとっても、また区にとってもＷｉｎ－Ｗｉｎの関係でありますし、どこが損をするかといえば、大手の製薬会社がもしかすると収入が減ることはあるのかもしれませんけれども、基本的に区民の方に還元できる施策であると思いますので、ぜひ前向きにご検討いただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":98,"id":"exchange-043"},{"speaker":"鈴木（博）委員","kind":"質問","question":"私は、まず１４２ページのすくすく赤ちゃん訪問事業と、助産師によるベビーマッサージ事業、それと１４３ページの家庭あんしんセンター運営費について、お尋ねいたします。第一に、すくすく赤ちゃん訪問事業については、昨年の決算特別委員会でも持参する物品についてお伺いしましたが、ブックスタートパックのほかに、現在では担当の方は何を持参して訪問されているのでしょうか。お伺いしたいと思います。","respondent":"安井子育て支援課長","answer":"お子さんの状況、特に我々児童センターで行っている場合は、なかなかお会いできないようなケースですので、お子さんが確認できるまで、奥にお子さんがいるというようなこともありますので、なるべくお子さんを現認できる形で、お子さんを見るということもやっておりますので。","voiceIndex":101,"id":"exchange-044"},{"speaker":"鈴木（博）委員","kind":"意見","question":"ちょうど事業の対象になるご家庭で、生後４カ月までのご家庭というのはまだ赤ちゃんを家庭に迎えて、母親も父親もその育児になれておりません。このようなそれぞれの家庭に対して、画一的ではない、その家庭に合ったきめ細かい援助と助言が必要とされていると思います。必要な場合は小児科の受診も進めるべきです。","respondent":"坂上品川保健センター所長","answer":"すくすく赤ちゃん訪問事業は、保健センターから保健師や訪問指導員が訪問している事業と、先ほど子育て支援課長が申しました児童センターの職員が訪問しているのと、大きく２つに分けられます。","voiceIndex":103,"id":"exchange-045"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"ワクチンデビューは生後２カ月からスタートとなります。最近はみずから学び、積極的に小児科医療機関にワクチンを受けにくる意識の高いご両親も増えてきておりますが、ぜひ絵本、その他のセットだけではなく、お話だけではなく、ワクチンの啓発パンフレットも同封されることを重ねて要望させていただきたいと思いまして、次の質問に移りたいと思います。","respondent":"安井子育て支援課長","answer":"こちらのベビーマッサージなのですけれども、保健的な部分の効果はもう一つわからない部分はありますけれども、子育て支援という部分でいきますと、やはりお子さんとスキンシップを図るということ。","voiceIndex":105,"id":"exchange-046"},{"speaker":"鈴木（博）委員","kind":"質問","question":"長い間、小児科医として子育てを行っている母親を見ておりますと、最近の母親は赤ちゃんに触れる時間がかなり短くなってきているように感じられます。その上でのベビーマッサージだと考えます。ベビーマッサージもよいでしょう。しかし、そのようなサービスは民に任せてもいいのではないかという気もいたしますが、この事業を品川区の事業として行う積極的な意義について、もう一度ご説明をお願いします。","respondent":"安井子育て支援課長","answer":"児童センターにいらっしゃるお母さんの中には、赤ちゃんに触れるのは自分の子どもが初めてという方もいらっしゃいますので、子どもを実際どのようにあやしたり、触ったりするのかということにすら、やはり悩んでいらっしゃるというお母さんたちもいらっしゃいますので。","voiceIndex":107,"id":"exchange-047"},{"speaker":"鈴木（博）委員","kind":"質問","question":"時間がありませんので、家庭あんしんセンターのほうにいかせていただきます。母子生活支援施設のひまわり荘についてお伺いいたします。今年度現在と昨年の入居世帯数についてご教授をお願いいたします。","respondent":"安井子育て支援課長","answer":"ひまわり荘は、今年につきましては、この１０月１日現在で１４世帯３４人の方が入所されていらっしゃいます。","voiceIndex":109,"id":"exchange-048"},{"speaker":"大倉委員","kind":"質問・要望","question":"私からは、１３７ページ、幼児二人同乗用自転車レンタル事業と、２２５ページ、介護認定審査会費に関連して、介護認定についてお伺いします。順番が前後いたしますが、介護認定について、先にお伺いします。それと審査の件数はここ数年どのような傾向にあるかをわかれば教えていただきたいと思います。","respondent":"原高齢者福祉課長","answer":"合議体の数ですけれども、この３月までは５合議体でございましたところを、認定審査の件数が増えるということで、合議体を６に増やさせていただいたです。そういった中で、合議体が６つということで、その合議体ごとに合議体の長がいる形になっているものです。","voiceIndex":113,"id":"exchange-049"},{"speaker":"大倉委員","kind":"質問・要望","question":"次に行って、一次判定審査で、介護認定審査資料に基づいたコンピューターとかによる審査が行われて、そこはある程度一定の基準があって決まって、第二次判定が行われると思うのですが、そうした中で、判定がどういった形で行われるのかというやり方というか、方法を教えていただきたいのと、第二次判定において、軽度、重度、一次判定から来たものの介護度が下がったり上がったりする件数は。","respondent":"原高齢者福祉課長","answer":"二次判定ということで、審査会で議論いただくわけですけれども、品川区の場合は、これは介護保険が始まりました平成１２年から、区の職員が非常勤も含めて事務局として出された認定調査、それから主治医の意見書をもとに全件確認させていただき、中で。","voiceIndex":119,"id":"exchange-050"},{"speaker":"大倉委員","kind":"質問・要望","question":"審査にかかって重度化された方も、軽度になられた方もいるといった中で、１件当たりどのくらいの時間がかかって、そういったお話、議論がされるのかというのを教えていただきたいと思います。他区ではこういった事例が多分ないと伺っております。そうした中で、品川区ではどのくらいの時間をかけてやられているのか、また、その時間が適正なのか、どのようにお考えなのかを教えていただきたいと思います。","respondent":"原高齢者福祉課長","answer":"そういった意味では、それを単純に割り返しますと２分あるいは２分弱ということで、委員ご指摘の他区の状況と時間としては変わりないという状況です。ただし、先ほど言いましたように、区では事務局が必ず全件同じ目で見ているというところは品川区の特徴と考えているところです。","voiceIndex":121,"id":"exchange-051"},{"speaker":"大倉委員","kind":"質問・要望","question":"２時間で５５件から６５件、日によって件数が違うということでした。ぜひ、今後もそうした熟議がしっかりできるようにしていただきたいと思います。その中で、最初に聞かせていただいた５５名という委員が、今７０名まで増やせると条例が改正されたと思うのですが、今後どういうふうにしていこうというお考えがあるのかをお聞かせください。","respondent":"原高齢者福祉課長","answer":"条例で７０名まで、第１回定例会で改正させていただきました。７０名ですからまだ少し余裕があるわけですけれども、今後の高齢者の増加、それから認定を受ける方の増加を鑑みて、そこまでの余裕を持って、また合議体についても件数の増加に合わせて増やすという考え方です。","voiceIndex":123,"id":"exchange-052"},{"speaker":"大倉委員","kind":"質問・要望","question":"次に移りたいと思います。幼児二人同乗用自転車レンタル事業についてお伺いします。この事業の開始の経緯とその目的。開始から数年たっていると思うのですが、台数がどのように増えていって、今後どのようにしていく方針なのかをお聞かせいただきたいと思います。","respondent":"安井子育て支援課長","answer":"こちらにつきましては平成２２年度に事業を開始いたしまして、当初１５台。平成２３年度につきましては５台増やしまして２０台。そして今年度につきましてはさらに５台増やしまして全２５台という枠の中で、レンタル事業を行っているところです。","voiceIndex":125,"id":"exchange-053"},{"speaker":"大倉委員","kind":"質問・要望","question":"今後も方針としては５台ずつ増やしていくということでした。こうした利用は多分まだあるのかなと。現状、まだ台数が余っているというお話も先ほど伺いましたが、そうした中でも、今後どういった周知をしていくかということが大事かなと思っています。そうしたところで区のお考えというか、お話を聞かせていただければと思います。","respondent":"安井子育て支援課長","answer":"周知につきましては、広報しながわで６月１１日に広報させていただいたほか、ケーブルテレビで周知を図りまして、また、児童センターにはチラシ等を置かせていただいて対応しています。","voiceIndex":127,"id":"exchange-054"},{"speaker":"渡辺委員","kind":"質問","question":"私は、成果報告書１３１ページ、高齢者相談等事業、関係して民生委員経費で伺いたいと思います。その中で、品川区独自の高齢者訪問の対象者の総数、本来の対象者、その仕組みの中で、当然行っていい、悪いがあるかと思います。その数。対象者はこの決算書でも２８２名かと思われますが、その方々が実際現場での訪問する回数であり頻度、その目安、基準などがありましたら教えてください。","respondent":"原高齢者福祉課長","answer":"そういった中で、どのくらいの対象者かです。高齢者相談員というのは、民生委員に区が独自に委嘱して、高齢者相談員という役をさらに担っていただくということで実施してございまして、こういった中で実態調査を３年に１回していただいているところです。","voiceIndex":130,"id":"exchange-055"},{"speaker":"渡辺委員","kind":"提案","question":"ここで、現場に携わる方のお声で、それも複数名から伺う中で、まず午前中、どの委員からもありましたが、民生委員は確かに大変だというお声はあります。もう一点は、仮にその民生委員自身が動けないときに、やはりその間、かわりがすぐいるわけではない仕組みの中で、この必要性、自己負担でいいものかと問われたときに、私はこれは支えるべきものの一つだと思うのですが、この点について伺いたいと思います。","respondent":"原高齢者福祉課長","answer":"そういう中で、インフルエンザ予防接種を公費でというご提案かと思います。町会活動とかさまざまなところでも区にいろいろご協力いただいているというところもございまして、そういうバランスも含めながら、少し検討させていただければと考えているところです。","voiceIndex":132,"id":"exchange-056"},{"speaker":"渡辺委員","kind":"提案","question":"ぜひご検討いただきたいと思います。そうすると、防犯の点で、万が一被害に遭ったときも、後追いもしやすくなるでしょうし、本来の目的である従事者への親しみ、そしてカード的な、名刺的なものがあれば緊急時の連絡先などの情報が提供できるのではないかという意味での写真入り名刺をこういった高齢者訪問に活用できないかという提案ですが、いかがでしょうか。","respondent":"原高齢者福祉課長","answer":"現在、民生委員に対しましては顔写真入りの身分証明書を発行させていただいているところです。委員ご提案の顔写真入りの名刺についても、安心感、信頼感といったところでは必要かと思います。少し検討させていただければと考えているところです。","voiceIndex":134,"id":"exchange-057"},{"speaker":"塚本委員","kind":"質問","question":"私からは、まず成果報告書１４２ページの親育ち支援事業。それから、２０５ページの特定健康診査等事業費。この２点についてお伺いしたいと思います。地域のコミュニティーもあって、一人の０歳、１歳、２歳児にいろいろな人がかかわっている中での育ちがあったのだという中で、０歳、１歳、２歳児に対する保育というか、養育というか、こういった部分での区の考え方をまず最初にお伺いしたいと思います。","respondent":"安井子育て支援課長","answer":"そういったところで子育てにつきましては、なるべく孤立化をさせないような形で対応していくということを行政でも支援していかなければいけないだろうと考えているところです。私どもの考えはそういうところです。","voiceIndex":137,"id":"exchange-058"},{"speaker":"塚本委員","kind":"質問","question":"これはこれで確かに重要な、本当に私なんかにとっても喫緊の政策課題というか、解消しなければいけない課題ではありますけれども、一方で、本当の意味での根本的な０歳、１歳、２歳児の教育、健全な保育、これは在宅で育てるにしても、また、保育園や、今度進むであろう幼保一体化の施設で育てるにあっても、非常に重要な考え方として、この健全な教育、保育というのですか。","respondent":"伊崎待機児童対策担当課長","answer":"私の担当する待機児童対策もその大きな柱の１つですが、それとともに、深刻な子育ての孤立化と負担感の増加にどうやって対応していくかということも含めて、今回の法の中で仕組みとしてきちんと言われておりまして、地域の子育て支援という意味合いからも。","voiceIndex":139,"id":"exchange-059"},{"speaker":"塚本委員","kind":"質問","question":"よろしくお願いしたいと思います。では、続きまして２０５ページの特定健康診査等事業費について、お伺いしたいと思います。特定保健指導ですね、健診を受けた後にさらに受けなければいけないメタボなんかの特定保健指導については、文書以外での通知が受診率のアップに有効だよというような話が出ていたかと思いますけれども、この辺の取り組みにつきまして、今、どのような状況でしょうか、お伺いします。","respondent":"榎本高齢者医療担当課長","answer":"保健指導につきましても、現在まだ低迷している状況ですけれども、より一層効果的な保健指導を実施できるように進めているところです。","voiceIndex":141,"id":"exchange-060"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私からは、成果報告書の１３６ページの児童相談事業、１４２ページの児童センター事業など、地域での子どもの見守りについてお伺いします。よろしくお願いします。個々でも、また友達関係でもいろいろ見られるということで、指導員の方々が知り得る情報も活かしていっていただきたいと思っているのが、児童センターの役割、大変重要であると捉えています。地域と学校の連携も教えてください。","respondent":"安井子育て支援課長","answer":"そこでの情報等については、大きな問題とかがあれば学校等にも連携しながら情報を伝えていっているところです。","voiceIndex":144,"id":"exchange-061"},{"speaker":"飯沼委員","kind":"質問・要望","question":"「何をすればこの問題は解決に向かっていくのか」と見通せない現状を記し、「どうか全国の方々の知恵を出し合って、解決に導く方法を考えていきましょう」と協力を求めています。この把握をされている子どもたち、そして保護者の方々への対応がどうなっているのか、また、個人情報があるにしても、保護者との情報の共有があるのかどうか、ぜひ情報提供を行ってほしいという立場で、この点をお伺いします。","respondent":"太田指導課長","answer":"いじめについて、保護者へどういうふうに情報提供をするのかというお話ですけれども、そのことにつきましては、そのいじめの件数だけで解決する問題ではございませんので、その内容につきましてもしっかり学校が把握して。","voiceIndex":146,"id":"exchange-062"},{"speaker":"飯沼委員","kind":"質問・要望","question":"具体的にどういったケアがされているのか、私も含めて周りの地域は本当に心配なのですが、これは調査とは関係ありません、どういうケアがされているのか、この一点について、お答えいただきたいと思います。","respondent":"太田指導課長","answer":"現在、調査を進めておりまして、その調査をもとに、ケアも含めまして対応しています。","voiceIndex":148,"id":"exchange-063"},{"speaker":"飯沼委員","kind":"質問・要望","question":"具体的な取り組みを。私も子どもが小学校、中学校のときにいじめに遭ったり、いじめの側に回ったり、そのとき、いち早く先生から知らせを受けて、親たちが集まって、一緒に考えました。ぜひそういった意味で親に情報を提供していただきたいのが一点です。本委員会の質疑の中で事実を明らかにしていただきたい。調査は第三者を加えて、透明性の確保をお願いしたいのですが、いかがでしょうか。","respondent":"太田指導課長","answer":"本件に限らず、子どもの心のケアにつきましては、日ごろから学校でもスクールカウンセラーを活用しております。それから、保護者に情報をしっかり提供するですけれども、提供する情報をきちんと把握して整理することも必要かと思います。","voiceIndex":150,"id":"exchange-064"},{"speaker":"原委員","kind":"質問・要望","question":"全体的に生きがいということで担当責任者として目指していらっしゃるものですとか、意気込みがありましたらお話しいただきたいということと、それから最後に１４３ページ、午前中もちょっと出ましたけれども、生活保護費のところで、実際には扶助費、私も半年余りの間に２回一般質問をさせていただいておりまして、その中で、やはりこの扶助費、それから生活保護全体の形、これは厚生労働省案ということで。","respondent":"竹田生活福祉課長、白鳥高齢者いきがい課長","answer":"こちらの事業は低所得者の方を対象に、離職者であって、就労能力および勤労意欲がある者のうち、住宅を喪失している者または喪失する恐れがある者を対象として、原則６カ月、最長で９か月間を限度として住宅手当を支給するとともに。初回のこの保証委託料の助成なんですけれども、こちらにつきましては５万円を限度ということで、実費額を助成しているものです。それから、２点目の高齢者生きがい対策事業費の中の高齢者クラブ等支援事業です。","voiceIndex":153,"id":"exchange-065"},{"speaker":"原委員","kind":"質問・要望","question":"それで実際に品川区との関係とすれば、これはやはり総合相談支援センターができるかできないかという、その辺のところかと思うんですけれども、どんな形で来るのかわかりませんけれども、もし来たときにはそれがしっかりと対応できるような体制をつくっておいていただきたいという思いと、それからその中には、先ほどちょっと午前中出たかもしれないですけれども、罰則の問題ですとか不正受給の問題。","respondent":"竹田生活福祉課長","answer":"今、まだ国の厚生労働省のほうの専門部会で検討されている最中ですが、その検討の動向を注視いたしまして、今後、国の方針を参考に、適切に対処してまいりたい所存です。","voiceIndex":156,"id":"exchange-066"},{"speaker":"金野委員","kind":"質問","question":"この就労支援に至るまでの、その就労支援ができそうな、就労支援する対象の人をやはり見きわめてお声をかけていくと思うんですけれども、その選定の仕方というんでしょうか、厚生労働省のほうからの生活保護受給者等就労支援事業というものを活用しながら多分されているだろうと思うんですけれども、幸いに品川区はハローワークを誘致いたしましたので、連携をすごくしやすいという状況の中。","respondent":"竹田生活福祉課長","answer":"生活保護の申請をされた方につきましては、面接相談員、それから担当のケースワーカー、それから就労自立支援相談員等の３者の話し合いを通しまして、ご本人に就労の阻害要因がないのかどうかということをまず確認いたします。","voiceIndex":159,"id":"exchange-067"},{"speaker":"金野委員","kind":"質問・要望","question":"見た目というのは、例えばメンタルなご病気を持っていらっしゃる方、身体的には何ら問題がなさそうに見えますが、例えば心のご病気を持っていらっしゃる方、すぐには復帰がなかなか難しいけれども、でも少しずつ頑張っていただきたいなという思いで多分お声をかけていらっしゃるんだろうと思うんですが、こういう方々のために、例えばお声をかけるときに、どのようにそちらに支援をしていくのか。","respondent":"竹田生活福祉課長","answer":"先ほども申し上げましたとおり、ケースワーカー、それから専門相談員、就労自立支援相談員が十分にお話をお聞きしまして、その方に隠れたご病気等がないのかどうかということを時間をかけてきめ細やかに対応しております。","voiceIndex":161,"id":"exchange-068"},{"speaker":"金野委員","kind":"質問","question":"きめ細やかに、そのＯＢの方が支援をしてくださっているということであります。これは東京都のほうでも、障害者職業センターというところでやっているんですけれども、この職場復帰、リワーク支援、いわゆる生活の見直し、立て直し、そして職場復帰のための訓練を行うところで、そういった活用というのはどのようにお考えになりますでしょうか。","respondent":"竹田生活福祉課長","answer":"委員のご指摘のような施設を利用するかということにつきましては、今後、国の動向や品川区の現状を踏まえまして、効果的な支援に取り組んでまいりたいと考えています。","voiceIndex":163,"id":"exchange-069"},{"speaker":"金野委員","kind":"意見","question":"こういった行政だけでやるものだけではなくて、医療機関でもやっていると。こうしたものもやりながら、このリワークという支援を病院の中でも、医療機関でもやっているというものがありますので、回り道かもしれませんが、こういうことをとることによって、確実な就労支援につながると私は考えますが、最後にもう一言お考えをお聞かせください。","respondent":"竹田生活福祉課長","answer":"委員ご指摘のとおり、求職活動ならびに就労を続けていくには、ご本人のやる気と意欲が何よりも大切です。生活保護受給者の個々の状況に応じた支援を積極的に行ってまいりたいと思います。","voiceIndex":165,"id":"exchange-070"},{"speaker":"金野委員","kind":"質問","question":"その後の状況をお聞きしたいのですが、特に建設型は３件あります中で、大井倉田わかくさ荘ですけれども、そのときにご答弁いただいた件では、やはり躯体の部分も、それからお住まいの部分も、入れかわりのときにはリフォームをする、あるいは躯体部分でも指定管理者のもと、整備をしていきますということでありますが、それとともに２階の部分がこの法人の寮になっている。","respondent":"白鳥高齢者いきがい課長","answer":"予算特別委員会でご質問のありました大井倉田わかくさ荘につきましては、現在８戸入居済みです。それから、２階のほうの法人の寮、管理人ということで、現在もそのような形でこの大井倉田わかくさ荘ではお住まいの状況です。","voiceIndex":167,"id":"exchange-071"},{"speaker":"金野委員","kind":"質問・要望","question":"空いている箇所があるので、その後はどうなっているかというふうに、今、お聞きしたんですが、ではもう少し質問を進めます。ここが空いている、法人の寮として使っているというのはわかるんですが、公共の建物として、いわゆる公共の住宅を求めている方がいらっしゃる中で、こういう空きがある。そうなったときに、この使い方、有効活用というのはどのように今後お考えなんでしょうか。","respondent":"原高齢者福祉課長","answer":"大井倉田わかくさ荘の関係ですけれども、有効に、法人の職員が災害とかそういったときにいち早く駆けつけられるという……。","voiceIndex":169,"id":"exchange-072"},{"speaker":"本多委員","kind":"質問・要望","question":"１３９ページの保育園運営費と、１４１ページのぷりすくーる西五反田運営費、１４０ページの子育て支援事業費、１４２ページ、助産師によるベビーマッサージ事業から、３点お聞きします。その点についてお聞かせください。それと、保育料の改定の考え方をお聞きします。文教委員会でしっかりと結論が出たということは伺っております。ちょっと内容について確認をさせていただきたいと思います。","respondent":"立川保育課長","answer":"負担の考え方ですが、認可保育園ですので国が基準を定めておりまして、保護者に対しての負担につきましては徴収基準額ということで、全部で８階層にわたって基準を定めております。","voiceIndex":172,"id":"exchange-073"},{"speaker":"本多委員","kind":"提案","question":"それで、この提案は今回の第３回定例会で提案がありまして、もちろんこれから手続を踏まえて区民に周知をしていくということなんですけれども、この後の第４回定例会での提案ではなかったり、このあとの第１回定例会の提案でない、早目早目に区民、利用者にお知らせをしていくというような気配りの部分がもしあれば、お知らせいただきたいと思います。","respondent":"立川保育課長","answer":"保育料につきましては、保護者の皆様におおむね６カ月ぐらい前にお知らせするということで、今回の第３回定例会のご提案ということになりました。","voiceIndex":174,"id":"exchange-074"},{"speaker":"本多委員","kind":"質問・要望","question":"質問、次に行きます。１４１ページのぷりすくーる西五反田なんですけれども、先ほどからも子ども・子育て関連法が出ていましたけれども、こちらのほうの子ども・子育て新システムと呼ばれるこの関連法案によりまして、総合こども園が廃案となり、ＮＰＯ法人への影響を区としてどう考えていくのか、支援できることをお聞かせいただきたいと思います。","respondent":"伊崎待機児童対策担当課長","answer":"これまで認定こども園という制度は４種類ございましたわけなんですけれども、この中で幼保連携型認定こども園という制度が今後大きく変わるようになります。あわせて、保育所型認定こども園というものも、公私連携型という形のものが新しく設計されております。","voiceIndex":176,"id":"exchange-075"},{"speaker":"本多委員","kind":"質問","question":"この規模とか定員とか予算とか、あと品川区がこれまでとってきた取り組みなども、あわせて影響はないでしょうか。","respondent":"伊崎待機児童対策担当課長","answer":"予算としましても年間約１億５,０００万円ほどの補助金でやってきております。そういった中で、新しい制度がどのように活かせるか、新しい仕組みとして給付の方式も変わりますので、そのあたりも見きわめながら、適切に対応していこうと考えております。","voiceIndex":178,"id":"exchange-076"},{"speaker":"本多委員","kind":"意見","question":"継続的にできることをやっていただければと思います。最後に、１４０ページの子育て支援事業費や、１４２ページの助産師によるベビーマッサージ事業で、この助産師が担う役割、費やす時間、効果、区政参画協働といった面で、予算の積算や単価の積算をどういうふうに考えていくのか。時間があまりなくてすみません。","respondent":"安井子育て支援課長","answer":"助産師によるベビーマッサージ事業は、先ほど別の委員にもお答えしたとおり、非常に重要な事業だと考えています。","voiceIndex":180,"id":"exchange-077"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１日目の続きで、国民健康保険をまずお伺いしたいと思います。平均所得ということでお聞きしたんですけれども、品川区の国保加入者の平均所得、平成元年と平成２３年がどうなっているのかを、まずお聞かせいただきたいと思います。それと二つ目は、平成２３年度という年度が国民健康保険が大きく変わった年で、保険料算定が住民税方式から旧ただし書き方式に初めて変わった年でした。","respondent":"間部国保医療年金課長","answer":"ただ一方で、この変更によりまして保険料が下がった方も一方では１万８,０００人ほどおりまして、変化がなかった方については５万人ほどです。","voiceIndex":183,"id":"exchange-078"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私はこの経過措置を少なくともなくさないでほしい。品川区の一般財源を減らさなければ続けることができるわけですから、この一般財源というのは今回初めて減らすということになっていくんだと思うんですけれども、一般財源を今までどおり投入して、少なくとも経過措置は続けていただきたいということで、２３区のところでも進めていただきたいと思うんですけれども、それが１点です。","respondent":"間部国保医療年金課長、榎本高齢者医療担当課長","answer":"第１点目のご質問であります、経過措置の終了に伴うその後のですけれども、この件につきましては、現在、国保担当課長会が２３区であるんですけれども、その中で鋭意検討しているというような状況です。１点目ですが、滞納者数につきましては、平成２４年８月末現在で７７７人です。滞納率といたしましては２％程度です。短期証につきましてですけれども、短期証の交付件数につきましては、平成２４年８月で５８件の交付をしております。","voiceIndex":185,"id":"exchange-079"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"平成１２年から原則平成１６年までに、第３期障害者福祉計画というのを立てるということが国のほうで出されていたんじゃないかと思うんですけれども、品川区はこれがどうなっているのかということが一つと、それから私は一般質問で、生活介護や就労継続支援のＢ型施設が定員を超えて、平均でも１.３倍ぐらいのところで入所をしているので、ここの施設の整備をということで求めたときに。","respondent":"永尾障害者福祉課長","answer":"第３期障害者福祉計画ですけれども、品川区の場合は長期基本計画と総合実施計画等に基づいて、障害者の施設について進めていくという考えをとっております。","voiceIndex":190,"id":"exchange-080"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今、足りているということなんですが、今でも平均１.３倍ということなので、そしてこれはすぐにできるものではないので、いつまでにどれくらいつくるかということで、計画を立ててやっていただきたいと思います。それと、マニュアルについては内部でということなんですが、計画の段階からぜひ当事者参加というところを検討していただきたいと思います。いかがでしょうか。","respondent":"原高齢者福祉課長","answer":"そういった意味では、その結果が、今、委員ご指摘の結果になっているです。サービスについても、十分な形で対応していきたいと考えているところです。","voiceIndex":192,"id":"exchange-081"},{"speaker":"西本委員","kind":"質問","question":"それを聞きます。これはどうなんですか。これが始まった当初というのは、結構高額なものであるので、それをなかなか準備できない方がいますからということでレンタル事業が始まったと思うんですけれども、時間もたっている、多少金額的にも下がっている、また使い古したもののリサイクルもでてきているのではないかと思うんですが、これの見直しというのはあるのかどうかについてお聞きします。","respondent":"白鳥高齢者いきがい課長、安井子育て支援課長","answer":"運営面ですけれども、現在、シルバー人材センターのほうに委託をしています。それと、職員については南品川シルバーセンターには１名配置していますけれども、この運営形態につきましては、このまま存続をする予定でおります。今後、大体５年間ぐらいは５台ずつ増やそうという考え方を持っていますけれども、今後のニーズを見ながら検討していきたいとは考えてあります。","voiceIndex":195,"id":"exchange-082"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、やはり改築については、そうすぐにはいかないと思いますけれども、老朽化が進んでいるところについては、計画的に長期にわたって考えていただきたいと思っています。これは私も最近よく聞いています。そういう場合、レンタルというのも出てくると思うので、ですから区がそこまでする必要があるのかなと思いますので、時期を見て見直しを図るべきものではないかと考えています。二つだけお願いします。","respondent":"白鳥高齢者いきがい課長","answer":"今後の高齢者住宅のことですけれども、今回、この大井林町高齢者住宅を開設した中で、これは一般質問でも答弁をさせていただきましたけれども、やはり、今現在自立で入居されている方がほとんどですけれども。","voiceIndex":198,"id":"exchange-083"},{"speaker":"西本委員","kind":"質問","question":"児童センター運営費のほうに入ります。これはいつまでするんでしょうか。ですが、やはり協働ということの事業の中で自立しているので、もうよろしいんじゃないのかなと思うんですが、それについてのご意見をお聞きします。青少年委員と児童センターとの連携というものも考えているというのがあるわけですけれども、具体的にはどのようなことを拡充という意味で考えられているのか、お聞きします。","respondent":"安井子育て支援課長、梶青少年育成課長","answer":"児童センターの運営ですけれども、平成２３年度、あり方検討委員会を行いまして、やはり午前中とかについては在宅子育てについて、先ほど子どもさんも非常に増えているというところなので、非常に重要な意味を持っているだろうと。ちなみに平成２３年度の実績は１４の児童センターで行いまして、平成２４年につきましても、今のところまだ半年ですけれども、もう９館で実績があるという形で、今後も進めてまいりたいと思っているところです。","voiceIndex":200,"id":"exchange-084"},{"speaker":"西本委員","kind":"質問・要望","question":"その辺の見きわめをしていただければと思います。その中でやはり運営をするには、毎回言っていますけれども、職員の増員という形はぜひともしていただきたい。保育園のところに取られたりとかして、いろいろされているようですが、そうではなくて、きっちりと児童センターの中での職員増という形でぜひ実現していただきたいと思いますので、その件に関してのご意見をお聞きします。","respondent":"安井子育て支援課長","answer":"職員の増員ですけれども、今はやはり在宅子育ての部分が非常に重要な位置を占めておりますので、やはり保育園からの経験者を異動させて、そちらでスキルを、急にはなかなかスキルをつけられませんので、新採を採ってもなかなかそこら辺の対応はできませんので。","voiceIndex":203,"id":"exchange-085"},{"speaker":"浅野委員","kind":"質問","question":"行旅死亡人の人数８名と出ておりますけれども、実際に年度によって違うんでしょうけれども、発見された数と亡くなった数というのは違うと伺っておりますけれども、過去３年ほど、こちらのほうのデータについて教えていただければと思います。この中には行旅病人、病気で品川区内で倒れられたという方も考慮されているふうに伺っておりますけれども、こちらの人数についてお伺いします。","respondent":"竹田生活福祉課長","answer":"過去３年間の数字ですが、平成２１年度が取り扱い件数９件、平成２２年度が５件、平成２３年度が８件となっております。ほとんどのケースがお亡くなりになられたのが発見されたというケースです。","voiceIndex":206,"id":"exchange-086"},{"speaker":"浅野委員","kind":"質問","question":"病人の方はちょっと数に入っていないということだと認識をしておきますが、この場合、亡くなった方については、区のほうで葬祭業者に委託されていると聞いておりますけれども、その葬祭業者は入札か何か、どのように決めているのかということと、あと、単価契約なのかどうなのか、そこら辺の内容と金額についても教えてください。","respondent":"竹田生活福祉課長","answer":"こちらの事業で取り扱っております件数は、今、手元にあるのは平成１６年度以降の数字ですが、いずれも１０件以下の数字となっております。","voiceIndex":208,"id":"exchange-087"},{"speaker":"浅野委員","kind":"質問","question":"この費用の内容ですけれども、葬祭をする費用ですから火葬にすると。は保管ですか。そちらのほうも含まれているというふうに聞いておりますけれども、どのような内容かということと、あと、例えば火葬した後に遺族等で引き取り手が現れた場合にはどのような対処をされるのか、遺骨という形でお渡しするのか、またこれにかかった費用はその遺族が払うのかどうか、教えてください。","respondent":"竹田生活福祉課長","answer":"お亡くなりになられた遺骨ですが、所定の委託している先に保管していただきまして、遺族がいらっしゃった場合には引きとっていただいているです。申しわけございません。先ほどご報告漏れました入札の単価ですが、１体当たり１７万３,９００円となっております。","voiceIndex":212,"id":"exchange-088"},{"speaker":"浅野委員","kind":"質問","question":"１体当たり１７万３,９００円ですと、平成２３年度８名亡くなっていて随分な額になるかと思うんですけれども、この額で合っているとは私は到底思えないんですけれども、後で教えてください。単価のほうをやはり教えていただければと思うんですけれども、こちらのほうにつきましても行旅死亡人と同じような形で、競争入札で区のほうでやられているのかどうか、教えてください。","respondent":"竹田生活福祉課長","answer":"ご遺族等がいらっしゃらない方あるいは引き取り手のいらっしゃらない方につきましては、公費のほうで負担しておりまして、ほとんどのケースが社会福祉法人のほうで行いまして、その遺骨を管理しているという状況です。","voiceIndex":214,"id":"exchange-089"},{"speaker":"浅野委員","kind":"質問・要望","question":"この中で、社会福祉法人に委託をしているということですけれども、これは品川区が決めているのか、それともほかの例えば都とかそちらの上のほうで決めているのか、この件について教えていただきたいんですが、同じような競争入札であれば、単価は行旅死亡人と同じようなレベルなのかどうかということについて、この件についてはお伺いしますので、こちらのほうはご答弁をいただきたいと思います。","respondent":"竹田生活福祉課長","answer":"それ以外、そういった特殊な事情があるものが各葬祭業者１件、２件と積み重なって約１割ございまして、残りの大多数のものにつきましては、先ほど申し上げた社会福祉法人のほうで処理しております。","voiceIndex":216,"id":"exchange-090"},{"speaker":"浅野委員","kind":"質問","question":"最初のほうの行旅死亡人のほうの単価がわからないので、多分単純に計算するとかなり安いんじゃないかなと私は見てわかるんですけれども、社会福祉法人のほうは金額がたしか３,０００万円ほどで百数十人ですから、単純な割り算をすると結構高いなと思っているんですけれども、もし内容が同じであるならば、これも生活福祉課のほうでやられているのであれば。","respondent":"竹田生活福祉課長","answer":"こちらにつきましては、単価のお話ですが、この扶助費の単価というものが定まっておりますので、そちらの範囲内で支出しております。こちらの扶助費の一つとして扱われておりますので、ほかの扶助費と同様に、４分の３は国の負担、４分の１は自治体の負担となっております。","voiceIndex":218,"id":"exchange-091"},{"speaker":"浅野委員","kind":"質問・要望","question":"質問が前後しましてちょっとごちゃごちゃになってしまいましたけれども、やはりこういう契約については、同じような契約があるのであれば、できるだけ安いほうに合わせるという努力はしていただきたいと思います。税金ですので、区が払うのか、都が払うのかはまた別といたしまして、この件については検討していただきたいと思います。ご答弁があるのであればお願いします。","respondent":"竹田生活福祉課長","answer":"すみません。先ほど誤ってご報告しました行旅死亡人の単価のほうですが、平成２３年度は５万１,４６８円です。","voiceIndex":220,"id":"exchange-092"},{"speaker":"松澤委員","kind":"質問・要望","question":"４点お聞きしたいと思います。３点目、１３７ページ、ＡＥＤ設置費助成について。４点目、１４３ページ、生活保護費、ジェネリック医薬品についてお伺いしたいと思います。１番目のことですけれども、メゾン琴秋、これは６月議会の中で、和解ということで専決処分の報告があったんですが、これは改めてどういうような和解内容なのか、そしてそれに至る経過というものをお知らせしていただきたいと思います。","respondent":"白鳥高齢者いきがい課長","answer":"したがいまして平成２４年３月３１日までということで、区の提案といたしましては、この契約期間２０年間を１０年間に変更、また家賃のほうなんですが、近傍の同種の家賃を参考にいたしまして、また調査した結果６万５,０００円ということで。","voiceIndex":223,"id":"exchange-093"},{"speaker":"松澤委員","kind":"質問","question":"この内容ですけれども、近傍家賃と比較して６万５,０００円まで家賃を下げてくれという交渉の中で、これは全体家賃が１０２万７,０００円と聞いておりますけれども、これは単純に計算しますと７万９,０００円になるんですけれども、いろいろな諸費用が入っているので、大体７万３,０００円ぐらいなんでしょうか。これを６万５,０００円に下げてくれ。この辺を詳しくお願いします。","respondent":"白鳥高齢者いきがい課長","answer":"こちらにつきましても、この２０年間の契約の中でも、やはり契約期間を１０年間に短縮ということで、そのときにも減額率４％ということで、これはその当時の近傍同種の家賃を参考にということで、今回のメゾン琴秋につきましてもやはり調査をした結果ということで。","voiceIndex":225,"id":"exchange-094"},{"speaker":"松澤委員","kind":"質問","question":"契約期間２０年。これは高齢者住宅ですから中に高齢者が入って、それをまた介護度が高い方がいらっしゃるので出すわけにいかないという思いはあるんでしょうけれども、やはりその中でもしっかりとした契約をしていただかないと、お上だから、自分たちの腹は痛まないからというのでは困るんですよ。ここは高齢者の話ですからちょっと款がずれますけれども、区民住宅だってありますよね。","respondent":"白鳥高齢者いきがい課長","answer":"これから最終的には、今現在では平成３２年というところで最終契約期間が切れる住宅があります。これまで４棟ありますけれども、その中でもしっかりとその辺のところは見きわめながら判断をしていきたいと考えています。","voiceIndex":227,"id":"exchange-095"},{"speaker":"松澤委員","kind":"質問・要望","question":"次に行きます。家具転倒防止対策助成について。これは６月補正の中で、助成がつかない一般の方にもＰＲするチラシとかのぼりとかをつくっていただきました。９月補正の中でも拡大されているということで、これは大変にすばらしいヒットだと思います。その辺、しっかりとつかまえているのかどうか、その点についてお聞きしたいと思います。","respondent":"白鳥高齢者いきがい課長","answer":"家具転倒防止対策事業です。８月末現在ですけれども、申込数につきましては３２３件です。そのうち非課税世帯につきましては１４９件、それから課税世帯の申込者が１７４件という内容です。","voiceIndex":229,"id":"exchange-096"},{"speaker":"松澤委員","kind":"質問・要望","question":"一般の家庭には助成がないということなので、ＰＲ活動を積極的に行っていっていただきたいと思いますし、この助成を受ける世帯、ほとんどの方は民生委員が絡んでおりますので、民生委員の負担が大きくなるかもしれませんけれども、訪ねていったときに、こういうのをやっているという形で聞いていただければまた拡大していくのかなと思っているところですので、この辺の考えをお聞きしたいと思います。","respondent":"白鳥高齢者いきがい課長","answer":"こちらにつきましては、高齢者福祉課の民生委員担当のほうとも連携をとりながら、家具転倒で大変危険な思いをされる、怖い思いをされる高齢者の方は大変多うありますので、その辺のところはしっかりとＰＲしながら、これから進めてまいりたいと考えています。","voiceIndex":231,"id":"exchange-097"},{"speaker":"松澤委員","kind":"質問","question":"了解しました。３点目のＡＥＤ設置費助成について、９４万５,０００円。これがどこかということと、ＡＥＤの単価あるいはランニングコストがどれぐらいかかるのかについてお聞きしたいと思います。","respondent":"立川保育課長","answer":"この９４万５,０００円につきましては、認証保育所の新規開設に伴って区のほうで補助いたしまして、開設時に設置してもらうということを目的にしております。単価につきましては、上限４０万円で３１万５,０００円が３つということで、計上させていただきました。","voiceIndex":233,"id":"exchange-098"},{"speaker":"松澤委員","kind":"確認","question":"聞くところによりますと、これはもう区有施設は全部ＡＥＤの設置をしたというふうにお話を聞いています。これはこの平成２３年度末で終わったということなんでしょうか。それとも平成２４年度も含めて工事をして終わるということなのか、その辺、確認をしておきたいと思います。","respondent":"江部健康課長","answer":"ただ最近リースが始まっておりますので、リースですと月７,８００円という形で、５年で４６万８,０００円という単価になります。","voiceIndex":235,"id":"exchange-099"},{"speaker":"松澤委員","kind":"質問","question":"２０８台ということは、全部ついていないということ、まだ設置していない区有施設があるということでしょうか。","respondent":"江部健康課長","answer":"基本的には全施設設置済という認識です。","voiceIndex":240,"id":"exchange-100"},{"speaker":"松澤委員","kind":"質問","question":"了としておきます。区有施設に飛んでいく。それは脈なし、呼吸なしという、けいれんしていたものですから、そのけいれんを呼吸と勘違いしたということもあるんですけれども、やはり実践的に本当に必要なんだ、これをやらなくちゃ、あるいはそのときにもし間違えたらどうしようという意識が働いてしないのかもしれないけれども、この点の訓練、品川区ではどのようにしているのでしょうか。","respondent":"江部健康課長","answer":"ただ、皆様実際に見たことがないので不安感が強いということはわかりますので、今後デモをするですとか、なじんでいただくような取り組みをしていく必要はあると認識しております。","voiceIndex":242,"id":"exchange-101"},{"speaker":"松澤委員","kind":"質問・要望","question":"本当にテレビを見てびっくりしたんですけれども、こんなことあるんだなと。学校の先生だからもし間違えたら。まちの人に聞いたら、人の命を預かるんだから怖くていじれないという声、これは誇張して言っているのかもしれませんけれども、そんな意味ではしっかりと実践的な職員の研修をしていただきたいと思います。ジェネリック医薬品は次のときにやりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":244,"id":"exchange-102"},{"speaker":"井上委員","kind":"質問","question":"私は、１３３ページの生活支援サービス、１３６ページ、重症心身障害児（者）通所施設運営費、１３０ページの高齢者生きがい対策事業費について、お伺いいたします。福祉タクシー券の申請なんですけれども、新規と継続でどう違うのか教えてください。","respondent":"永尾障害者福祉課長","answer":"福祉タクシー券ですけれども、福祉タクシー券は毎年申請された方に対して支払っているもので、継続してやっている方と新規で初めて受けることになった方といらっしゃるということの区別です。","voiceIndex":247,"id":"exchange-103"},{"speaker":"井上委員","kind":"質問","question":"心身障害者福祉タクシー事業実施要綱では、継続の方は実施要綱みなし規定として、区が審査をして郵送すると。新規の方は、障害者福祉課に来て、区長から交付が許可されているのに、どうして新規の方だけ社会福祉協議会の窓口に行かなければならないのか、その理由を教えてください。","respondent":"永尾障害者福祉課長","answer":"現状では社会福祉協議会のほうに委託して、タクシー券についてはやっているところです。新規の方と継続の方の手続の違いについては、ちょっと、今、実務的ことなので把握ができておりません。","voiceIndex":249,"id":"exchange-104"},{"speaker":"井上委員","kind":"質問・要望","question":"事務事業概要では原則郵送というふうに書かれておりますけれども、新規の方は引換券というのを窓口でいただいて、それを持っていかなければならないとなっております。ぜひ要望いたしますが、いかがでしょうか。","respondent":"永尾障害者福祉課長","answer":"この事務的な手続の点につきましては、障害者の方がより使いやすいように、社会福祉協議会と協議をして決めていきたいと考えております。","voiceIndex":251,"id":"exchange-105"},{"speaker":"井上委員","kind":"質問・要望","question":"お願いします。次は、障害者の社会参加、特に移動支援についてお伺いいたします。この中で、車いす対応の車両購入および改造助成に絞って、これから質問していきたいと思うんですけれども、この事業の開始年度と実績、実績は累計で結構ですので教えてください。その実績に対する評価をどのように考えていらっしゃるのか、お伺いいたします。","respondent":"永尾障害者福祉課長","answer":"自動車改造費助成の件ですけれども、開始年が昭和５０年になっております。","voiceIndex":253,"id":"exchange-106"},{"speaker":"井上委員","kind":"質問・要望","question":"実は、千葉県館山市では車いす対応の車両を市が所有しまして、通院等に貸し出しているという制度があります。私も実際にそういう当事者なのでそのことはよくわかりますけれども、車いす利用者の外出支援および社会参加の利便性向上を図るために、ぜひ導入に向けての検討を要望いたしますが、お考えはいかがでしょうか。","respondent":"永尾障害者福祉課長","answer":"この車いす同乗車両の助成の申請のことですけれども、これまで１年に１回広報で募集をして行っておりましたけれども、平成２４年度からは随時受付をするということにしておりますので、そういうところでこの助成金の活用の拡大を図っていきたいと考えております。","voiceIndex":255,"id":"exchange-107"},{"speaker":"井上委員","kind":"質問","question":"心身障害者福祉会館でのリフト付の２台というのは休日ではないかと思うんですけれども、そこは平日貸し出しというのもされているのでしょうか。","respondent":"永尾障害者福祉課長","answer":"２台のうち１台は毎日貸し出しをしております。もう一台のほうは土曜日、日曜日、休日、年末年始となっております。","voiceIndex":257,"id":"exchange-108"},{"speaker":"井上委員","kind":"質問","question":"そういう事業があるのであれば、周知をしていただけるようにお願いしたいと思います。昭和５０年からやってきたこの事業ですので、少しそういったところも大きく見直しも含めて検討いただければと思います。次は、重症心身障害者通所事業のピッコロについてお伺いいたします。開設されて以降の利用状況なんですが、定期利用の方とレスパイト利用の方、それぞれ対象者、登録者、利用の状況を教えてください。","respondent":"永尾障害者福祉課長","answer":"通所のほうですけれども、現在、利用者につきましては３名ということになっております。レスパイト事業については、登録者が３名で、現在２名が申請中という状況になっております。","voiceIndex":259,"id":"exchange-109"},{"speaker":"井上委員","kind":"質問","question":"レスパイト事業のほうは２名が申請中ということは、まだ利用していないということなのかどうかということと、あとまだ利用されていないので、レスパイトの方たちの送迎が要綱ではしないというふうになっていますが、まだ始まっていないのにそういう話も変ですけれども、どうしてそのようなレスパイトには送迎をしないということで要綱が定められているのかも教えてください。","respondent":"永尾障害者福祉課長","answer":"送迎につきましては、やはりいつその予約が来るかわからないということもあり、送迎車両を常時そういうふうに用意しておくということは現状なかなか難しい状況になっています。始めたのがまだ７月ですので、今後やっていく中で利用者のニーズとかも考えながら検討してまいります。","voiceIndex":261,"id":"exchange-110"},{"speaker":"井上委員","kind":"質問","question":"ピッコロの車両が外を走っているのを私は見たんですが、自前で車と運転手はいるんじゃないかなと思ったんですが、それはどこかから借りて、定期の人の利用だけをされているんですか。","respondent":"永尾障害者福祉課長","answer":"東京福祉バスのほうに委託をして、運転手と添乗員をつけて運行していただいているということです。","voiceIndex":263,"id":"exchange-111"},{"speaker":"井上委員","kind":"質問・要望","question":"まだ、始まった事業ですので、今後注目しますので、ぜひ頑張っていただきたいと思います。高齢者いきいき事業なんですけれども、高齢者いきいき事業の対象者は、区はどこら辺の年齢を想定して事業を行っているのか教えてください。","respondent":"白鳥高齢者いきがい課長","answer":"高齢者いきいき事業ですけれども、対象者は６０歳以上の区民の方ということで考えてあります。","voiceIndex":265,"id":"exchange-112"},{"speaker":"井上委員","kind":"質問","question":"２項では、適当な仕事に従事する機会やその他社会的活動に参加する機会を与えられるものとするとなっていますけれども、区としてはどのような事業を用意されているのでしょうか。","respondent":"白鳥高齢者いきがい課長","answer":"老人福祉法の趣旨ですけれども、私どものほうとしましては、主にシルバーセンターの中でのご利用、利用者ということでもって考えてありますけれども、やはり先ほども申し上げました、このいきいき事業のほうの対象者６０歳以上ということで。","voiceIndex":267,"id":"exchange-113"},{"speaker":"井上委員","kind":"質問","question":"私はこれで、シルバーセンターのみが区の施策というのは少々残念だなと考えています。元気な高齢者の技術、技能を活かした事業を興す、今、女性の企業とか品川区も支援をしておりますけれども、やはりこういった方たちの知識、技能は大変重要なものと思います。コーディネートシステムを充実して、そういったプログラムの研究をすべきと思いますけれども、お考えをお伺いします。","respondent":"白鳥高齢者いきがい課長","answer":"ご高齢の方々のこれまで培われた技術、技能等の活動ですけれども、私どものほうではやはり１つ例を挙げますと高齢者クラブ。高齢者クラブにつきましては、６０歳以上ということで、この社会貢献活動と……。","voiceIndex":269,"id":"exchange-114"},{"speaker":"高橋委員","kind":"質問","question":"よろしくお願いします。そのような中で、保育園の運営費についてお尋ねしたいんですが、さまざまな認可保育園があります。その運営実態についてお伺いしたいんですが、認可保育園も幾つかあるので、区立保育園の運営費の決算８０億円について、内訳についてお尋ねいたします。いろいろな議論があったんですが、まず、年齢別の園児１人当たりのコスト、どれぐらいかかっているのかということをお尋ねします。","respondent":"立川保育課長","answer":"８０億円ということで、区立保育園の分なんですけれども、年齢別のコストにつきまして、歳出のほうで０歳児が年間で約４１８万円、１歳児が２７６万円、２歳児が２４１万円、３歳児が１１７万円、４歳児・５歳児が四捨五入いたしまして９９万円です。","voiceIndex":272,"id":"exchange-115"},{"speaker":"高橋委員","kind":"確認","question":"そこで確認ですが、先ほどお話があった国の徴収基準額の割合というのは、５３％と先ほどお話があったと思うんですが、そちらでよろしいでしょうか。負担率が何％ぐらいかもおわかりになるならお願いします。そして、今、平成１６年のご答弁にあったような政策目標という非常に重要な発言で、６０％という割合がありますが、それは今でも変わらないのでしょうか、お伺いいたします。","respondent":"立川保育課長","answer":"川崎市につきましては、平成２４年度を含めて３年間で横浜市並みの７５％にするということで、平成２４年度から実施しております。","voiceIndex":276,"id":"exchange-116"},{"speaker":"高橋委員","kind":"質問・要望","question":"それからもう一つは運営コストをいかに下げていくかというご努力、そちらも政策目標に掲げていただいて、かつこちらもほかの委員がおっしゃっていたんですが、区政全体の行革もきちんと説明していただき、さらに専門家の諮問なり意見を聞く機会、そして区民の方のお声を聞く機会をつくっていただいて、今後の保育料を含めた保育施策を進めていっていただきたいんですが、そのあたりはいかがでしょうか。","respondent":"立川保育課長","answer":"コスト削減についての努力の目標ということですけれども、やはり公立保育園につきましては、品川区におきましてはこれまでいわゆる保育の質を確保するということで、乳幼児教育等についても力を入れてきたところですので、いわゆる質を確保しつつ。","voiceIndex":278,"id":"exchange-117"},{"speaker":"高橋委員","kind":"質問・要望","question":"そちらについては正規の職員の方も配置されていますが、業務委託という形態なんですが、指定管理者制度の導入を検討はしていらっしゃるんでしょうか。そして導入していないということは、何か児童センターにおいては指定管理者制度を導入することによるデメリットがあるのでしょうか。もしデメリットがないのならば、なぜ指定管理者制度を導入しないのかというところをお願いします。","respondent":"安井子育て支援課長","answer":"児童センターのほうで指定管理者制度の導入を検討したかどうかですけれども、指定管理者制度を導入することで、まずメリットがあるというのはやはり施設の管理、例えば維持管理の部分が、非常に大きな施設ですと機械周りであるとかそういったもの、あるいは光熱費等。","voiceIndex":282,"id":"exchange-118"},{"speaker":"高橋委員","kind":"質問・要望","question":"今、事業の中身というお話をおっしゃったんですが、委託の場合は委託の範囲内に限定されて事業を行う。その点を考慮しまして、今後、効率的運営という視点で、その光熱費云々ということだけではなくて、指定管理者の導入についてぜひ検討をしていただきたいと思います。あり方検討のほうには指定管理者という言葉が報告書になくなっていたので、そのあたり、強調して質問を終えたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":284,"id":"exchange-119"},{"speaker":"山元委員","kind":"質問・要望","question":"私は、１３１ページの高齢福祉費の中の高齢者地域配食サービス事業について、また時間があれば、次の１３３ページの移動支援事業（ガイドヘルプ）についてお伺いしたいと思います。その学校給食配食サービスを受けていた方たちの人数、それから今度それが商店街連合会の配食サービスに変わったんですが、そのときの人数を教えていただきたいと思います。","respondent":"原高齢者福祉課長","answer":"それが、平成２４年３月末の受給者ということで、お昼が４３名、夕食が３６名といった数字になってあります。","voiceIndex":286,"id":"exchange-120"},{"speaker":"山元委員","kind":"質問・要望","question":"半分ぐらい減ったという感じになると思いますが、実際この学校給食配食サービスのときの値段は幾らだったのか、またそれが今度の商店街連合会による配食サービスは幾らのものが幾らになったのか、その辺も教えていただきたいと思います。","respondent":"原高齢者福祉課長","answer":"商店街連合会のほうに委託していますけれども、利用者負担については変更がないというところでございまして、区のほうから商店街連合会に委託しているのは８００円と事務手数料ということで５０円、夕食につきましては９００円の５０円というような状況になっているところです。","voiceIndex":288,"id":"exchange-121"},{"speaker":"山元委員","kind":"質問・要望","question":"それは利用実績の低下、また民間サービスの充実などから、実施手法の見直し云々というふうになっていましたが、それなりの何か情報を得て見直しをしようとなったと思うんですが、その辺の理由も教えていただきたいと思います。それからメニューは一括して商店街みんな一緒なのか、その地域によって食べるもの、お弁当が違うのかどうか、その辺も教えていただきたいと思います。","respondent":"原高齢者福祉課長","answer":"メニューのほうからですけれども、この配食につきましては、６カ所の事業者がご協力いただいているです。そういった中では中華の事業者、あるいはお弁当屋というような形です。","voiceIndex":290,"id":"exchange-122"},{"speaker":"山元委員","kind":"質問・要望","question":"本当に、今、課長のほうから要介護云々というお話がありました。商店街連合会によってはそれが対応できているのか、その辺がちょっと気になります。やはりその辺が、外に出られないお年寄りにとってみては、やはりそこで何か今まで会話があったのがないということ、この辺は区としてはどのような対応をまた考えているのか、教えていただきたいと思います。","respondent":"原高齢者福祉課長","answer":"現在どのような形でされているかというのは、行ったときに利用者に直接手渡しと限定をしておりまして、直接手渡しができない場合については、在宅介護支援センターあるいは私どものほうに連絡が入って。","voiceIndex":292,"id":"exchange-123"},{"speaker":"山元委員","kind":"質問・要望","question":"今、本当に大事なことはやはり対話だと思います。そういう意味では、やはり区のほうでこの６カ所やってくださっているということですけれども、その辺は徹底した指導というか対話の大切さをもうちょっと重点にとっていただきたいと思っています。区としてもこれからこのような対応はできるのかどうか、その辺のご意見も聞かせていただきたいと思います。","respondent":"原高齢者福祉課長","answer":"この事業の見直しというのは、すべてが廃止ということでの見直しではなくて、そういったことを含めて、今の事業を見直してどんな工夫ができるのか、あるいはできないのか、こういった見きわめの中で最終的な結論を出していこうと考えているところです。","voiceIndex":294,"id":"exchange-124"},{"speaker":"山元委員","kind":"質問・要望","question":"移動支援事業（ガイドヘルプ）についてお伺いさせていただきたいと思います。今回この予算が２,１７８万円に対して、決算が１,６８７万円ですか。マイナス５００万円というかなり大きな額になっておりますけれども、これは１つは知的障害者の方、精神障害者の方が活用なさっているのかということと、この５００万円のマイナスというのはどういうことなのか、その辺を教えていただきたいと思います。","respondent":"永尾障害者福祉課長","answer":"移動支援事業につきましては、平成２３年度については知的障害者と視覚障害者に対する支援を行っているものです。","voiceIndex":296,"id":"exchange-125"},{"speaker":"山元委員","kind":"質問・要望","question":"ちょっと若干時間がないのであれなんですけれども、今、知的障害者で利用なさっている方が、何名中何名使っていらっしゃるのか、またわかれば、この自己負担がどのくらいかかっているのか、平均で結構です。教えていただきたいと思います。","respondent":"永尾障害者福祉課長","answer":"ちょっと人数については今すぐ出ないんですけれども、負担については非課税者の方については無料になっております。は１割ということです。","voiceIndex":298,"id":"exchange-126"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"その理由、もちろん入院とかいう理由もわかるんだけれども、これだけの差があるということは、どういうことが考えられるのかということを教えていただきたいのと、それから認知症サポーターが、先ほど５,４００人というお話があったんだけれども、私はこの方々を、今後しっかりいろいろな形で助けていただく方法は行政側で考えて、一緒になってこの方々とやっていくべきだと思うので。","respondent":"原高齢者福祉課長","answer":"その方が５,４００人ということで、今はその裾野を広げるというところで、今後は多くの方にこのサポーター養成講座に出ていただく中で、認知症の方を理解してもらうような取り組みをしていますけれども、委員ご指摘のとおり、このサポーターを今後の中でどう活用。","voiceIndex":301,"id":"exchange-127"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それから介護認定審査会は、これは意見だけ言っておきます。委員の方からもさまざま議論のある方の部分のところがいろいろ意見があるみたいなので、例えば委員での総会等があると思うので、その委員の方々からも十分意見を聞いていただいて、これはよりよい介護認定審査会にしていただきたいというのは要望だけしておきますので、認知症デイサービスの工夫の部分についてだけ、もう一度お願いします。","respondent":"原高齢者福祉課長","answer":"ただ、結果として利用率につながらないということは、今の方法ではなかなか進まないということになりますので、委員ご指摘のように、予約という形ではないにしても、次の方ときちんと話をしながら、この方がお休みになったら次に使えるというような工夫を各施設でできるように。","voiceIndex":303,"id":"exchange-128"},{"speaker":"南委員","kind":"質問","question":"１３９ページの保育園運営費について伺いたいと思います。長期基本計画が平成２１年から実施されているんですけれども、ここの中で子育て世帯への経済的支援を掲げておりますよね。この当時、こういう経済的支援をやるということを表明したことに、私は評価をしていたわけでありますけれども、そういう支援を掲げたその思想というのは何なのか、まず改めて伺いたいと思います。","respondent":"立川保育課長","answer":"保育園関係、子育て家庭の経済的負担の軽減ということで長期基本計画にはありまして、具体的な事業計画としましては、当時すこやか児童手当の支給、子どもすこやか医療費助成、私立幼稚園の入園料・保育料の助成、あと認証保育所保育料助成、この４点です。","voiceIndex":306,"id":"exchange-129"},{"speaker":"南委員","kind":"確認","question":"子育て家庭への負担軽減ということを確認したいと思います。そして、これは区政運営の指針だと述べているんですけれども、これからもそのスタンスでずっと頑張っていくという意思があるのかどうか、改めて伺いたいと思います。","respondent":"柏原行財政改革担当課長","answer":"これから長期基本計画の改定に向けていろいろ作業を行っていくわけではありますけれども、現在のところではそういった考え方です。","voiceIndex":308,"id":"exchange-130"},{"speaker":"南委員","kind":"質問・要望","question":"今、かなり経済不況の中で、とりわけ子育て世代の経済的な状況というのはかなり厳しいものがあると思います。したがって、ぜひ区民の実態から出発していただきたいと思いますし、これまでの長期基本計画には、先ほども申し上げましたけれども、区政運営の指針だとなっている、ここに盛り込んでいるわけですから、それは当然継続していただきたいということを強く要望しておきたいと思います。","respondent":"立川保育課長","answer":"区民の願いがどこにあるのかということと、保育料の関係ということでよろしいでしょうか。ちょっと１３９ページということで、申しわけありません。区としましては、いわゆる子育て世代の負担軽減ということと、いわゆる両立支援ということで考えてあります。","voiceIndex":310,"id":"exchange-131"},{"speaker":"南委員","kind":"提案","question":"よかった、ほっとした思いです。それで、保育料の値上げが提案されていますけれども、区の負担が７８.８％に今はなっているということです。この７８.８％になっているそこのところは、値上げの理由にしているんですけれども、なぜこんな高い状況になっているのか、まずこの数字の背景を教えていただきたいと思います。","respondent":"立川保育課長","answer":"ただ、私立保育園につきましては、国と都の分担金につきましてはそのまま継続されております。なぜこの負担割合になっているかと言いますと、国の基準に対しまして、おおむね５割以上なんですけれども、区が加算いたしまして、保育の質を高めているという現状です。","voiceIndex":312,"id":"exchange-132"},{"speaker":"南委員","kind":"確認","question":"平成１６年に国の負担金、東京都の負担金がなくなって一般財源化したということで、品川区の独自財源に頼らざるを得なくなった。保育園の保育料ですね。事実ですからそのことを申し上げているわけです。したがってその部分、非常に重たく区がどうしても負担せざるを得ないということでありますけれども、この辺について、この数字の状況について、改めて確認をしたいと思いますけれども、いかがでしょうか。","respondent":"立川保育課長","answer":"実際、今、８億円来ているということなんですけれども、そこにはいわゆる新規開設に伴う経費とかも入っておりますので、いわゆる保育所の運営費というところだけで言いますと、平成２３年度ベースでは、国と都を合わせておよそ５.７％ということで。","voiceIndex":314,"id":"exchange-133"},{"speaker":"南委員","kind":"質問・要望","question":"本会議で共産党の飯沼議員が質問をしたんですけれども、そのときにも強く国にこういう状況で求めるべきだと、財政支援をやれということを言ったのですが、区長会を通じてやっているというこのことだけで、確かにやっていますけれども、もっとしっかりと国に、本当に子どもを守る立場に立って、一般財源からきちんとした補助金に、もとのように戻すという方向で。","respondent":"立川保育課長、伊崎待機児童対策担当課長","answer":"先ほど、国に対して強く要望していくべきだですが、これまでも特別区長会を通して要望してきたところです。これからも強く要望していくというふうに考えております。いずれにしましても保育園の最低基準、今では設置認可基準ですが、こちらの基準を十分遵守いたしまして、日々の対応につきましては、園長はじめ保育士等がお子さんの育ちをきちんと保証するように保育をしています。","voiceIndex":316,"id":"exchange-134"},{"speaker":"南委員","kind":"質問・要望","question":"スペースが広がったということはあります。じゃあ、その規模に見合って、職員はどれだけ増えているんですか。子どもを豊かに育てる、健全に育てる、そういう点でどれだけの配置、この倍近くにも広がった定数、子どもの数に見合って職員が増えているんですか。そのこともあわせて教えていただきたいと思います。その点についてはどうでしょうか。これは私の意見ですけれども、先ほどのご質問をお願いします。","respondent":"伊崎待機児童対策担当課長","answer":"職員数ですが、各園の職員数は、申しわけありません、手元にはないんですけれども、職員全体の数の動きを見ましても……。","voiceIndex":319,"id":"exchange-135"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"それと２２８ページ、介護保険の中の住宅改修アドバイザー派遣等事業について、１４３ページ、生活保護費について、時間があれば１３６ページの高齢者住宅等整備費について、お伺いをします。その上で改めて質問します。この改定で０歳児から２歳児の保育料は２３区内でも最高水準並みとなるが、今後の改定においても大きく値上げをしていくことになるのか、どうバランスを考えるのか、区の考えを伺います。","respondent":"金子子ども未来事業部長","answer":"説明等についてですけれども、確かに今回、３分の１とおっしゃいましたけれども、３０％の方が結果的に対象になるという改定の内容ですけれども、私どもとしましては、もちろん全体に対しての改定ということも考えましたが、現在の経済情勢に鑑みて、比較的所得の低い層。","voiceIndex":322,"id":"exchange-136"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"今回、大幅に値上げとなる世帯は、２年前にも階層を増やしたことで値上げ対象となっている可能性もあります。こうした一連の措置が、少子化対策という視点から見てマイナスのメッセージとなってしまわないでしょうか。今後、そういったさまざまな視点を取り入れた検討を強く求めてまいります。保育園については以上です。次に、住宅改修アドバイザー派遣等事業についてお伺いします。","respondent":"原高齢者福祉課長","answer":"事務事業評価のところですけれども、この住宅改修アドバイザーと、バリアフリー住まい館のほうも住宅改修という視点で捉えてございまして、そういった意味では、バリアフリー住まい館のほうはこの３月をもって今までの役割を終えたということで。","voiceIndex":324,"id":"exchange-137"},{"speaker":"石田（慎）委員","kind":"質問","question":"住宅改修アドバイザー制度は、知識と経験を備えるアドバイザーを派遣するということになっていると思うんですが、例を１つ挙げします。この住宅改修アドバイザー制度の中に、知識と経験を備えるアドバイザーというふうに記されているのに、なぜこのような外で使うものに対して、雨の日に使用できないものを勧めるのか。この点について、区としてどのようなご見解があるかお聞かせください。","respondent":"原高齢者福祉課長","answer":"そういった意味では、一方的なご案内ということであれば、そこについては今後改めていかなくてはいけないと思いますし、こちらのほうも一級建築士とその辺については十分話をしながら。","voiceIndex":326,"id":"exchange-138"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"ぜひ高齢者のさまざまな生活場面、また福祉サービスの活用状況などを踏まえて、今後そういった配慮をしていただきたいなと。これは要望で終わります。そんな中で、その方たちは十分働くことができる可能性が非常に高いと予想される中で、そういったリーマンショック後の増加された受給者に対して、就労支援の拡充をさらにしていただきたいと思うのですが、区の考えをお聞かせください。","respondent":"竹田生活福祉課長","answer":"平成２２年度に向けましては４２９世帯増えまして４,０６３世帯となっています。次に、就労支援についてのご質問ですが、生活保護の受給を開始する方の要因の１つに、経済情勢による雇用の悪化があると考えられます。","voiceIndex":328,"id":"exchange-139"},{"speaker":"石田（慎）委員","kind":"意見","question":"ぜひ今後もしっかりと取り組んでいただければと思います。そんな中、外国人受給世帯が平成２２年には、全国でありますけれども４万世帯を超えたとのことですが、品川区の現状をお知らせください。人数と、それと国別、どの国が多いかという部分でお知らせください。","respondent":"竹田生活福祉課長","answer":"国別ということですが、韓国等が８７名、フィリピンが３８名、中国が２０名、アメリカが５名、ベトナム４名、その他東南アジアが１０名、ブラジル・中南米が６名です。","voiceIndex":330,"id":"exchange-140"},{"speaker":"須貝委員","kind":"質問・要望","question":"２１９ページの介護保険全般についてお聞きしたいと思います。品川区も今回、歳入歳出１８６億円。この現状の中、介護費用を確保し、高齢者に対する安定的な保障を提供するために、社会保障と税の一体改革の法律が制定されましたが、これが品川区に対する社会保障にどのような影響があるのか、もしわかれば教えていただきたい。実際、品川区に対してどのような影響があるのか教えてください。","respondent":"原高齢者福祉課長","answer":"大きな課題です。こういった介護、それから医療、福祉を含めて、制度が持続、継続的に安定的に運営されるというところが一番大事な要素です。そういった意味では、国を挙げてこういった制度が安定的に経営できるようにということで、こういった一体改革がなされているです。","voiceIndex":333,"id":"exchange-141"},{"speaker":"須貝委員","kind":"質問","question":"すみません。１点だけお聞きしたいんですが、よく、高福祉高負担、中福祉中負担、低福祉低負担ということがありますが、これは該当するとしたらどこに該当するんですか。それとも、今、現状のとりあえず維持できるんだという形なんですか。それともいくらかでも区民サービスがよくなるんでしょうか。","respondent":"原高齢者福祉課長","answer":"どういった負担のところで制度が維持されるかというところは、なかなか難しいところがありますけれども、まず、こういった社会保障制度の一つですから、そこに安心感がないと、区民の方が介護保険、医療も含めて使うことができない。","voiceIndex":335,"id":"exchange-142"},{"speaker":"須貝委員","kind":"質問・要望","question":"どうぞ頑張って、私は皆さんにやっていただきたいと思います。さまざまな支援もありまして、大変なことだと思いますが、よろしくお願いいたします。１年も満たないで辞めていると。今後も増える傾向なんでしょうか、減る傾向なんですか。そして将来、担っていただけるヘルパー、安定化も私は必要だと思うんですが、何か対策はしているんでしょうか、お答えください。","respondent":"原高齢者福祉課長","answer":"そういった中で、区の役割というんですか、区がどんなことを実施してきたかというお尋ねですけれども、この離職率をどう捉えるかというところとどういう対応をとるかというのは、基本的にはまず事業者が中心になってするというのが大変重要かと思います。","voiceIndex":337,"id":"exchange-143"},{"speaker":"須貝委員","kind":"質問・要望","question":"でも、これは品川区のせいではなくて、国でつくっているその介護制度によってそういうふうにある程度決められちゃっているんですが、ほとんどは国のあれなんだけれども、やはり区としても離職がないように、それで若い人が未来への希望を持てるような支援を何か、ぜひ要望しておきたいと思います。その効果というのは現実あらわれているんでしょうか。その点についてご見解をお聞かせください。","respondent":"原高齢者福祉課長","answer":"そういった意味では、この認定率は必要があって認定を受けるわけですけれども、皆さんの思いとしては、１日でも介護を受けずに今までどおりの生活ができるようにというところを求めているわけですから、そういった中で区としてはさまざまなこういった事業を展開する中で。","voiceIndex":339,"id":"exchange-144"},{"speaker":"須貝委員","kind":"質問・要望","question":"課長もご存じだと思うんですが、私の知っている方で、例えば医者に連れていく。日曜日だから、祭日だから家族と過ごしなさいといったって、自分たちは自分たちのやはりそういう生きる場所がある、生活する場所があるので、どうぞそういうのをどんどん活用していただいて、できるだけ大勢の人と接せられるような支援をつくっていただけるとありがたいと思います。これは要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":341,"id":"exchange-145"},{"speaker":"若林委員","kind":"質問・要望","question":"１２９ページの福祉人材確保・定着事業、もう一点が１３６ページの発達障害児デイサービス運営費、２点お聞きいたします。福祉人材、介護のほうでしょうか。この医療行為を行える介護職がさらに人材として必要な段階にますますなってくると思いますので、今後のこの人材の確保、また育成という観点での課題をお聞かせいただきたいと思います。","respondent":"原高齢者福祉課長","answer":"そういう中で課題と言えば、この研修を受けたいということで手を挙げている方皆さんが早く受けることによって、ご利用者への対応ができることを望んでいるところではあります。","voiceIndex":343,"id":"exchange-146"},{"speaker":"若林委員","kind":"確認","question":"老健等の施設の中では、今、できていると。それから、訪問介護のほうでは７事業所に、これはとどまっているという言い方が、現状、まだ正しいんでしょうね。それからもう一点は、この研修を受けた方、これは障害者のほうの医療ケアについては、この方は一定の障害者の特性、こういう研修とか講習を受けた人は障害者の医療ケアもできるのかどうか、このことについて確認をします。","respondent":"原高齢者福祉課長、永尾障害者福祉課長","answer":"そういった意味では、訪問事業者がこれをとる場合につきましては、東京都の決められた研修を受けるということになりますので、先ほどの課題がありつつ、ここの研修に申し込んでいただきながら対応するというようなところです。障害者に関しても、たん吸引の実施については同じようなスキームでやるようになっています。研修についても、不特定多数の者を対象にした研修、特定の者が対象の研修という形で、基本的には一緒になっております。","voiceIndex":345,"id":"exchange-147"},{"speaker":"若林委員","kind":"質問・要望","question":"ぜひしっかり取り組んでいただきたいと思います。現状、児童発達支援センター、品川児童学園のほうで、いわゆる公立保育園の巡回相談を行っておりますけれども、この体制と実態をお聞きしたいと思います。それから今後、公立保育園以外の幼稚園、私立保育園、私立幼稚園等、いわゆるこういう品川区の幼児に対するこの発達障害に関する支援、巡回相談、この考え方をお聞きしたいと思います。","respondent":"永尾障害者福祉課長","answer":"品川児童学園のほうで巡回相談をやっておりますけれども、実績といたしましては、大体月に１件から２件というような状況になっております。公立保育園、幼稚園、そして民間の幼稚園、保育園についても、依頼があれば巡回はやっております。","voiceIndex":348,"id":"exchange-148"},{"speaker":"若林委員","kind":"質問・要望","question":"そうすると特別支援教育もある。今のうちからしっかりと、私立だ公立だという縦分けではなくて、この子どもたちはたまたま私立に行っているお子さん、たまたま公立に行っているお子さんという目で、すべての品川区の幼児の障害という角度での特別な支援についての、いわゆる１つは巡回相談のあり方というのをしっかりと明確に方針を示していただきたいと思いますが、いかがでしょうか。","respondent":"永尾障害者福祉課長、立川保育課長","answer":"先ほどの説明がちょっと不十分だったんですけれども、公立の保育園については保育課のほうで巡回相談をやっておりまして、そのほかの部分については、こちらの品川児童学園ほうで巡回相談をやっているというところです。保育園におきましては、現在、小児科医と臨床発達心理士が定期的に各園を巡回しています。","voiceIndex":350,"id":"exchange-149"},{"speaker":"大沢委員","kind":"質問・要望","question":"１３０ページ、高齢福祉費、１３２ページ、障害者福祉費、そして１４３ページ、生活保護費ということで、３点お伺いいたします。最初に、１３２ページなんですが、過日、身体障害者手帳に該当しない中等度の難聴児の補聴器購入に関する助成の請願が、都議会のほうで採択されたということで情報を持っておりますけれども、この件について、区にはどの程度の情報が入っているのか教えていただきたい。","respondent":"永尾障害者福祉課長","answer":"直接的にこの難聴児に対するご要望というのは、障害者福祉課でまだ受けてはおりません。ただ、その基準に該当しないお子さんについて、補聴器を自費で払わなければならないということは、以前、ちょっとほかの場所で聞いたことはあります。","voiceIndex":354,"id":"exchange-150"},{"speaker":"大沢委員","kind":"質問・要望","question":"ほかの場所はどこだったかというのはあえて問いませんけれども、ここのところで該当しないけれども、その線上にいる方、これは支援を必要とする方が非常に多いのではなかろうかと思っていますし、ましてやこの件に関しましては難聴の子どもさんですから、その家計においてもちょうど子育て、品川区では子育て支援を存分なくやっていると思いますけれども、ちょうど家計にかかる教育費。","respondent":"永尾障害者福祉課長","answer":"ただ、やはりどこかで線を切らなければならないんだなとは思いました。やはり何デシベルというのがどこかの線でどうしても出てきてしまう。そうすると、そこにいかない方々がやはり同じように思ってしまう。なので、どうすべきかというのは非常に難しいと思いました。","voiceIndex":356,"id":"exchange-151"},{"speaker":"大沢委員","kind":"質問","question":"今、障害者福祉課長から何デシベルということでお話をいただきました。予防的なものから見たら大変重要なことだと思うんですけれども、それを受けて、またお話を伺いたいと思います。","respondent":"永尾障害者福祉課長","answer":"やはり現実、生活する上で耳が遠くなってしまうということは難しい部分が出てきてしまいますけれども、それで補聴器をつければすべて聞こえるという場合でもないとは思います。","voiceIndex":358,"id":"exchange-152"},{"speaker":"大沢委員","kind":"質問","question":"確かに財政もありますけれども、そこの部分というのは、やはり予防的観点から僕は必要ではないかと思いますので、ご検討方、お願いしたいと思います。では、次に移ります。男性の場合は６５歳以上で何がしたいか。ここで男性と女性と、団塊の世代と言いながら意識の差が出てくるわけなんですけれども、ここの意識がずれながら、今後団塊の世代を含めた高齢者施策をどのように行っていくのか、教えてください。","respondent":"白鳥高齢者いきがい課長","answer":"こういうような支援を区のほうとしても支えていきたいと考えています。","voiceIndex":360,"id":"exchange-153"},{"speaker":"大沢委員","kind":"質問","question":"わかりました。それはわかっているんです。それはわかっているんだけど、それを聞きたいのではなくて、団塊の世代は考え方が違うんじゃないですかと。その方たちを今後、高齢者いきがい課としてどういうふうに捉えていくのかということ。そのためには何を仕掛ければいいのかということをちょっとお伺いしたいと思って、質問させていただいているわけです。お願いします。","respondent":"白鳥高齢者いきがい課長","answer":"ただ、やはりその地域の中で、今、生活をされているということの中では、やはり自分一人だけで生活できるものではないということを、やはり地域からも我々区のほうからも、いろいろな機会をとらえてアプローチなり、そういったことをＰＲしていきたいと考えております。","voiceIndex":362,"id":"exchange-154"},{"speaker":"大沢委員","kind":"質問・要望","question":"持ち時間じゃ終わらなくなっちゃうので、これは本当に高齢者の方の地域参加を活発にするということは、私は一般質問でもお尋ねをさせていただきました。次は変わります。１４３ページの生活保護費です。先ほど来、何回か出ています不正受給ということですけれども、これは確かにマスコミで面白おかしく取り上げられた部分もあります。以前にも伺いましたけれども、改めて教えていただきたいと思います。","respondent":"竹田生活福祉課長","answer":"そういったものが未申告になっておりますので、そういったものを私どもは不正受給と呼んでおりますので、今後就労収入があった者、あるいは年金収入、遡及年金等で臨時に収入があった者、ほかにも生命保険等の給付、交通事故や災害の補償金、あるいは離婚の慰謝料。","voiceIndex":364,"id":"exchange-155"},{"speaker":"大沢委員","kind":"質問・要望","question":"セーフティーネットですから、これは本当に困っている方には厚くやっていただきたいし、やはり不正に関しては厳正に対処していただきたいと思いますが、ちょっと時間もなくなっちゃたので、最後にこの点については論点が４つぐらいあると僕は考えております。要は給付の形とかあり方、そしてチェックの仕方。しっかりとやっていただきたい。以上を希望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":366,"id":"exchange-156"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1360#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":113312,"voices":367}},{"id":"h24-20121005-4","meetingId":"h24-c-settlement","date":"2012年10月5日","dateIso":"2012-10-05","committee":"決算特別委員会","time":"午前１０時００分～午後５時３１分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を160件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"○午前１０時００分開会 ただいまより決算特別委員会を開きます。 それでは、平成２３年度品川区一般会計歳入歳出決算","agenda":"○午前１０時００分開会 ただいまより決算特別委員会を開きます。 それでは、平成２３年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"沢田委員","kind":"質問・要望","question":"成果報告書の１５４ページ、生ごみ処理機普及事業、１６０ページのバンコクビジネスサポートセンターと、同じく１６０ページのＩＳＯ認証取得経費助成についてお伺いさせていただきたいと思います。来年度の予算でも、一応６０台を予定しているみたいですけれども、今までこの助成は何台されて、また、この事業をどう分析されているのか。ごみ減量にどう役立っているとお考えでしょうか。","respondent":"太田品川区清掃事務所長","answer":"私から、生ごみ処理機にかかわるご質問にお答えいたします。実績ですけれども、ここ５年ぐらいでよろしいでしょうか。","voiceIndex":4,"id":"exchange-001"},{"speaker":"沢田委員","kind":"質問","question":"その辺の必要性について、そういった仕組みをつくるとか、そういったことは考えられているのでしょうか。","respondent":"太田品川区清掃事務所長","answer":"いろいろな手段を使いながら、周知をまず努めていきたいと、こういうふうに考えているところです。","voiceIndex":6,"id":"exchange-002"},{"speaker":"沢田委員","kind":"質問","question":"わかりました。次へ行きます。１６０ページのバンコクビジネスサポートセンターのほうですけれども、これは現在の状況と、また、期間長く入っているところもあるかと思うので、その辺の状況と、また、バンコクへ定着、どの程度会社が出ているのかという成果等を教えてください。","respondent":"福島ものづくり・経営支援課長","answer":"タイのバンコクにありますビジネスサポートセンターですけれども、現在の状況ということで、実はこちら、ビジネスサポートセンターは、平成２２年１１月に設置しまして、それから現在まで至っております。その間、全部で６社ほどが利用されております。","voiceIndex":8,"id":"exchange-003"},{"speaker":"沢田委員","kind":"質問","question":"この事務事業評価でも、これは事業運営に当たり、より効果的、効率的な手法を検討するということであるんですけれども、こういった効果的、効率的ではなかった部分がどういうところであって、これからどう改善をされていくのでしょうか。","respondent":"福島ものづくり・経営支援課長","answer":"といいますのも、こういったサポートセンターは区が１カ所持ちますと、やはりそこはランニングコストが重なりますので、現地のスタッフですとか、現地の会社をうまく利用して、こういったサポートセンター的な動きをできないかということで、今、検討しています。","voiceIndex":10,"id":"exchange-004"},{"speaker":"沢田委員","kind":"質問・要望","question":"次は、１６０ページのＩＳＯの認証取得助成のことでお伺いしたいんですけれども、この事業のそもそもの意味と、助成の理由、またこの制度で利用した企業数も、長くやられているかと思うんですけれども、何社ぐらいこの制度を利用されたでしょうか。","respondent":"福島ものづくり・経営支援課長","answer":"利用者数ですけれども、平成２３年が６社、平成２２年が１７社、平成２１年が１２社ということでの利用です。ただ、最近多いのが、ＩＳＯの９０００シリーズの品質管理ですとか、あるいは情報管理、そういったものに多く集まっている傾向があります。","voiceIndex":12,"id":"exchange-005"},{"speaker":"沢田委員","kind":"意見","question":"これもまた事務事業評価がＣで見直しになっているんですけれども、そもそも区内の中小企業の本当にＩＳＯの認証取得というのは、信用力を高める標準規格ということで、結構大変な経費がかかるわけですけれども、この助成をもってしても中小企業が取得するのは大変難しい制度であったかと思うんですけれども、事務事業評価では、一定程度完了したことを踏まえると。","respondent":"福島ものづくり・経営支援課長","answer":"こちらのＩＳＯの取得支援事業ですけれども、先ほど言いましたように、四つの種類について現在助成していますけれども、特に、年によっても違うんですけれども、環境シリーズが結構行き渡って取得している企業が多いということで少なくなってきたりですとか。","voiceIndex":14,"id":"exchange-006"},{"speaker":"沢田委員","kind":"質問・要望","question":"お話しされたように、そんなに経費がかからないんですけれども、やはり企業としてはこういった区内の中小企業の競争力を高めるという意味でも、こういった制度というのはどうしてもやっぱり利用したい企業も多いと思いますし、ＩＳＯまでとらなくても、企業に応じた認証制度があるので、ぜひともこういった形のいろいろな新しい認証制度に対しても助成の対象を広げていっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-007"},{"speaker":"鶴委員","kind":"質問","question":"１４５ページ、衛生費ということで、難病対策、また啓発事業ということに関してお尋ねしたいと思います。長期基本計画を見ましたら、区民の健康づくりを支援する、疾病等対策を充実する、地域の医療体制の充実をするというふうにありますけれども、こうした施策の啓発事業というもので、主なものはどういったものがあるか教えてください。","respondent":"福島荏原保健センター所長","answer":"難病対策については、一般に皆さんに周知する方法としては、まず、講演会をやっております。それから、一番主なものは、難病の医療費の助成というところかと思います。","voiceIndex":18,"id":"exchange-008"},{"speaker":"鶴委員","kind":"質問","question":"難病だけではなくて、いわゆる全体としての啓発がどれだけあるのかなと、そこのところも知りたかったんですが、わかりました。今言っていただいた難病の部分なんですが、難病の中で白血病があります。こうしたところの数字というか、そうした方の把握というのは、区としても行っていくものなのかどうか、この辺を教えてください。","respondent":"江部健康課長","answer":"骨髄バンクの件ですけれども、国といたしまして、方針といたしまして、できるだけ骨髄バンク登録事業を進めるという基本計画は出ておりますけれども、自治体で数字を押さえるというふうにはなってございません。","voiceIndex":20,"id":"exchange-009"},{"speaker":"鶴委員","kind":"質問","question":"自治体では押さえないということで、では、区としては、その数字的なところはわからないということであると思いますけれども、ただ、先ほど啓発のところで難病については講演会等行われているということも含めて、１人でも多くの方がこういう骨髄移植を受けられる機会をたくさんつくるということで、骨髄バンクへの登録の推進運動、これは各地で行われていると思いますけれども。","respondent":"江部健康課長","answer":"現在のこの骨髄バンク、ドナー登録の啓発につきましては、国のほうから登録カードの配布というもので区に一定枚数来ておりますので、区役所の健康課なり、各保健センターのほうで、窓口に置いてあるという形ですので、特に啓発の取り組み、講演会をするですとか。","voiceIndex":22,"id":"exchange-010"},{"speaker":"鶴委員","kind":"提案","question":"わかりました。窓口に、たしか黄色いカードだったですか、あれが置いてあるということかなと思いましたけれども、わかりました。その上でまた提案でありますけれども、ぜひ品川区としても骨髄バンクの登録の推進の啓発事業として提案させていただきたいものがあります。品川区の都市像の中に、みんなで築く健康福祉都市とこうあります。","respondent":"江部健康課長","answer":"委員から今ご紹介にありました「ＩＭＡＧＩＮＥ９.１１」というものについては認識しておりませんでしたので、ちょっと確認させていただきたいとは思います。現在のところ、今、大々的にＰＲをというご意見でございました。","voiceIndex":24,"id":"exchange-011"},{"speaker":"鶴委員","kind":"質問・要望","question":"１４８ページの妊婦健康診査であります。事務事業概要の数字の確認等をさせていただきたいんですが、申請の数は、いわゆる出産前の申請について、申請内訳のところに妊娠届出と、それから多産児、これを足した数がいわゆる出産前の申請であるということなのかということと、それから、出産後とありますけれども、これは１回も健診を受けていない可能性もあるということなのかどうか、この辺を教えてください。","respondent":"江部健康課長","answer":"届出数と申しますのが、内訳ですので、全部含めて３,９３０ということで、多産児等は含まれるものだと思います。","voiceIndex":26,"id":"exchange-012"},{"speaker":"鶴委員","kind":"質問・要望","question":"あわせて、今、品川区は１４回公費助成していただいて、これは本当にすばらしいことだと思います。そのときにもらうつづりなんですけれども、１回目、それから２から１４回目という形で分かれると思うんですけれども、この辺の単価、検査項目によってそれぞれの検査ごとに金額は違うと思うんですが、大体のアベレージというか、平均的な金額を１回目と２から１４回目でわかれば教えていただきたいと思います。","respondent":"江部健康課長","answer":"１４枚の妊婦健診ですが、１枚目が８,４６０円でございまして、２回目から１４回目が５,１６０円ということで、１回目はちょっと高めになっているというものです。","voiceIndex":31,"id":"exchange-013"},{"speaker":"鶴委員","kind":"質問・要望","question":"これも概算なんですけれども、３６週以降というのは週１回の健診が必要ですよというふうにたしかなっていると思います。そうすると、大体４枚のつづりが残っているという考え方になると思うんですが、でも、大体いろいろあって二、三枚ぐらいなのかなと思うんですけれども、この残った受診票の取り扱い、これについては現在どういうふうになっているのか教えてください。","respondent":"江部健康課長","answer":"１４枚、お一人お一人が持つわけですけれども、すべてを使い切る方は少のうございまして、予算も平均でお一人１０枚という見込みでやっております。実務上も大体そのぐらいで、もっと少ない方もいらっしゃいますが、余す方が多い実態があります。","voiceIndex":33,"id":"exchange-014"},{"speaker":"鶴委員","kind":"提案","question":"私、ここのところに期待して、ぜひ今ご答弁いただいたような目的があるんですけれども、この余った部分のつづりの運用について、例えばご答弁いただいたような形で、もちろん運用についてはきちっとルールをつくる必要はあると思うんですけれども、その残ったつづりをまさに経済的支援につながるような形で有効活用ができるような仕組みづくり、これをいわゆる五者協。","respondent":"江部健康課長","answer":"先ほど申しました目的が妊婦の健康状態の保持と、お子様の安全な出産ということを事業目的としておりますので、区のほうでということではなく考えなければいけないことかなというふうに考えます。","voiceIndex":35,"id":"exchange-015"},{"speaker":"鶴委員","kind":"提案","question":"今、課長のご答弁だと、提案をしていただけるというふうに受けとめたいなと思うんですけれども、区としては当然限界があるのはわかっています。もちろん方向性とかを協議するのが五者協ということも存じ上げておりますので、ぜひここはさまざまな角度があると思うんですけれども、積極的に提案をしていただきたい、このように思いますので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":37,"id":"exchange-016"},{"speaker":"鈴木（博）委員","kind":"質問","question":"私は、成果報告書のページ１４６の定期予防接種、任意予防接種、それとページ１４７の女性の健康診査についてお伺いいたします。第一に、定期予防接種、任意予防接種についてなんですが、初日の歳入に引き続いて、まず不活化ポリオワクチンについて質問を続けたいと思います。平成２４年８月２日以降生まれたお子様は、新四種混合ワクチンの対象になります。","respondent":"伊津野保健予防課長","answer":"三種混合ワクチンの三者協の価格ですが、７,００４円となっております。新しい四種混合ワクチンにつきましては、まだ三者協の値段が示されておりません。ただ、つい先日公表されましたワクチンの原価から類推しますと、１万２,０００円を少し超えるものと予想されます。","voiceIndex":39,"id":"exchange-017"},{"speaker":"鈴木（博）委員","kind":"質問","question":"ここは９月から１０月に打ち始めた三種混合ワクチン７,０００円、それとあと新しいイモバックスが１万１,１００円で行われて、この組み合わせも同時並行で進められていくことになるわけですが、当然新しい、前回の補正予算は、このＤＰＴとイモバックスの高いほうの組み合わせで設定されると思うんですが、新しい１１月から始まりますので、この平成２４年度の一般会計補正予算分のうち。","respondent":"伊津野保健予防課長","answer":"委員ご指摘のように、補正予算を組む段階では新四種混合の接種の開始時期および価格が決まっていなかったため、この方たち、１,２００名もイモバックスとＤＰＴの三種混合を打つ予定として計上しております。","voiceIndex":41,"id":"exchange-018"},{"speaker":"鈴木（博）委員","kind":"質問","question":"ということは、生ポリオは怖いということで接種を控えていた膨大な層という方たちがいらっしゃるので、その部分が加わったので、今回の補正予算は膨れ上がったという理解でよろしいのでしょうか。","respondent":"伊津野保健予防課長","answer":"この約７,０００名のうち接種を控えられた方というのは、約半分の方、その対応として補正予算を組んでおります。","voiceIndex":43,"id":"exchange-019"},{"speaker":"鈴木（博）委員","kind":"質問","question":"結局、不活化ポリオの現在使われているイモバックスという単独ワクチンは、新しい新四種混合ワクチンが登場するまでのＤＰＴだけを行った患者に対するつなぎのワクチンとして登場したものでありまして、ポリオのワクチンをつける非常に高価なつなぎの、役割以上でもなく、以下でもなく、今回の補正では２億円以上かかっておりますが、あくまでもこれ。","respondent":"伊津野保健予防課長","answer":"四種混合ワクチンが普及していけば消えてなくなってしまうワクチンであります。したがいまして、今回、２億円以上という莫大な補正予算を組んでいただきましたが、四種混合が定着していけば、これは数千万円におさまるというふうに考えております。","voiceIndex":45,"id":"exchange-020"},{"speaker":"鈴木（博）委員","kind":"質問","question":"定期接種と任意接種についてお伺いいたします。もともと１９４８年につくられた予防接種法では、ワクチンは罰則つきの義務接種でありました。任意接種はＨｉｂワクチンほか３万９５１件で、１億４,３５９万円の支出となっております。そこでお尋ねします。平成２３年度のＨｉｂワクチン、小児用肺炎球菌ワクチン、子宮頸がんワクチンの接種数と接種率をご提示ください。","respondent":"伊津野保健予防課長","answer":"小児用肺炎球菌ワクチンにつきましては、接種数は１万３４件で、接種率は約８５％であります。子宮頸がんワクチンにつきましては、接種数は３,９５２件で、接種率につきましては、中学生が約４０％、二十歳の女性に関しましては約２０％の接種率となっております。","voiceIndex":47,"id":"exchange-021"},{"speaker":"鈴木（博）委員","kind":"質問","question":"Ｈｉｂワクチンと小児用肺炎球菌ワクチンがそれぞれ８５％以上と接種率が上昇しているのは、これは関係者のご努力の結果として非常に喜ばしい限りですが、しかし、残念ながらこの数字ではまだ完全に細菌性髄膜炎を制圧することはできません。次に、子宮頸がんワクチンについて伺います。現在、使用できる子宮頸がんワクチンは２種類あります。その種類と区別を簡単にご説明お願いいたします。","respondent":"伊津野保健予防課長","answer":"もう一つは、平成２３年８月から発売開始になりましたガーダシルというワクチンでありまして、これは前述のＨＰＶの１６型、１８型のほかに、子宮頸がん以外の病気に有効な６型と１１型についても有効なワクチンであります。","voiceIndex":49,"id":"exchange-022"},{"speaker":"鈴木（博）委員","kind":"質問","question":"子宮頸がんは、我が国では年間１万２,０００人の女性が発病し、２,５００人の方が亡くなっている女性のがんでは乳がんに次いで２番目に多い病気であります。特にＨＰＶの１６型と１８型が主な発癌の原因ウイルスとされております。現在、２３区のうち子宮頸がんワクチンが区民の負担なしで全額公費負担、無料でできる区は幾つぐらいあるのでしょうか。ご質問します。","respondent":"伊津野保健予防課長","answer":"子宮頸がんワクチンを全額補助している区は、２３区中２０区であります。","voiceIndex":51,"id":"exchange-023"},{"speaker":"鈴木（博）委員","kind":"質問","question":"子宮頸がんワクチンが極めて高額な費用なこと、既にほとんどの区が全額補助に踏み切っていること、接種を受ける女性自身だけでなく、次代の品川区民を守るワクチンであること、接種を受けることが検診と並んで非常に重要ながん対策になること、国からの臨時補助金も出て、平成２４年度からは財調にも組み込まれるとお聞きしたんですが、改めてこの子宮頸がんワクチンに対する接種率の低さについて。","respondent":"伊津野保健予防課長","answer":"従来、任意予防接種につきましての助成額は、おおよそ半額程度ということで整理されていることなのですが、この接種率につきましては低いものだというふうに考えております。","voiceIndex":53,"id":"exchange-024"},{"speaker":"鈴木（博）委員","kind":"質問","question":"苦しいご答弁をありがとうございました。では、次に、ページ１４７の女性の健康診査についてお伺いしたいと思います。成果報告書によれば、女性健診は平成２３年度では、２,３４３人が受診し、２,０６３万円が計上されております。女性の健康に配慮した非常にすばらしい施策だと思われるのですが、受診数が少ないように思われます。区の見解はいかがでしょうか。","respondent":"江部健康課長","answer":"低いかどうかということについて、現在のところ、積極的にＰＲということをしている事業ではございませんが、いろいろなところでの受診機会が多い方等々ありますので、その方たちの分を差し引きますと、このぐらいなのかなという認識です。","voiceIndex":55,"id":"exchange-025"},{"speaker":"鈴木（博）委員","kind":"確認","question":"これは非常にすばらしい制度ですので、国保基本健診のときに行ったような、それほどでもなくてもよろしいのですが、十分な意欲的な広報をもって、品川区民の若い女性が健康を守るために、この無料の健康診断があるということをお知りになって、受診されて自分の健康を確認されるという、そのプッシュというものを区のほうにもお願いしたいと思いまして、質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-026"},{"speaker":"向委員","kind":"質問","question":"二十歳以上は２０歳だけということなんですが、その２０歳という年齢が選ばれた理由と、そもそもこういった子宮頸がんワクチンというのは、若ければ若いほど、性交渉を経験する前がいいと言われていますが、もっと上限というのは、大体何歳ぐらいまで有効と考えられているのか、そのあたりをご説明いただけませんでしょうか。","respondent":"伊津野保健予防課長","answer":"もう一つの質問で、何歳まで子宮頸がんワクチンを打っても有効なのかという質問につきましては、確かに中学生が効率的にはいいんですが、その後も全く打っても意味がないというわけではなく、学会のほうでは、４５歳まで打っても有効であるという見解を出しております。","voiceIndex":59,"id":"exchange-027"},{"speaker":"向委員","kind":"質問・要望","question":"もうワクチンを助成してもらえないというか、打つにはちょっともう今、出おくれた感があるような年代の私たちにとっては、子宮頸がん、それでもこうやって大人になって社会人になったとは言っても、子宮がん検診というのはなかなか勇気がいるものだという声を周りからもちらほら聞いているんですけれども、現行、今、品川区で進めている、区内の診療機関で受けられる子宮がん検診の具体的な内容というか。","respondent":"江部健康課長、坂上品川保健センター所長","answer":"痛みというお尋ねでは、やはり体に、臓器に触れますので、痛みはあるだろうと思われます。済みません、痛みはないそうです。失礼しました。子宮頸がんの細胞診に関しましては、本当にちょっと触れる程度なので、痛みは伴わず、本当に視診を含めて１分かかるかかからないかぐらいと自分の経験からは。","voiceIndex":61,"id":"exchange-028"},{"speaker":"向委員","kind":"質問","question":"区の先ほどの数からすると、それよりもやっぱり低いという印象を受けるんですが、原因としては、子宮頸がんの検診の重要性をどこまで若い年代の人たちが理解しているかというのと、やっぱり検診の受けづらさ、受診の時間とかの制限とかもあるでしょうし、働いている方、あと、そういった心理的な恐怖心とか、あとは、中にはやっぱり配偶者の方とか、パートナーが。","respondent":"江部健康課長","answer":"この精度につきましては、検査結果が区に戻ってまいりますので、私どもと区の医師会のメンバーの皆様方との精度管理を検討する打ち合わせ会等で、その実績、検査のあり方などを検討しつつ、少しずつ改善を行っているところです。","voiceIndex":68,"id":"exchange-029"},{"speaker":"向委員","kind":"意見","question":"お尋ねしたかったのは、見落としがあるのかどうかとか、そこら辺だったんですが、聞いたところによると、２割から６割ぐらいがやっぱり見落としがあるというところも、そういうデータも出ています。","respondent":"江部健康課長","answer":"現在行っている細胞診検査に加えてということで、ＨＰＶ（ヒトパピローマウイルス）の検査方法の導入につきまして、国の検討会で検討が続けられてきたところですが、先だって国のほうで一定の方向性が示されまして、このＨＰＶ検診につきまして。","voiceIndex":70,"id":"exchange-030"},{"speaker":"向委員","kind":"質問・要望","question":"わかりました。やっぱり私が今日申し上げたいのは、女性の心理的な検診に対する恐怖とか、心理的な痛みとか、やっぱりありますし、そういった予防に、検診への財政的なことで、例えば出雲市については、３０％ほど検診の費用を削減できたとかというデータが出ているんです。では、あと２分ぐらいなんですが、廃棄物対策費に関連して、小型家電リサイクルについてもお尋ねしたいと思います。","respondent":"太田品川区清掃事務所長","answer":"品川区の場合は、３０センチ角を超えたものは粗大ごみとして収集しています。それ以外のものについては、陶器、ガラス、金属ごみという形で、小物については収集しています。小物の部分については、清掃一組の京浜島の不燃ごみ中継センターへ行きます。","voiceIndex":72,"id":"exchange-031"},{"speaker":"向委員","kind":"意見","question":"今、携帯だと１トンから金が４００グラムほどとれるというデータが出ているようで、こういった都会の中にもいっぱい、普通の金鉱石だと１トンから３グラムしかとれないんですよね。なので……。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":74,"id":"exchange-032"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私からは、１４７ページの成人歯科健診について伺いたいと思います。今回のこの成果報告書では、健診を受けた方が２,１７７人ということですけれども、この対象者数は何人で、経年的に見て、この健診をされた方の推移はどういうふうに変わってきているのか。それと、健診を受ける年齢層、品川区は４０歳からですけれども、これが特徴があれば教えていただきたいんですけれども。","respondent":"江部健康課長","answer":"年齢的には、４０歳から７０歳、ほぼ均一化しておりますが、一番多いのが４０歳と７０歳後半ぐらいです。","voiceIndex":76,"id":"exchange-033"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"品川区は、４０歳からということで、５歳刻みと今ありましたけれども、なぜ５歳刻みなのかなというところで、私は１年ごとでもいいんじゃないかな、してほしいなと思っているんです。ですから、やはり成人歯科健診であれば、二十歳からこれを、前回の質問でもさせていただいたんですけれども、二十歳から始めていただきたいなと思うんですけれども。","respondent":"江部健康課長","answer":"対象年齢のことです。なぜ５歳刻みなのかということですが、まず基本は、国が４０歳、５０歳、６０歳、７０歳を対象としているということがございまして、これに品川区では、４５歳、５５歳、６５歳を追加する形で実施しているものです。","voiceIndex":78,"id":"exchange-034"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"こういった経済理由、また労働環境のもとで、国民も区民も、いろいろわかってはいるけれどもなかなか行けない、わかっているけれどもお金がない、こういう状況があると思うので、こういった生活状況の変化に合わせて健診も改善していくべきだと思うんですけれども、改めて二十歳から、そして１歳刻みで進めていくということを求めたいと思うんですけれども、いかがでしょうか。","respondent":"江部健康課長","answer":"若い方につきましてですけれども、やはり啓発が大事だと考えておりまして、今、区の職員を見ましても、昼休みに歯磨きをするというのは普通になってきていること、それから、歯科診療所でも、定期的に年１回、２回の健康診査のために歯のチェック。","voiceIndex":80,"id":"exchange-035"},{"speaker":"石田（ち）委員","kind":"質問","question":"６.４６％。やっぱり体の健康を保っていくというところで、今も言いましたけれども、全身の健康と関連していると思う人が９５％もいる中でですので、財政の問題とも言いましたけれども、では、この３万３,７１４人が全員受けたら、どれぐらいの予算がかかってくるのでしょうか。","respondent":"江部健康課長","answer":"１回の健診でおそらく６,０００円台だったと思いますけれども、それに人数を掛けていただければと思います。失礼しました。単価は４,５９０円でございました。失礼いたしました。約１億５,０００万円。","voiceIndex":82,"id":"exchange-036"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"やっぱり歯が歯周病から全身の疾患に、心臓疾患にもかかわってくるということが前回の質問でも、私、させていただいたんですけれども、もっと早くから知っておけばよかったという４０代、５０代、６０代の方は本当にたくさんいるんです。ですので、やっぱり早い段階からこういった啓発、そして認識していくということが必要だと思いますので、引き続き私はこの歯科健診の拡充を求めていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-037"},{"speaker":"渡辺委員","kind":"質問・要望","question":"成果報告書１５３ページ、リサイクル推進費の資源回収事業、特に資源持ち去り防止対策で伺いたいと思います。大きな活動の二つである集団回収あるいは行政による回収、この辺の品目の区分け、すみ分け等は、改めて確認ですが、徹底できているかどうかをまず一つ目。気持ちの問題、モチベーションの問題もあるかと思いますが、損失額というのは、算定というか、推計はあるものなのでしょうか。","respondent":"太田品川区清掃事務所長","answer":"私のほうからお答えをします。１点目ですけれども、資源回収と集団回収との品目の区分けですが、集団回収のほうで共通していますのは、古紙、瓶、缶、ペットボトル、それから拠点で行っています古着、こういったものは集団回収でも実施しております。","voiceIndex":86,"id":"exchange-038"},{"speaker":"渡辺委員","kind":"確認","question":"今いろいろお話しいただいた中で、結構、現場確認ができている３５件、これは本当に効果といいますか、努力の成果だと思われます。ただ、本当に制度、仕組みの中で、品川区が条例改正をしての罰則規定導入が平成２０年７月というものだと思いますが、ここで伺いたいのは、罰則規定が防犯につながるという意味でも、罰則は、他自治体もこういった取り組みが日本全国いろいろあるかと思います。","respondent":"太田品川区清掃事務所長","answer":"あくまでも私どもに対して、パトロールのとき……。それから、警察との連携ですけれども、年３回一定期間、２週間程度期間を決めて、警察官と一緒に同乗していただいてパトロールを実施している、こういう状況です。","voiceIndex":90,"id":"exchange-039"},{"speaker":"阿久津委員","kind":"質問","question":"二つ目は、衛生費全体でＡＥＤについて伺います。１点目の品川保健センター管理運営費なんですが、先日、北品川にお住まいの方で、体が動かしにくくなる難病の患者の方からお話をちょっと伺ったんですが、これからその話をする前にちょっとお伺いしたいんですけれども、難病の関係というのは、定期的とか、何か決まった形で保健センターに伺う、そういう機会はやっぱり多いものなのでしょうか。","respondent":"坂上品川保健センター所長","answer":"難病の申請のために定期的にこちらのほうに来所していただいております。","voiceIndex":93,"id":"exchange-040"},{"speaker":"阿久津委員","kind":"質問","question":"私も行ったんですが、健常者であれば何ともなく出入りできるんですが、杖で本当に一歩一歩よろめいて歩くような難病の方だと、また足の悪い方だと挟まれてしまって本当に怖い、転倒してしまったりするということもありまして、実はほかの方からもこういう話を伺いました。","respondent":"坂上品川保健センター所長","answer":"それらを除いてしまうのはちょっと困難ではありますが、今、委員言われたように、手すりなどを動線上の全部につけることは難しいとは思いますが、可能な限りのことは対応させていただきたいと思います。","voiceIndex":95,"id":"exchange-041"},{"speaker":"阿久津委員","kind":"確認","question":"今、ちょっと議場からも声が上がったんですけれども、ありがとうあります。２点目です。衛生費全体、ＡＥＤについてお伺いします。もし把握されていればなんですけれども、それ以外で区内の一般企業とか、駅舎とか、コンビニとか、そういうところでどれぐらいＡＥＤを設置しているのか、もし把握をしていればその二つを確認のために数字を教えていただければと思います。","respondent":"江部健康課長","answer":"そういった形で載せます。ただ、平成１９年４月以前の区のものが載っておりませんので、中を調べますと、区のものが１２０個ありましたので、それ以外で９０個ぐらいありますので、区内全体で５００個弱のＡＥＤが設置しています。","voiceIndex":97,"id":"exchange-042"},{"speaker":"阿久津委員","kind":"提案","question":"この近くだとどこなのかと消防隊員の方に聞かれたんですけれども、駅なのか、コンビニなのかということで、なかなか我々も把握していないということで、これは日常的に防火防災管理者ですから押さえておかなければいけないんですが、昨年、定例会の一般質問の中で、こういうＡＥＤを設置している外部企業に声をかけて、いざというときはご近所の方や通りがかりの方でもＡＥＤを使ってくださいよという。","respondent":"江部健康課長","answer":"広くネットワーク化みたいなことというご意見ですけれども、企業にとっては社会貢献をしているというメッセージを送れるいい機会であるということからも必要性は認識しておりますけれども、どのような団体で、どのような手法でということについて、今、研究中です。","voiceIndex":99,"id":"exchange-043"},{"speaker":"阿久津委員","kind":"質問・要望","question":"調査研究中ということでした。先ほど、社会貢献という言葉がありましたが、品川区内にはＣＳＲ協議会があります。定期的に区と連絡協議も行っていらっしゃるので、そういう社会貢献がそもそもの目的だと思いますので、これもお願いベースで、もちろんボランティア精神ということなんですけれども、ぜひお声をかけていただきたいと思いますが、このところをちょっとご意見をいただけますでしょうか。","respondent":"江部健康課長","answer":"やはり使用実態を考えますと、要は、事務所的、内部の方、特別な、一般の方が入りやすいようなところでないクローズされているビルもあるとは思いますので、そのあたりは、その事業者との調整といいますか。","voiceIndex":101,"id":"exchange-044"},{"speaker":"阿久津委員","kind":"質問・要望","question":"最初の１行だけ読みますと、東京都品川区は、１０月１日に、今後１年以内に起業予定か、起業して５年以内の女性を対象にビジネスプランの募集を始めたということで、これは入賞するとどういう特典があるのか、また、昨年のグランプリ、どういう事業だったのか、また、この昨年グランプリをとられたところがどれぐらい現在事業展開をされているのか、まだ１年ですからどこまでかわかりませんが、その辺。","respondent":"福島ものづくり・経営支援課長","answer":"特に昨年といいますか、今年なんですけれども、今年の３月に第１回は行いました。そのとき募集して集まったのが８１件ほどございました。大体区内からの応募がその４分の１を占めているというものです。","voiceIndex":103,"id":"exchange-045"},{"speaker":"阿久津委員","kind":"質問・要望","question":"我々も紹介をしたんですけれども、ただ、ここにいらっしゃる議員の中でも、もしかしたら、理事者の皆さんはもちろんご存じかもしれないんですが、こういうグランプリの仕事の内容まではご存じない方がやっぱり多いのではないのかなと、山田副区長も写真に載っていらっしゃいましたけれども、恥ずかしい話ですけれども、私もその方とお話をして初めて、実は私のこういう仕事というのは。","respondent":"福島ものづくり・経営支援課長","answer":"優勝者等につきましてのＰＲ、アピールですけれども、徐々に進めていきたいと、いろいろな手段をとりたいというふうに考えてあります。","voiceIndex":105,"id":"exchange-046"},{"speaker":"藤原委員","kind":"質問・要望","question":"１５０ページ、大井保健センター、１５１ページ、温暖化対策事業、１５８ページ、武蔵小山創業支援センター、１５９ページ、プレミアム付商品券、１６０ページ、海外進出推進事業についてお伺いします。というのは、これだけ続けていると、インパクトが少なくなってきているんじゃないかと。それと、海外なんですけれども、区内企業にとっては、どういうメリットがあったか、実績を教えてください。","respondent":"川島大井保健センター所長、米田商業・観光課長、福島ものづくり・経営支援課長、野呂瀬環境課長","answer":"乳幼児健診等の母子保健の件数も少しずつ増加しておりますし、窓口にいらっしゃる方も。あわせまして、ずっと売っているわけではございませんで、４カ月ということで、一旦途切れるというようなこともありまして。武蔵小山創業支援センターでの事業についてお答えします。片やアメリカとか中国も、全地球のＣＯ２の３０％、４０％、ほとんどのところが中国、アメリカで出されている。","voiceIndex":108,"id":"exchange-047"},{"speaker":"藤原委員","kind":"質問・要望","question":"大井保健センター、本当に頑張ってください。品川区の税金を使って４分の３は品川区外の方にやっている。これも品川区の心が広いと思うんですけれども、この目的というのは、やっぱり品川区の商店街なり、まちの活性化なりというのに寄与していただきたいと思うんですが、その辺については改めてまたどうですか。海外については１点、改めて今後の展望と方針について、区の見解をお伺いします。","respondent":"米田商業・観光課長、福島ものづくり・経営支援課長","answer":"そういった中では、この区の規模において、３億円、３億円というのは、ある程度、２３区におきまして、金額としては大きくやっているというふうに自負していますので、今後また検討させていただきたいと思います。海外の展望ですけれども、現在はタイを中心に支援を行ってありますけれども、他の東南アジアの地域でもかなり新興国が出てきてありますので、そういった動向は見ていきたいというふうに考えていますが、どういった支援をするか。","voiceIndex":113,"id":"exchange-048"},{"speaker":"山内委員","kind":"質問","question":"１５７ページ、観光アクションプラン、観光についてちょっと伺いたいと思います。これ、僕らはいいですよ、僕らは何となく人が確かに行くところだからというのはわかるんだけれども、ただ、区外から来る人、観光ガイドマップというイラストマップを見て、なんで斎場が載っているんだと思うんですけれども、こういった感覚というのは、僕ちょっと疑うんですけれども、どうなんでしょうか。","respondent":"米田商業・観光課長","answer":"区内でまちめぐりをする方もあわせていろいろ見られるような、あとは、外からいらっしゃる方もというようなことでつくっているわけですけれども、その辺の中身については、観光協会のガイド、案内の委員会でいろいろ議論して決めて、今回のマップは。","voiceIndex":118,"id":"exchange-049"},{"speaker":"山内委員","kind":"質問・要望","question":"観光案内所移転経費、これが１１９万何がしという金額で決算額として出ている。これは平成２３年７月から、「しなかんＰＬＡＺＡ」という形で場所が移転した、その費用ではないかなと思うんですが、７月のオープンだと、ここの、例えば移転経費は出ているけれども、運営経費といったものは、この平成２３年度では、品川区としては補助していないというか、お金を出していないということでいいんですか。","respondent":"米田商業・観光課長","answer":"お尋ねの件ですが、観光案内所移転経費の二つ上に、観光タウン・コーディネーター経費ということで、こちらが観光協会のスタッフのいわゆる人件費等になっているものです。","voiceIndex":120,"id":"exchange-050"},{"speaker":"山内委員","kind":"質問","question":"そうすると、これは平成２４年度の予算にちょっと触れてしまうんですけれども、２,２００万円余の予算を計上して、今、運営しているということです。ということは、単発で１０回イベントを行いました、それが実績としてあらわれていますというようなことで考えてしまうと、私は、だったら品川の観光とこの程度で言えるのかなということを疑問に感じるんですけれども、そのあたりはいかがでしょうか。","respondent":"米田商業・観光課長","answer":"それ以外に観光協会独自で、特に今年度、延べ日数としましては、スタッフの勤務日数としては倍増していますので、そういった中で独自の、特に今年度、船を使っての事業を充実させていこうという中では、夏休みにも数回事業を実施していますし、また、冬に向けても自主事業。","voiceIndex":122,"id":"exchange-051"},{"speaker":"山内委員","kind":"質問","question":"そうすると、自主事業の数といったものは年々増えているのか、今年、平成２４年度は、どれぐらいのイベントを予定しているのか教えてください。","respondent":"米田商業・観光課長","answer":"これまでいわゆる観光タウン・コーディネーターのときは、しながわ観光協会が大井一丁目共同ビルに出ていって、その運営だけでも手いっぱいの部分がありましたが、今年度は専門的知見を持ったスタッフも迎えておりまして。","voiceIndex":124,"id":"exchange-052"},{"speaker":"山内委員","kind":"意見","question":"今、旅行業の話が出ました。これまで、ちょっとその辺は認識がないのでごめんなさい、わからないんですが、その旅行業をとることで、イベントの数を増やすことができる。ソフトでやっていくのは難しいと思う。でも、最後にそこの部分で、いま一度意気込みというか、今後どのようにしていきたいかというのを我々にももう少しわかりやすく示してほしいんです。よろしくお願いします。","respondent":"米田商業・観光課長","answer":"ソフトの充実というのはご指摘のとおりだと思います。そういった意味で、観光協会のみならず、他の旅行関係団体等も含めて、観光情報の発信と、それから、いわゆる旅行の企画等での充実を図ってまいりたい、このように考えてあります。","voiceIndex":126,"id":"exchange-053"},{"speaker":"中塚委員","kind":"質問・要望","question":"私からは、１４６ページの予防接種費、１４７ページの健康診査費について、三種予防接種の無料化、あと、若者健診の実施を求めて質問したいと思います。これまで区は、任意接種は一部自己負担だと立場を崩しておりませんが、任意接種だとなぜ一部自己負担なのか、私は子育て支援と位置づけてワクチン接種を希望する方の負担を無料にすべきだと思いますが、改めて伺います。","respondent":"伊津野保健予防課長","answer":"品川区におきましては、任意予防接種につきましては、あくまでも法律に基づく接種ではないという立場から、自分で判断し、区はそれに対しての助成を行うという判断でこれまで行ってきておりました。","voiceIndex":129,"id":"exchange-054"},{"speaker":"中塚委員","kind":"質問・要望","question":"妊婦健診も、当初２回が１４回に増やして、あとエコなどをプラスしたり、実質自己負担は無料をしてきました。なぜこの三種ワクチンは一部負担のままですが、何が違うのか、子育て支援としてしっかり位置づけて無料化を進めるべきだと思いますが、いかがでしょうか。品川区は、ほかの自治体で導入が進むこの状況をどう評価しているのか、ぜひ学ぶ姿勢をとっていただきたいと思いますが、いかがでしょうか。","respondent":"伊津野保健予防課長","answer":"繰り返しになりますが、定期予防接種と任意予防接種の区別という部分では、一部助成というものを続けています。ただ、周辺自治体の状況ですとか、ほかのさらに定期化ということも検討されている状況を考えますと、今後検討は必要かと考えています。","voiceIndex":131,"id":"exchange-055"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほど伺ったのは、子育て支援として、子ども医療費無料化や、妊婦健診の無料化は進めているわけですが、このワクチンだけは一部負担だと、何が違うのかご説明をしていただきたいと思います。私は子育ての負担をなくしていくよう充実していくべきだと思います。あわせて、若者の健診について伺いたいと思います。何をどう研究していこうと考えているのか、その中身を伺いたいと思います。","respondent":"江部健康課長","answer":"それで、一般質問でお答えいたしましたけれども、２３区の中で２０区ぐらいだったでしょうか、既に若者の健診、これは男女問わずやっていますよというご指摘がございまして、私どももその状況は認識しております。","voiceIndex":133,"id":"exchange-056"},{"speaker":"中塚委員","kind":"質問・要望","question":"予防接種につきましては、このワクチン接種、１日も早い無料化を求めたいと思います。若者の健診についてですけれども、本会議で若年層の健診のあり方については研究してまいりますと、その研究の中身を伺ったんですけれども、正直よくわかりませんでした。全体のバランスを調べるとは、どういうことなのか、改めて伺いたいと思います。","respondent":"江部健康課長","answer":"年齢ですが、４０歳以上の方につきましては、平成２０年度の保険制度改革によりまして、各保険者が責任を持つということになっておりますのと、さらにお勤めの皆様につきましては。","voiceIndex":137,"id":"exchange-057"},{"speaker":"中塚委員","kind":"確認","question":"現在、実感されている範囲で結構なんですけれども、どういうケースで健康診断を受ける機会を失っている若者がいるのか、区の認識を伺いたいと思います。自分の周りや同級生、友達を見ても、そのことは日々実感します。例えば、委託先や派遣について、健康診断の実施を行っているかどうかを確認していらっしゃるのか、あわせて伺いたいと思います。","respondent":"江部健康課長、堀越人事課長","answer":"派遣労働につきましては、委員ご指摘のとおり、基本的には労働安全衛生法上の健康診断規定がありますので、派遣元の企業が実施責任を負うということになっておりますので、そこでやられているのではないかと。希望する方は受診をしていただくことができます。それから、人材派遣につきましては、労働安全衛生の考え方につきましては、基本的に派遣元、登録されている会社の責任となっているものです。","voiceIndex":139,"id":"exchange-058"},{"speaker":"中塚委員","kind":"確認","question":"はそういう実感とか想像だけでなく、アンケート調査をして、どういう状況で若い世代が健康診断を受ける機会がないのか、そこをつかむ必要があると思いますけれども、その必要性を伺いたいと思います。もちろん契約上に法令遵守という言葉は入っていると思いますが、これだけ若い世代の健康診断の機会が奪われている中で、契約上もしっかり確認をすべきだと思いますが、改めて伺います。","respondent":"江部健康課長、堀越人事課長","answer":"さまざまな機会を捉えながら、若者の健診機会が果たして奪われているのかどうかということについて検討させていただきたいと思います。派遣、それから契約、委託等に関してですけれども、私のほうから答弁しますが、労働安全衛生の考え方、これにつきましては、労働安全の関係法令に伴って適切に対応していることですので。","voiceIndex":142,"id":"exchange-059"},{"speaker":"中塚委員","kind":"質問・要望","question":"若い世代が健康診断を受けている機会が奪われている、その状況をしっかりとまず把握をしていただいて、とりわけ今の仕組みの中では、失業状態になると、仕組み上も健康診断を受ける機会はありません。失業状態の若い世代の健康診断の実施を改めて求めたいと思いますが、失業についてに絞ってご答弁いただきたいと思います。","respondent":"早津健康福祉事業部長","answer":"実態の調査、実態の調査ということを盛んに委員のほうでおっしゃいますけれども、自分の状況がどうして生じたのかというようなことを実態を正確に把握するというのは、非常に難しい面があろうかというふうに考えておりますので、研究をします。","voiceIndex":145,"id":"exchange-060"},{"speaker":"塚本委員","kind":"質問・要望","question":"私のほうからは、初めに、成果報告書の１５０ページ、不妊治療助成事業につきまして、それから１５８ページ、１６０ページの武蔵小山とか西大井、天王洲の創業支援の関係についてお伺いしたいというふうに思います。","respondent":"江部健康課長","answer":"件数につきまして、平成２３年度４６９件とございましたが、前年、平成２２年が４７７件、平成２１年が３６９件、平成２０年が３２８件、平成１９年は２９３件ということで、着実に上昇してきておりまして、ニーズは高まっていると認識しております。","voiceIndex":148,"id":"exchange-061"},{"speaker":"塚本委員","kind":"質問","question":"ニーズが非常に高まっているという中で、この平成２４年度の予算で行きますと、微増ですか、若干増えているかなという感じに予算が組まれているかと思いますけれども、なかなか区民のニーズに応じて予算を拡大していくというのは、なかなか他の予算の関係もあるし、厳しい財政状況の中で難しい状況もあるかと思うんですけれども、一方で、平成２４年度の事務事業評価を見ますと。","respondent":"江部健康課長","answer":"実際に妊娠に結びついた数を把握している数字ですが、平成２３年度が１０８組、平成２２年度が９９組、平成２１年度が９２組とあります。","voiceIndex":150,"id":"exchange-062"},{"speaker":"塚本委員","kind":"質問・要望","question":"私自身も実はこういう経験をしておりますけれども、何年間かにわたってちょっとやったりしたことがありましたけれども、正直言うと、さまざまな治療とか、さまざまな病院がありますけれども、なかなかここがこうだからというはっきりとしたものにつながらなくて、やってみなければわからないみたいな世界が非常にあるのかなという中で、この事業の効果を検証しながらということでは。","respondent":"江部健康課長","answer":"申しわけございません、勉強不足でございまして、東京都の制度については認識してございませんでした。委員ご指摘の部分を含めまして勉強させていただきたいと思います。","voiceIndex":152,"id":"exchange-063"},{"speaker":"塚本委員","kind":"質問・要望","question":"実施の方法ということで行きますと、一律、効率的、効果的な運営にということで見直すというようなことでなっておりますけれども、これはこういった創業支援絡みの事業が一律というか、こういう形になったことについて、もうちょっと具体的な説明をいただきたいと思います。","respondent":"福島ものづくり・経営支援課長","answer":"こうした導入したときに、指定管理者制を導入するかどうか、公の施設ですので検討しました。その際はまだ創業支援というものが区としては取り組んだばかりなので、なかなかノウハウも確立できていないということもございまして、区の直営事業として進めてまいりました。","voiceIndex":154,"id":"exchange-064"},{"speaker":"塚本委員","kind":"質問・要望","question":"その中でですけれども、武蔵小山につきまして、多少今までも質問等出ていたかと思うんですが、インキュベーションルーム、８部屋ばかり貸しているところがあるかと思いますけれども、あそこのスペースが、やっぱり使い勝手という部分ではちょっと狭いところがあって、２部屋ぐらい合同で使ったほうがいいんじゃないかというような場合が希望としてあったりするんじゃないかと思うんですけれども。","respondent":"福島ものづくり・経営支援課長","answer":"確かに狭い部分はありますが、ただ、施設自体が非常に狭い施設ですので、いかんともし難いところがあります。二つ利用したいという声もありますけれども、ただ、ほかにも借りたいという方がたくさんありますので、その辺はよく調整していきたいというふうに考えてあります。","voiceIndex":156,"id":"exchange-065"},{"speaker":"稲川委員","kind":"質問","question":"初めに、平成２４年度の予算において、私のほうから、羽田空港国際化に対する対応についてご質問させていただいて、その中のご答弁の中で、外国からの来街者で、特に中国、それから台湾、香港、韓国からの飛行機を使っての来街者に対して、広く品川区の魅力を発信していくことでということで、日本航空の機内誌、品川の特集を４ページ組み込まれたとそのときお伺いいたしました。その反響がいかがだったのか。","respondent":"米田商業・観光課長","answer":"「伝統の技と味／しながわ展」ですが、こちらについては、平成２３年度については、平成２４年１月２８日、２９日、きゅりあんの７階、イベントホールで行いまして、約６,０００人の来場者がございました。","voiceIndex":159,"id":"exchange-066"},{"speaker":"稲川委員","kind":"質問・要望","question":"もし品川区単独開催が無理であれば、ここの決算書にも書いてあるように、広域観光まちづくりの観点から、大田区と連携して、品川・大田伝統工芸展なるものを開催してもいいのかなと、私は意見としてお伝えさせていただきたいのですが、区の思いはどういう思いですか。","respondent":"米田商業・観光課長","answer":"羽田空港のディスプレイについては、非常にディスプレイする値段が高いということで、大田区も、その効果についてどうなんだというようなことがちょっと話題になっているということは聞いてありますが、そういった意味では、やはり今。","voiceIndex":161,"id":"exchange-067"},{"speaker":"稲川委員","kind":"質問","question":"さっきの質問の中で、中国とか台湾、香港、韓国という近隣アジアなんですが、ご存じのように、非常に外交上も厳しいような状況の中で、さらにおそらく旅行客が減少するのではないかと私は思っております。その中で今まであまり出ていなかったんですが、例えば、欧米諸国にもそういった観光誘致に対して対象を広げてもいいんじゃないかなと思うんですが、いかがでしょうか。","respondent":"米田商業・観光課長","answer":"確かに旧東海道筋なんかは、むしろ欧米圏の方のご来訪も多いというようなことで伺っておりますので、その辺も視野に入れながら、伝統工芸に関しては、やはり国がどこであろうと、興味は若干違うとは思うんですけれども。","voiceIndex":163,"id":"exchange-068"},{"speaker":"稲川委員","kind":"質問・要望","question":"ぜひ進めていただきたいと思いますので、お願いいたします。実際に羽田空港でどれぐらいの外国人が入ってきたのか、どこを目的としているのかというデータをお持ちなのかどうなのか、やっぱりそういうものは調べていく必要性があると思いますが、いかがでしょうか。","respondent":"米田商業・観光課長","answer":"広く羽田ということですと、データというものはとれますので、その辺のところは数字を見ながら考えておりますが、外国の方はたしか１万人弱ぐらいの来訪者だったというふうに認識しています。","voiceIndex":165,"id":"exchange-069"},{"speaker":"稲川委員","kind":"質問・要望","question":"品川区全体を俯瞰したときに、例えば、大井町周辺、大崎など、ホテルが多くあります。最後に、商業・観光課から見た視点でお伺いしたいんですが、しながわ水族館についてですが、見直しという形になっております。これをやるには、まさに公園課のみならず、部課の連携でこういう財産を有効活用していかなければならないと思うんですが、その連携とかについていかがお考えか教えてください。","respondent":"米田商業・観光課長","answer":"舟運の事業等、今年度も多数実施しておりまして、その前後にしながわ水族館に寄っていただくというような企画をやってあります。今後も水族館と所管課との連携をより深めながら観光振興に努めてまいりたい、このように考えてあります。","voiceIndex":167,"id":"exchange-070"},{"speaker":"松澤委員","kind":"質問・要望","question":"２点お伺いします。一つが１５８ページの中小企業支援費、それと二つ目が１５０ページのかかりつけ薬局に関連してお伺いしたいと思います。","respondent":"福島ものづくり・経営支援課長","answer":"信用保証料ですけれども、融資を受けるときに、東京信用保証協会に保証を受ける、そのときに保証料がかかりますので、その保証料の２分の１ないし３分の２を区として補助しているものです。","voiceIndex":170,"id":"exchange-071"},{"speaker":"松澤委員","kind":"確認","question":"この保証料というのは、今の説明だけではなくて、例えばお金を借りたいと言ったときに、あなた、返せるかどうかわからないので連帯保証人をつけてくれと、それをつけられない、それではお金を借りられないというので、それについて連帯保証人にかわって保証するということなんですよね。ちょっとその辺が抜けているので確認しておきます。","respondent":"福島ものづくり・経営支援課長","answer":"中小企業の場合、なかなかそういう連帯保証人あるいは土地の担保ですとか、建物の担保、そういうものを見つけることが難しいということもありまして、こういった信用保証協会というのが全国にできてあります。","voiceIndex":172,"id":"exchange-072"},{"speaker":"松澤委員","kind":"質問","question":"金融機関が貸し出ししやすくするという考えよりも、中小企業者が借りやすくなるですよね。私は考え方としてはそっちに立ってもらいたい。借りやすくなったということだというふうに思います。例えばこれ、１,０００万円借りた場合の保証料というのは幾らぐらいなんでしょうか。もしわかりましたお願いします。","respondent":"福島ものづくり・経営支援課長","answer":"１,０００万円借りても、例えば期間ですとか、あるいはその内容ですとか、そういうことによってかなり変わってきますので、一概に幾らというのは難しいかと思います。","voiceIndex":174,"id":"exchange-073"},{"speaker":"松澤委員","kind":"確認","question":"わかりました。ちなみに、例えばこの数年間、保証料、品川区の融資制度を受けて保証を受けた方の事故があったとか、その事故率、五、六年でいいですけれども、そういうものがあったのかどうか確認をしておきたいと思います。","respondent":"福島ものづくり・経営支援課長","answer":"事故率といいます、払えなくなりますと、信用保証協会が代位弁済といいまして肩がわりします。その件数ですけれども、平成２３年が８５件、平成２２年が１０２件、平成２１年が８１件、その前の平成２０年が６２件です。","voiceIndex":176,"id":"exchange-074"},{"speaker":"松澤委員","kind":"質問","question":"いやいや、数が多いのでびっくりしました。これだけ借りていながら払えなくなっている。これは当然ながら保証協会が銀行に返済するといいますけれども、払えなかった中小企業者はその債務を負うんですよね。その関係もちょっと教えてください。","respondent":"福島ものづくり・経営支援課長","answer":"最終的に足りなくなった場合は、国等の公共機関が支援するという形になってあります。倒産した会社の債務につきましては、信用保証協会が肩がわりしますので、肩がわりしたお金は、倒産した中小企業からまた回収をしていくという形をとってあります。","voiceIndex":178,"id":"exchange-075"},{"speaker":"松澤委員","kind":"質問・要望","question":"緊急経済資金ということでしょうか。これは幾らかな。信用保証料が５億円だとか、利子補給が６億円だとか、そんなような形で大変に増えました。当然ながら、来年の３月には金融円滑化法が切れるので、これに絡んで融資制度で変わるのかなというふうに思いますけれども、鳴り物入りで今年度予算の中の中でボンと増やしたものが見直しになるのか、この辺をお教えいただきたいと思います。","respondent":"福島ものづくり・経営支援課長","answer":"融資あっせんを受けましたこうした経済対策につきましては、常に見直しが必要というふうに考えてあります。そういった意味では、例えば平成２４年につきましても、経営安定化資金というものを新しくつくりました。","voiceIndex":180,"id":"exchange-076"},{"speaker":"松澤委員","kind":"質問・要望","question":"しっかりと見直しをしながら中小企業対策をしていただきたいと思います。２点目です。かかりつけ薬局。実は今度の補正の中で、生活保護費の方にジェネリック薬を勧めるというようなことがありましたけれども、そこで質問しようと思ったんですけれども、これ、大変なことだと私は思っているんです。その前に、ジェネリックとは何かということと、よい点と悪い点がわかりましたらお教え願います。","respondent":"工藤生活衛生課長","answer":"ジェネリック医薬品は、薬の特許が切れたものということで、メリットとしては、従来の医薬品よりお安い値段でご利用できるです。患者の側からは、使用感が違うとか、今までの薬でなければ効かないという思い込みがあるという部分が問題として挙げられているところです。","voiceIndex":182,"id":"exchange-077"},{"speaker":"松澤委員","kind":"質問","question":"感想だけ言いたいと思うんですけれども、実は調剤薬局へ行きましたら、私が行ったんですけれども、メタボなものですから、３点薬を飲んでいるんですけれども、ジェネリックを勧められたんです。二つある。そのうちの、私は朝晩飲む、１日２薬飲むほうをジェネリックにしたんです。どうしようかなと思ったら、おまけがついているので買いました。これは質問ではないので、私の感想を述べさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":184,"id":"exchange-078"},{"speaker":"原委員","kind":"質問・要望","question":"私のほうからは、成果報告書の１６１ページの中小企業対策費の中で、大崎のほうのものづくり産業支援プロジェクト１,９９９万５,０００円、総務費のときにもやはり大崎のほうの産業のほうの構想検討ということで２９９万円何がしということで伺いましたけれども、いろいろな委員会でも断片的にはお聞きしているんですけれども。","respondent":"福島ものづくり・経営支援課長","answer":"ですから、３階、４階ですと、２,６００平方メートルを予定しています。３階では展示会などが行われ、また集客が見込まれるような多目的なホールをというふうに考えてあります。","voiceIndex":186,"id":"exchange-079"},{"speaker":"原委員","kind":"質問","question":"これは私の勘違いかどうかわからないのであえてお聞きしますけれども、品川という言葉が入ってきているということ自体は、やはり今後において大事な、品川区にとって、総務費のときにも申し上げましたように、場所的にもかなりいい場所でありますし、それからあとは、品川区の思い入れが入っているのかなという感じもいたします。","respondent":"福島ものづくり・経営支援課長","answer":"建築自体は再開発組合が行っておりまして、今回ここにつきます３階、４階部分の設計につきましては、今後詰めていくということで、来年の５月までに基本設計を終えようということで、現在、どういった機能にしていくか、また使い方、さらには運営方法。","voiceIndex":188,"id":"exchange-080"},{"speaker":"原委員","kind":"質問・要望","question":"何度も申し上げますけれども、このプロジェクトというか、この場所にしても、それから全体的にやはり私が思うのは、これは短期間の問題ではなくて、それこそ５０年、１００年、２００年、ちょっとオーバーかもしれませんけれども、そんな形での考え方。そういったことを考えますと、このプロジェクトというのは、しっかり腹を据えてやっていただきたいという思いが私はあります。","respondent":"福島ものづくり・経営支援課長","answer":"先ほど出ていました品川の顔になるですけれども、こちらの施設そのものは、大崎の再開発、ニューシティに始まりまして、ゲートシティ、オーバルコート、シンクパーク等、さらにはソニー等に始まりまして、再開発が進んだ中で満を持して最後にできるですので。","voiceIndex":190,"id":"exchange-081"},{"speaker":"原委員","kind":"質問・要望","question":"そうしましたら、制度的というか、形的には、ここに先ほどありましたように、一般財団法人ということですので、公益性が５０％以下でもいいということですので、しっかり、やはり品川区民、品川のファミリーだけではなくて、場所もいいことですから、それこそ東京都、それから日本全国、先端であれば世界のいろいろなところからここの施設にやってくるぐらいの意気込みを持ってやっていただきたい。","respondent":"福島ものづくり・経営支援課長","answer":"ただいまビジネスクラブ、相当盛り上がっておりまして、会員も増えております。そういった中で世界に誇れるような施設、さらには組織にしていきたいというふうに考えてあります。","voiceIndex":192,"id":"exchange-082"},{"speaker":"金野委員","kind":"質問・要望","question":"よろしくお願いします。私のほうからは、１５２ページの放射線量調査、それから１５８ページの中小企業ワークライフバランス支援事業、この二つをお聞きいたします。今後、健康被害は次に聞きますが、この測定、定点観測も含めて、放射線の測定、給食も含めて、こうしたことは今後継続をしていただきたいという要望をしたいのですが、今後はどのようにお考えでしょうか。","respondent":"野呂瀬環境課長","answer":"ですから、今後継続してはかるにつきましては、関係課とも連携して適切な対応をしてまいりたいと思います。","voiceIndex":195,"id":"exchange-083"},{"speaker":"金野委員","kind":"質問・要望","question":"ここの品川区でのお子さんへの健康診断というのは、定期的にということではなく、任意で健康診断を受けていくということになりますが、そうした放射線に限ってということではなくて、子どもの、何かいつもと違うなという症状が見えたときに、その何か違うというのは、やはり少しこの放射線というところも絡みながら、相談できるお医者さん、あるいは。","respondent":"野呂瀬環境課長、坂上品川保健センター所長","answer":"今現在、もう１年半たっていて、品川区のお子さんに対しての健康被害というのは、全く今の現在では心配することがないという……。それなりの評価も受けていると思いますし、その後、お母さんたちに何か心配なことがあるときには、電話相談などもしておりますので、そちらのほうで対応させていただきたいと思います。","voiceIndex":197,"id":"exchange-084"},{"speaker":"金野委員","kind":"質問・要望","question":"８年というのは、それはヨウ素のことだと思います。ただ、保健センターのほうでしっかりそういう相談の体制はつくってくださっている、あるいは対応してくださっているということを確認できましたので、ぜひ今後もその体制は続けていただきたいですし、また、健康診断というところでは、しっかりその気持ちを受けとめていただきながら対応していただきたいと、このように要望したいと思います。","respondent":"福島ものづくり・経営支援課長","answer":"それと、事業所内育児事業ということで、事業所内で育児ができるようにということで、それに対する支援、この三つを大きく行っていますが、その３番目の事業所内育児助成事業のほうで、整備費助成と、あとベビーシッター経費助成、この二つがあるんですけれども。","voiceIndex":200,"id":"exchange-085"},{"speaker":"金野委員","kind":"質問・要望","question":"ぜひこれからもっと皆さんにこういうものがあるということがどれだけ周知されているかなと、こういう感じがいたしますので、ぜひこの事業は、今後、仕事と家庭、両立ができる、そうしたことによって、家庭内の子育て、あるいは介護といったところにもしっかりできる、そうしたことによって、家庭の円満というところも仕事もということがありますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":202,"id":"exchange-086"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私は、１５７ページ、観光アクションプラン、先ほどいろいろ話が出ているのですが、まずお聞きしたいのは、観光とは、品川区もいろいろ集客について頑張っていらっしゃいますが、観光と集客、この関係をどのように考えているかというのを教えていただきたいと思います。","respondent":"米田商業・観光課長、野呂瀬環境課長","answer":"こうした品川の魅力を、区民に対しては地域に愛着と誇りを持ち、また、観光で訪れた方には人間味あふれる温かい交流、おもてなしを通じて、何度でも訪れたくなるようなまちづくりの取り組みというものを進めることによって。ですから、早期というよりは、それは一つのきっかけという事業で考えているところです。","voiceIndex":204,"id":"exchange-087"},{"speaker":"石田（秀）委員","kind":"質問","question":"観光のほうから行きます。イベント型で行くというと、これでは数が少なくて、もっと頻繁にやらなくてはならないだろうし、では、ファサード整備型というのは、これは相当商店街の個人の店の方の負担も出てくるわけで、それを腹くくってどうやっていかなくてはならないというのが、これは相当お店の方々にも影響があるわけですね。それから、シンボル施設はどうしていくんだ。","respondent":"米田商業・観光課長、野呂瀬環境課長","answer":"今ご指摘ありましたように、イベントや、あるいは街なみ、それから情報発信というものを織り交ぜながら区内の観光情報を発信していくという、今一番まず、イベントも大事だと思いますけれども、情報発信という面では。ただ、この省エネ設備導入助成、いわゆる温暖化に対する資金の助成につきましては、ここ３年間やってまいりましたけれども、３年間で大分製造コストが下がってきた、いわゆる補助金を差し上げてきたものより下がってきたということで。","voiceIndex":207,"id":"exchange-088"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"観光は本当に大変だと思いますので、今、会議にも参加してと、もちろんのことだけれども、やっぱりバックアップがどこかに、やっぱりこれぐらい一緒になってこうやるよというところがないと、私はなかなか、先ほど言ったやれることというと、そういういろいろ集めたツアー系しかできないのかなと、ちょっと寂しい思いもするけれども、あとは地域の中で我々も相当言っていきますけれども。","respondent":"片田都市環境事業部長","answer":"そういう当初行政が旗を振る部分としての税の使い方、インセンティブを与えるというところがありましたけれども、今委員がおっしゃられたような、個人の財産への支援というところも一方でありますので、バランスをとって見直したい、このように考えております。","voiceIndex":210,"id":"exchange-089"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"東京都は、毎年２万世帯ずつこの太陽光エネルギーを増加させていくという、そして国も大幅な太陽光のエネルギーを導入を目指していくという、こういう方針だということで、ここにも書かれていますし、品川区も率先して進めるということでここに書かれているわけなんですけれども、この実態がどうなっているのかということについてもお聞かせください。","respondent":"野呂瀬環境課長","answer":"実態ですけれども、今後も家庭部門につきましては、それぞれの家庭の中で、今申し上げたような理由で、区が補助を見直していろいろな形で進んでいくものということと、もう一つは、先ほど言いましたとおり、今後の国の方策等も今。","voiceIndex":213,"id":"exchange-090"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう中に太陽光発電、たかだか２００件じゃないですか。実際に太陽光発電はそれだけではとてもつかないので、私は本当につけたいと思う方がどんどんつけられるような、そういうために品川区が補助をして、そしてぐっと後押しをして、再生可能エネルギー、自然エネルギー、これを爆発的に増やすという、そういう対策こそ、そういう姿勢こそ品川区に求められていると思うんですけれども、いかがでしょうか。","respondent":"野呂瀬環境課長","answer":"先ほど、再生可能エネルギーの促進は進めますと申し上げましたけれども、区の方針としましては、当然一般財源で税金を投入するわけですから、それを太陽光を設置するご家庭に補助金がどれだけ効果が、その設置された方からどれぐらい区のほうに。","voiceIndex":215,"id":"exchange-091"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これを通年にして、今までの助成をぜひとも続けていただきたいということを求めたいと思います。それが１点です。そういうところで福祉避難所としての機能もすごく上げることができるので、ぜひとも品川区の施設、どこにどれくらいつけることができるのかというのを徹底して調べていただいて、つけられる限り太陽光発電をつけていくという姿勢で取り組んでいただきたいと思うんですが、いかがでしょうか。","respondent":"野呂瀬環境課長","answer":"その意味で、当然、区の施設につきましても、可能な限り、太陽光パネル、太陽光発電の設備は、関係所管と協議しながら、今後も可能な限り設置していく、その方針は変わりはございません。","voiceIndex":217,"id":"exchange-092"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひとも自然エネルギーを飛躍的に進めていただくように、助成の充実を強く求めたいと思います。ということで、子どもたちの集まるところ、遊ぶところ、そういうところをぜひともまた品川区が定期的にはかっていただきたいと、ホットスポット測定をしていただきたいと求めたいんですが、いかがでしょうか。","respondent":"野呂瀬環境課長","answer":"昨年そういうお声があって、１,１４１カ所調べました。下がっている、下がっていないというよりも、その当時も安全な値だったと。今現在も安全な値だったです。ですから、安全な値、いわゆる基準値以下であったですので、今後もそのような形で対応していきたいと考えています。","voiceIndex":219,"id":"exchange-093"},{"speaker":"西本委員","kind":"質問・要望","question":"その後に、１５９ページの商店街ステップアップ支援事業についてお聞きします。それがどうしてなのかという理由をまず分析していただきたいと思います。それから、蝶の道プロジェクトですが、これが今どうなっているのか、これが始まったときに何かを期待して始まったと思うんですけれども、その経過をお聞きします。それから、被災者雇用助成、これの内容と結果、今後の支援のあり方についてお聞きします。","respondent":"福島荏原保健センター所長、多並公園課長、太田品川区清掃事務所長、工藤生活衛生課長、福島ものづくり・経営支援課長","answer":"この思春期の心の相談というのは、これはその時間に来ていただいてやっているというものであって、決して少なくはないとこちらでは考えております。そちらが地元の方の支援をさせていただいて進めてきたところで、現在は地元の方がそれで進めているところで。私からは、１５６ページに記載されております被災地支援職員派遣費についてご回答いたします。１４５ページに出ています被災地支援職員派遣費です。こちらのほうは、復興・復旧に向けて、職員派遣に要する旅費の経費です。","voiceIndex":222,"id":"exchange-094"},{"speaker":"西本委員","kind":"質問・要望","question":"それぞれありがとうあります。健康相談なんですが、７９件は少なくないという意味がよくわからないんですが、なぜそういう判断をされるのか、これ、どういう仕組みになっているのかなと思いますし、あと、宣伝はどういうふうな広報をされているのかお聞きしたいと思います。実際現場を見ていられるわけですから、いろいろな部署の中で行かれていると思うんです。","respondent":"福島荏原保健センター所長、堀越人事課長","answer":"これは３保健センターで月に１回ずつ毎月行っているということで、これはどういう具合にするかというと、いわゆる保健師がふだんの日常の相談の中で解決できないような人、子どもとかその親御さん、それから保育園の方等の相談があって。被災地の派遣の区へのフィードバック等に関するご質問ですけれども、区といたしましても、災害時の対応、それから、その後の支援を受ける側になった場合の備えとか、そういった面においてこの経験が活用できるというふうに考えています。","voiceIndex":228,"id":"exchange-095"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、相談業務、いろいろなところで、例えば学校だったらカウンセラーとかいろいろなことがある、保健所もある、いろいろなところでそういう相談業務があるんだけれども、実際に次のステップはこういうところがありますよ、こういう悩み事、それから、専門的なこと、処置が必要な場合にはこういう手立てがありますよというものは、やっぱりしっかりと広報していただきたいというふうに思っております。","respondent":"福島荏原保健センター所長","answer":"実際、いわゆる児童思春期の相談件数、家庭訪問というのが７５件、それから電話相談等が２３８件あります。その中でどうしても保健師等の相談で解決が得られなかったり、治療が必要だったりという方を、特に必要な人を選んで専門医相談という形をとっているということです。","voiceIndex":231,"id":"exchange-096"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、まずどこが窓口になっているところがあって、その先、どういう手立てがあるのかという全体像がやはり見えにくくなっているんだと思うんです。では、次に行きます。商店街ですから、それぞれの自力の中でしていかなければいけない部分なのではないか、区がどこまでかかわっていくべきものなんだろうかというふうに疑問視するんですけれども、目的、それから区の考え方についてお聞きします。","respondent":"米田商業・観光課長","answer":"通常のイベント事業等ですと、事前に、かなり前に申請手続をしてというような補助事業になってまいりますが、こちらについては比較的柔軟な区の対応がとれる区の単費の事業ですので、そういった意味でもこういう人材育成のための事業については今後も支援を続けてまいりたい。","voiceIndex":233,"id":"exchange-097"},{"speaker":"西本委員","kind":"質問","question":"本来であれば、区商連の人材育成にしてみれば、区商連の中でするべきものではなかろうかというふうに思うんですけれども、あえて品川区がそれに予算をかけてというところにおいては、どういう考えがあってこの予算を立てて税金をかけていくのだろうかということについての考え方をお聞きします。","respondent":"米田商業・観光課長","answer":"簡単に言ってしまうと、商店街の、区商連の動きをサポートする、そのためにある種一定の金額の投資も避けられないかなと考えています。","voiceIndex":235,"id":"exchange-098"},{"speaker":"浅野委員","kind":"質問","question":"１６０ページの新製品・新技術開発促進事業について質問します。今回の実績としては、ものづくりのほうで１３件で、ソフトウエア開発５件という結果だったと思いますが、平成２３年度の当初予算、こちらは約２,７００万円だったわけですけれども、この当初予算のとき、そもそもものづくりのほうとソフトウエア開発費、それぞれ何件ずつ助成する予定でスタートしたのか教えてください。","respondent":"福島ものづくり・経営支援課長","answer":"ものづくりの部門につきましては９件で、ソフトウエアが２件というふうに考えてあります。","voiceIndex":238,"id":"exchange-099"},{"speaker":"浅野委員","kind":"質問","question":"ものづくりのほうは３３件の応募があって、ソフトウエアのほうは２０件の応募だったと思いますが、今までものづくりを中心に進めてきたということもあって、なかなか新しく入ったソフトウエアのほうは厳しいのかなという気持ちもあるんですが、ソフトウエアもそれが中小企業にとっても大事な産業であるということを考えるならば、やはりもう少し。","respondent":"福島ものづくり・経営支援課長","answer":"実際に募集したところ、応募が２０件ありました。内容を審査したところ、かなり優れたものだということもございましたので、補正で３件を組んだということで５件にしました。なお、平成２４年につきましては、ソフトウエアも１０件ということで大幅に増やしています。","voiceIndex":240,"id":"exchange-100"},{"speaker":"浅野委員","kind":"質問","question":"新クライアントということで、なかなかなじみはないかと思いますけれども、今後セキュリティーの観点からも非常に重要な技術だと思いますが、今回、審査に当たったのが、これは毎回でしょうか、産業支援を目的とした団体等になっていると思いますけれども、これはどのような審査体制なのかということを１点お伺いしたいのと、あと、新クライアントということもあって、情報システム関係だと思います。","respondent":"福島ものづくり・経営支援課長","answer":"品川区への取り組みですけれども、今回の仮想新クライアントにつきましては、Ｌｉｎｕｘでございましたので、品川区で取り入れるのはなかなか難しいなというふうに思っておりましたので特に紹介はしませんでしたけれども、他のソフトにつきましては。","voiceIndex":242,"id":"exchange-101"},{"speaker":"浅野委員","kind":"質問・要望","question":"この規定の中に、助成金の規定に抵触して取り消しになるという、このケースもあるかと思いますけれども、この規定について適用された例は過去にあったのかどうかということと、このような規定を設けたそもそもの考え方、こちらについてお伺いしたいと思います。","respondent":"福島ものづくり・経営支援課長","answer":"取り消しのケースですとか、あるいは、途中で開発を取りやめるというケース、そういったものもありますので、途中でやめる、あるいは逆に金額も少なくなる、そういうケースもあります。やはり流動性があるもので、それに対応するように事務作業を進めているものです。","voiceIndex":244,"id":"exchange-102"},{"speaker":"浅野委員","kind":"質問","question":"選ぶ限りにおいては、やはり継続的に品川区で頑張ってもらうような、そのような企業になってもらいたいなと思いますけれども、今回こういう形で、ものづくりも、ソフトウエアのほうも受賞されたということで、本当にいいことだと思いますけれども、例えば、優秀な企業になりますと、ソフトウエアについても、ものづくりについても、毎年のように新製品を出したとか、世に問うような。","respondent":"福島ものづくり・経営支援課長","answer":"連続しての助成ですけれども、基本的には２年連続までという内規で進めております。といいますのも、やはり多くの方が応募されてありますので、連続２回ありましたら１回休んでいただく、そのような形で今のところ運営しています。","voiceIndex":246,"id":"exchange-103"},{"speaker":"浅野委員","kind":"質問","question":"そしてもう一つ質問ですけれども、フォローアップとして相談員が翌年度伺う場合があるというふうに、この一文も書かれておりますけれども、この意図についてお伺いしたいと思います。受賞したところにつきましては、今後も長いつき合いをしていっていただいて、品川区にとってメリットのある、また企業にとってもメリットがあるような動きをしていただければと思います。ご答弁をお願いします。","respondent":"福島ものづくり・経営支援課長","answer":"そういうことを進める上で、今年からメードイン品川ＰＲ事業というものも進めておりまして、これまで助成した製品について区としてのＰＲも進めていく、そういう展開にもなってあります。","voiceIndex":248,"id":"exchange-104"},{"speaker":"本多委員","kind":"質問","question":"芳水小学校の周辺を毎日１年中、冬でも夏でも、晴れでも雨でも、雪が降っていると雪かきをする、本当に地域ですごい、この人はすばらしいなという方が、この平成２３年度に表彰されて、大変うれしく思いまして、こういう汗をかいた人が報われるということを、区が表彰していただいたことを本当にうれしく思いまして、そういう情報のキャッチをどうされているのかお知らせください。","respondent":"野呂瀬環境課長","answer":"環境大賞についてのお尋ねです。情報のキャッチですけれども、いわゆる環境にいろいろ取り組んでいただいた方、町会とか、自治会に推薦をいただくということで、今回この方が地域のほうから推薦されたです。","voiceIndex":251,"id":"exchange-105"},{"speaker":"本多委員","kind":"質問・要望","question":"次の質問に移ります。１５４ページの清掃費に関連しまして、この「ごみ・リサイクル通信」を見ているんですけれども、この中で最終処分場が平成１８年ごろまでには約３０年と予測されていましたが、サーマルリサイクルや分別の徹底のおかげで、約５０年に延命されましたということで、この５０年について、概要をお知らせいただきたいと思います。","respondent":"太田品川区清掃事務所長","answer":"ごみ量ですけれども、品川区では平成２０年１０月に分別変更をさせていただきました。プラスチック系のもので、いわゆる不燃ごみとして出していたものを燃やす方向でいこうというところで、２３区共同で実施したものです。","voiceIndex":253,"id":"exchange-106"},{"speaker":"本多委員","kind":"質問・要望","question":"１５３ページの資源回収ですけれども、先ほど、渡辺委員からもいろいろ課題については取り組んでほしいということがありましたので、全く同じ思いから質問しますが、アルミ缶など、資源還元が、今、単価はキロ６円ということでやられておりますけれども、この６円というのは、本当に区民の皆様の汗があり、絆があり、夢や希望がありまして、この６円について、今後、単価を値上げなどできないものか。","respondent":"太田品川区清掃事務所長","answer":"再開発事業における資源についてですけれども、これはもういわゆる事業系の資源、あるいは事業系のごみというふうな位置づけになってありますので、このものについては、あくまでも事業者が自己責任のもとにおいて適正に管理していくと。","voiceIndex":255,"id":"exchange-107"},{"speaker":"本多委員","kind":"質問・要望","question":"町会への話し合いというのは、今後も機会があれば取り上げさせていただきたいと思います。ちょっと時間があるので１点だけ。先ほど来、答弁で、融資あっせんや創業支援センターなどに対して、事務事業評価のＣの見直しということで、積極的な見直しという答弁があったんですが、Ｃの見直しでも積極的な見直しと、縮小する見直しがあるというふうに捉えていいのか、簡単にそれだけ。","respondent":"柏原行財政改革担当課長","answer":"そういった中で、物によっては縮小方向というものもありますし、そのやり方を変えていくとか、いろいろな形での見直しの方向がありますので、それを表現させていただいたです。","voiceIndex":257,"id":"exchange-108"},{"speaker":"井上委員","kind":"質問","question":"私は、１５０ページのしながわ出会いの湯事業と、１５４ページ、リサイクル推進費、拠点回収、１４８ページの保健指導費について伺います。高齢になると、入浴が大変な生活課題になって困難課題になります。それを総合的にどう解決していけるのかという、そういう問題意識で質問をいたします。しながわ出会いの湯は、５,３００万円余の経費がありますが、その中で委託費の内訳を教えてください。","respondent":"江部健康課長","answer":"平成２３年度、浴場組合への委託費が４,２５６万２,８００円。それからシルバー人材センターへのプログラムの実施委託が７８０万３,１８０円です。","voiceIndex":261,"id":"exchange-109"},{"speaker":"井上委員","kind":"質問","question":"この主なものが浴場組合の４,２５６万円と、プログラム実施委託が７８０万円ということですが、毎週楽しみにしているという人が多いというふうに思います。延べ人数を割り返すと、大体１週間の利用人数は５４５人ぐらいになるんじゃないかなというふうに思います。この現状で質問をいたします。移行の理由と、事業の目的、参加実人数、以上３点、教えてください。","respondent":"江部健康課長","answer":"ちょっと詳しい経緯については、私、把握していない部分がありますが、事業を整理する中で、健康づくりの範疇に入れるのが妥当ではないかという考え方で健康課が扱っているのではないかと思われます。","voiceIndex":263,"id":"exchange-110"},{"speaker":"井上委員","kind":"質問","question":"そうすると、どのぐらいの高齢者の方が利用されているのかなという、先ほど、４０何週、多分５２週のうちに休みがあって４９週ぐらいかなというふうに思ったんですけれども、そうすると、私は６００人弱かなというふうに思ったんですが、その辺がどのように区は把握をされているのか、そういうところも把握は必要かと思うので教えていただければというふうに質問いたしました。","respondent":"江部健康課長","answer":"委員の計算で、ほぼ１浴場２０人で、１年間通しで利用していただくということで、３４浴場で平成２３年度はスタートしています。年度途中で残念ながら１浴場が廃止ということになりまして、途中から３３浴場になりました。単純計算で行くと、大体６００名の方だと思われます。","voiceIndex":265,"id":"exchange-111"},{"speaker":"井上委員","kind":"質問","question":"先ほど答弁いただいたように、事務事業概要では、この事業の中で、あわせて区内公衆浴場の振興に寄与するというふうに書かれているんですけれども、６００人ぐらいの高齢者の方が利用されている。そこで、この矛盾を何とか解消したいというふうに自分でも思うんですけれども、そこを行革の視点か、あるいは企画の立場から、ちょっと教えていただければなというふうに思います。","respondent":"柏原行財政改革担当課長","answer":"ただ、事業のそれぞれの目的がありますので、それぞれに応じた形で今、事業展開をしているというところがあります。そういったところをかんがみながら、今のご指摘も含めながら、今後どういった形ができるのかというのは検討すべきことだというふうに思ってあります。","voiceIndex":267,"id":"exchange-112"},{"speaker":"井上委員","kind":"提案","question":"ですから、そこも十分に検討していただきたいなと思うんですが、事務事業概要では、４６ページでは、Ｂとなっているんですけれども、やっぱり大きな意味では見直しが必要ではないかというふうに考えるんですが、この費用対効果の面も含めて、その根拠を教えてください。","respondent":"江部健康課長","answer":"先ほどご説明不足で申しわけございませんでした。プログラムに参加する方の人数と、それから、そのときにプログラムには参加しないけれども、お風呂の時間帯に来ていただきますと、半額での入浴をしていただいております。","voiceIndex":269,"id":"exchange-113"},{"speaker":"井上委員","kind":"質問・要望","question":"次は、リサイクルの推進ですが、２０１２年より拠点回収場所が２９カ所に増えました。拠点ごとの回収量の多いところと少ないところという差があるのか、あるとしたら、どういう要因が考えられるのかお伺いします。２点目は、ここ数年の拠点回収、集団回収にかかる経費の推移が、大まかで結構です、わかれば教えてください。","respondent":"太田品川区清掃事務所長","answer":"平成２０年度に１カ所、平成２１年度に３カ所増やして、平成２３年度にさらに３カ所ということで、ここのところ地域のバランスを考えて、大体半径６００メートルから７００メートルの範囲内で、拠点へ持っていける範囲内で拠点数を増やしてきているということがあります。","voiceIndex":271,"id":"exchange-114"},{"speaker":"井上委員","kind":"質問","question":"そうなると、同時に拠点および集団回収経費というのは増えていきます。それに対して行政の行うリサイクルや清掃事業費が減るという関係をつくっていかないと、どんどん経費が膨らんでいくということになりますので、一方が増えれば一方が減るということで、当然、区もそういう目標をお持ちだというふうに思いますので、そこに向けて実際にどのような取り組みをされているのか教えてください。","respondent":"太田品川区清掃事務所長","answer":"その結果によって、先ほど本多委員からご質問があったように、最終処分場への延命へもつながっていく、こういう流れになるかと思います。そういう考え方です。","voiceIndex":273,"id":"exchange-115"},{"speaker":"井上委員","kind":"質問・要望","question":"新規の集積拠点が少ないということは、やっぱり周知がまだ地域の方にできていないということだと思いますので、その辺は頑張っていただきたいなというふうに思います。次は、歳入でも質問しましたけれども、健康大学についてお伺いいたします。ここは受講料は無料で、テキスト代とか実費はかかります。抜本的な仕組みの構築が必要ではないでしょうか。見解を伺います。","respondent":"坂上品川保健センター所長","answer":"今、井上委員よりご指摘ありましたように、卒業生の活動については、まだまだ成熟したものではない形です。今後の課題といたしまして、卒業生の活動の仕方ということをより深く研究していこうと考えています。","voiceIndex":275,"id":"exchange-116"},{"speaker":"高橋委員","kind":"質問","question":"１４９ページの区民健康づくりプラン品川推進事業費、それから、成果報告書のどこかちょっとわからないんですけれども、品川区就業センターについて、２点お尋ねします。これについて、平成２２年の決算特別委員会において、別の委員の方が指摘され、次の年、つまり、平成２３年度にどういう基本的な考えをしていくかということをご質問されていました。よろしくお願いします。","respondent":"江部健康課長、柏原行財政改革担当課長","answer":"その理由につきましては、初年度の実績としては、個人の方、商店の方、企業の方から、こういった健康づくりをしていますよということで一定の件数が出ておりましたが、次年度以降、平成２３年度実績ではゼロということだったので。それからあと、健康づくり推進委員会につきましては、平成２４年度は１３地区で推進委員の選出の改選期であったというところがございましたので、高齢化を配慮した選出をお願いしたという経緯があります。","voiceIndex":278,"id":"exchange-117"},{"speaker":"高橋委員","kind":"質問・要望","question":"さまざまな施策を行っていただくのは大変よろしいんですが、今、監査委員の意見書の中にもありましたけれども、非常にいろいろなことが重なったりしているというところで、衛生費の中だけのお話ではなくなってしまって、民生費とか、全庁的なお話になってしまうので、今、企画の方からお答えいただいたので大変難しいことだと思うんですが、初めに健康課長のほうもお話しいただいたので。","respondent":"江部健康課長","answer":"先ほど、行財政改革担当課長から出ましたもう１点の健康づくり推進委員の高齢化という問題につきましては、改選に当たりまして、部分的には若返りといいますか、一部改善を図ったところです。","voiceIndex":281,"id":"exchange-118"},{"speaker":"高橋委員","kind":"質問・要望","question":"次に移りますが、今お話にあったように、さまざまな健康づくりの関連事業を展開していただいているんですが、その必要性があるから行われていると思うんですが、私、ちょっとこういう分野は素人でわからないんですが、公衆衛生とか、公衆衛生学というのでしょうか、そういった観点からお尋ねしたいので、間違っていたらご指摘いただけるとありがたいのですが、品川の区民の皆さんの健康度。","respondent":"矢野品川区保健所長","answer":"それによりますと、それは６５歳健康寿命というんですけれども、男性は東京都の平均が８０.６６ですが、品川区は８１.０１、それから女性のほうは、東京都全体が８２.２７で、品川区が８３.０１ということで、２３区で比べると。","voiceIndex":283,"id":"exchange-119"},{"speaker":"高橋委員","kind":"質問・要望","question":"今のは、要介護の話ですよね。健康づくりは、そういった高齢の６５歳以上の方のものがありますが、もう少し年齢の下がる方々に対しても、さまざまな健康づくりをされているというところですので、ぜひ今いろいろな尺度があって判断が難しいと思うんですが、健康づくりの施策の整理と体系化をしていく中で、そういった調査というんでしょうか、そういうことを進めていっていただきたいと思います。","respondent":"江部健康課長","answer":"区民に対して区として行っております世論調査、名称はちょっと正確にでてきませんけれども、その中には健康に関する調査項目があります。","voiceIndex":285,"id":"exchange-120"},{"speaker":"高橋委員","kind":"質問・要望","question":"その健康に対する調査を生かして、さまざまな方法といいますか、方向性を出して、先ほどの類似事項のいろいろな健康づくり政策の整理と体系化を進めていっていただきたいと思います。よろしくお願いします。次に、品川区就業センターのことなんですが、ちょっと成果報告書の中では見当たらなかったんですが、年度末に開設したので、私が探せなかった、済みません、まずどこにあるのか。","respondent":"福島ものづくり・経営支援課長","answer":"品川区就業センターですけれども、昨年度、平成２３年３月に開設しました。予算ですけれども、こちらのほうは急遽行ったということもありますので、こちらの成果報告書で言いますと、１５７ページの産業情報収集提供事業、この中で予算流用しながら開設した次第です。","voiceIndex":287,"id":"exchange-121"},{"speaker":"高橋委員","kind":"質問","question":"３月２６日、年度末に開設したとお聞きしています。そういった点も踏まえて、ハローワークとのそういった連携、そしてサポしながわ、それからあと、生活保護関係との連携、そういったところを含めて、平成２４年度に入ってしまいますが、この事業の現在までの実績と評価、現在どのような評価をされているかお伺いいたします。","respondent":"福島ものづくり・経営支援課長","answer":"サポしながわにつきましては、当初の予定では、今年の１０月に移転をする予定だったんですけれども、やはり早く近くに来てほしいというか、北品川では遠いという区民の声もありましたので、前倒しをしまして、７月からサポしながわは就業センターの中に移転してきました。","voiceIndex":289,"id":"exchange-122"},{"speaker":"高橋委員","kind":"意見","question":"今のように、ハローワーク等のそういったさまざまな法律の壁等あり、線引きが難しいところがあるんですが、ここまで来て、今、大変成果が上がっているというお話をいただいたんですが、課題もあると思うんです。その課題がどういったところにあって、それを今後どう解決していこうと思われているかお願いします。","respondent":"福島ものづくり・経営支援課長","answer":"区としましては、求人を出している中小企業に対する支援も必要と考えておりまして、今年の７月から事業は開始し、実際は９月からそういった支援を進めているところです。","voiceIndex":291,"id":"exchange-123"},{"speaker":"山元委員","kind":"質問・要望","question":"よろしくお願いします。最初に、区も推進しているように、この集団回収、こちらにも書いてありますけれども、５７２団体登録されておりますけれども、先ほどのお話で行きますと、この団体、ＰＴＡとか、町会というように伺ったと思いますが、そのほかに企業とか、何かほかにあるのかどうかも教えていただきたいと思います。","respondent":"太田品川区清掃事務所長","answer":"平均の金額ですけれども、これは回収量によって当然違ってきますので、ちょっと今、手元に細かな書類がないんですけれども、ほとんどが、大ざっぱですけれども、１０万円行くか行かないかぐらいが標準的な支給金額かなというふうに思っております。","voiceIndex":295,"id":"exchange-124"},{"speaker":"山元委員","kind":"質問・要望","question":"次の資源持ち去り防止対策費についてお伺いいたしたいと思います。初めに、黄色いテープというんでしょうか、持ち去り禁止テープがありますけれども、こちらはたまに見るんですけれども、どういうような形、各家庭に配布していただけるものなのか、その辺がどういうふうになっているのか、その辺も教えていただきたいと思います。","respondent":"太田品川区清掃事務所長","answer":"７月については、広報紙あるいはホームページでお知らせさせていただいて、清掃事務所、荏原、大崎のほうに来ていただければ配布をすると、こういうことで周知をしています。","voiceIndex":297,"id":"exchange-125"},{"speaker":"山元委員","kind":"質問・要望","question":"本当に私もつけさせていただいて、置いてちょっと目を離したら、もう持っていかれてしまったなんて、そんなこともございましたけれども、ぜひまた使わせていただきたいと思います。今まで過料というんでしょうか、合計どのぐらいになっているのか、また、その行方はどちらのほうに行くのか、それもちょっと教えていただければと思います。","respondent":"太田品川区清掃事務所長","answer":"その命令に違反した場合に初めて過料５万円という形になります。そういう意味で行きますと、条例の効果があって、抜き取り業者はすべてステーションのほうへ返すという形になってありますので、５万円の徴収という事例は現在ございません。","voiceIndex":299,"id":"exchange-126"},{"speaker":"山元委員","kind":"質問","question":"了解いたしました。実は名古屋市のほうに集団回収のときに、古紙守君というキャラクターがありまして、回収所にのぼりを立てて、またチラシをつくったりするときにこのキャラクターを載せて皆さんに意識を高めてもらうと、そういうものがあります。品川区もぜひこのキャラクター、何かを考えて、少しでも周りの人たち、また目立つようなものをつくってはいかがかと思いますが、いかがでしょうか。","respondent":"太田品川区清掃事務所長","answer":"そういう意味で目立つという形での啓発というのもあるんでしょうけれども、逆に、資源ステーションの場所を抜き取り業者に明らかにしてしまうということもありますので、なかなか難しい面があるかなというふうに思ってあります。","voiceIndex":301,"id":"exchange-127"},{"speaker":"山元委員","kind":"質問・要望","question":"区長の顔のポスターがあったらいいななんて内心思いましたけれども、ぜひ考えていただきたいと思います。生ごみ処理機普及事業についてお話をさせていただきたいと思います。先ほど、品川区、３４５台というお話がありましたけれども、この３４５台の中、助成されているわけですけれども、大体どのぐらいの機械をお買いになっている方が多いのか。簡単でいいんですけれども、教えていただきたいと思います。","respondent":"太田品川区清掃事務所長","answer":"先ほど、台数を申し上げましたけれども、誤解のないようにお願いしたいと思うんですけれども、ここ５年間の支給件数ですので、実際はもっと前から実施していますので多くなります。","voiceIndex":303,"id":"exchange-128"},{"speaker":"山元委員","kind":"質問","question":"特に足立区は、累計ですけれども、２,２５５台まで普及しているというお話ですので、この辺、先ほど所長のお話しですと、四、五万円ということであれば、半額、５万円であれば半額まで助成していただくと、もう少し広がるのではないと思いますが、その辺はいかがでしょうか。","respondent":"太田品川区清掃事務所長","answer":"品川区においては、かつてコンポストも実施してございましたけれども、においの問題とか、いろいろ手間がかかるとかがあって、件数がなくなったもので、なくならせていただいたものです。","voiceIndex":305,"id":"exchange-129"},{"speaker":"須藤委員","kind":"質問","question":"というのは、本当は款が違うから、昨日、国保とか後期高齢者医療でやればいいんだけれども、ジェネリックを使いなさいという表示が区でできるのかどうか、また、ジェネリック医薬品について区としてはどういうふうに考えていらっしゃるのか教えてください。","respondent":"工藤生活衛生課長","answer":"国のほうでは、いわゆる推進目標ということで、今、２０数％ジェネリック医薬品が普及していると言われておりますけれども、国のほうでも３０％を目指してやっているです。","voiceIndex":308,"id":"exchange-130"},{"speaker":"須藤委員","kind":"質問・要望","question":"先ほど、松澤委員が言ったけれども、医師からの処方箋でジェネリックをどうのというのは、なかなか処方箋に書いていないので、薬局によっては、もうそのまま医師の処方箋のとおりで薬が出てきてしまうよというのが通常だろうと思うので、そのあたりのところは、今度は区民の人たちが、これはジェネリックに変わりますというのは薬局で表にして出してくれると思うんですが、そのことに気づいてもらって。","respondent":"多並公園課長","answer":"調査の結果、鳥類が３５種、昆虫につきましては２９３種、魚類につきましては１４種、水生生物については５４種、両生類については３種、爬虫類については６種等々という状況を確認いたしました。","voiceIndex":310,"id":"exchange-131"},{"speaker":"須藤委員","kind":"質問","question":"生物多様性の調査は、国際的に世界中でいろいろ調査をして、絶滅危惧種とか、あるいは植物なんかでもきちんと種をどこかあっちのほうの氷の島で保存するような仕組みをつくって守っていこうというような仕組みをやっているんだけれども、その基礎調査というのが、今言ったように、昨年度やられて、何年かやっていくものなのか、５年に１回とか、そういう仕組みになっているのか教えてください。","respondent":"多並公園課長","answer":"例えば、鳥であれば木に巣をつくったりだとか、そのような形で生物が生息する空間として緑が大切と、全体的な形で区民の方々が、都心に住む方々が生物等を大量に消費する都会の中で、そういうつながりがあって。","voiceIndex":312,"id":"exchange-132"},{"speaker":"須藤委員","kind":"質問・要望","question":"１５７ページの産業経済費全体で、ここで執行率が７２.２％と、ほかの款に比べて不用額が非常にここの産業経済費だけ大きいんだけれども、このあたりについては、震災の影響があっただけなのか、それにしては３割近い不用額が出ているというのはなぜだろうと思うんですが、そのあたりはいかがでしょうか。","respondent":"本城企画財政課長","answer":"産業経済費につきましては、経年的にもほかの費目と比べると８割弱程度のことが多いのが実情です。","voiceIndex":314,"id":"exchange-133"},{"speaker":"須藤委員","kind":"質問","question":"１６０ページのものづくりの活性化で、品川技術ブランドＰＲ事業、今年の代表質問のときに区長がいろいろそういうものについては先頭になってＰＲをするというお話をいただきました。それから、タイランドなんかでは、ジェトロでやっているけれども、今、タイランドではほとんど休眠状態になっているよというようなことがあるんだけれども、そのあたりのＰＲについては、いかがされているのかどうか。","respondent":"濱野区長","answer":"ただ、海外へのアピールというのは、正直言ってその次の段階で考えてさせていただきたいと思っていますので、よろしくお願いします。","voiceIndex":316,"id":"exchange-134"},{"speaker":"須藤委員","kind":"質問・要望","question":"品川区がタイランドをやったというのは、海外を目指していると思うので、そのときにトップが動くというのは、今言ったような大使館であるとか、国とどうのしようというときにトップが出ていくもので、細かい点を区長がそこまで理解してどうのしようなんていうのは、しょせん無理なので、そこが区長の出番はどういうところなんだというのを聞かせてもらおうと思って質問したので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":318,"id":"exchange-135"},{"speaker":"南委員","kind":"質問","question":"１５９ページの商店街活性化事業費のうちの商店街の装飾灯の関係でお尋ねしたいと思います。それぞれ決算額が３項目に渡って出ているんですけれども、大前提として、これらの補助金対象になった商店街は幾つあるのか、品川区内のすべての商店街のどの程度お使いになっているのか、大規模商店街、小規模商店街に分けて、わかれば教えてください。","respondent":"米田商業・観光課長","answer":"装飾灯自体ですけれども、現在、電気代の助成ということで、ちょっと別の場所になりますけれども、そちらについては、９４の商店街が使っております。おそらく街路灯を立てるときにはこういう助成制度を使っていると思われますので、それが数字なんだろうと思ってあります。","voiceIndex":320,"id":"exchange-136"},{"speaker":"南委員","kind":"質問","question":"商店街の規模別で知りたいなと思ったんですけれども、後ででいいですけれども、わかれば教えてください。この三つの決算書に出ているそれぞれの決算額は、予算額と比較すると、随分下回っているんですけれども、改めて執行率がどの程度だったのかを教えてください。","respondent":"米田商業・観光課長","answer":"活性化推進事業に関しての執行率については、今年度、７８.７６％という執行率になってあります。","voiceIndex":322,"id":"exchange-137"},{"speaker":"南委員","kind":"質問・要望","question":"ぜひ教えていただきたいと思います。そして、いずれも先ほど申し上げたように、予算額を大幅に下回っているんですけれども、下回った要因は何なのか、昨年度のことでありますので、大震災、このことによって福島原発事故があり、大きな節電を求められましたので、それが一番かなと思うんですけれども、担当のところの見解、その分析はどういうふうにしているのかを伺います。","respondent":"米田商業・観光課長","answer":"商店街の装飾灯の維持管理の補助ですけれども、こちらについては、８７.２４％になってあります。それから、小規模改修助成につきましては、２９.４％です。小規模改修助成というのは、これは倒壊等の危険のある緊急対策ということでやっております。","voiceIndex":324,"id":"exchange-138"},{"speaker":"南委員","kind":"質問・要望","question":"そうすると、大震災の影響、節電の部分については、あまりそういう問題ではなかったというふうに考えていいということですか。それから、商店街の合意をとれなかったというところは、どういうことなのか、例えば、予算的に捻出することが困難な部分があるとか、そんなことを一瞬インスピレーションであれしたんですけれども、そのあたりのことを教えていただきたいと思います。","respondent":"米田商業・観光課長","answer":"それからもう１点、商店街内の合意がとれなかったということについては、このケースに関しては、こちらの装飾灯等の関係の建て替え自体について、すべきでないというようなお声があったということで、商店街内で建て替えをしようということの合意がとれなかったと。","voiceIndex":326,"id":"exchange-139"},{"speaker":"南委員","kind":"質問・要望","question":"したがって、商店街が存続させていくということは、品川区の区民の生活にとっても非常に大きな影響のある生活の基盤ですから、そういう点で、経済が落ち込んでいる中でもしっかりと維持していただけるという、そういうための支援というのは引き続きしていただきたいというふうに思っているんですけれども、そのあたりの思いというのをちょっと伺っておきたいと思います。","respondent":"米田商業・観光課長","answer":"品川区のいわゆる商店街をめぐる環境ですけれども、景況調査等を踏まえましても、上がったり下がったり等あるとはいえ、厳しい状況が続いているというふうに認識しているところで、この辺のところを現在の商店街支援ということで、地域に欠かせない生活インフラとして。","voiceIndex":328,"id":"exchange-140"},{"speaker":"南委員","kind":"質問・要望","question":"その理由としては、先ほども申し上げましたけれども、商店街を衰退させてはならないということと、高齢社会に大きな影響を及ぼすだけに、維持発展させるべきだという、この点でしっかりと維持をさせて、商店街の負担を一層軽減させていただきたいということを強く求めておきたいと思います。その点について、このＣ評価のここについて改めて見解をお願いします。","respondent":"米田商業・観光課長","answer":"緊急経済対策の一環として、現在、基準額を倍増しておりますので、それについて、絶えず考えてまいりたいです。","voiceIndex":330,"id":"exchange-141"},{"speaker":"石田（慎）委員","kind":"質問","question":"私のほうからは、ページ数がちょっと不明ですが、ＡＥＤについてお伺いしたいと思います。それと、１５１ページからの環境対策費、１５７ページからの観光アクションプラン、１４６ページの予防接種についてお伺いします。点検の周期はどのくらいで行っているのかお知らせください。それと、レンタルについて、区で今どのような形で進んでいるのか、お考えを含めてお知らせください。","respondent":"江部健康課長","answer":"現在は、午前中の委員の質問にありましたが、区の中で行政機関以外でＡＥＤの機械があるよという表示をするですとか、そういったことを想定しておりましたので、ステッカーを２００枚ほど予算計上し、まずはそこからという考えでおります。","voiceIndex":333,"id":"exchange-142"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"レンタルで、ちょっと僕の聞き方が悪かったんですが、その貸し出し、区が例えばイベント等で貸し出しをしているかどうかのところだったので、その点で、今、例でお祭り等という話が出ましたが、例えば、どこかのセミナーで大勢来るときに貸してほしいとか、高齢者を対象としたセミナーとかだと、その必要性が出てくるのかなと思うんですが、その点、レンタルの考えをお知らせください。","respondent":"武内総務課長、野呂瀬環境課長","answer":"貸し出しにつきましては、特に使用団体の制限等は行っておりませんので、必要があれば地域活動課に相談していただければ、できる限り貸し出しするという、そういう方向でやっております。エネルギー対策、最初の質問ですけれども、ご承知のとおり、３・１１前は、いわゆる地球温暖化ということでこれは全国というか、区もそういう計画にのっとって進めてまいりました。","voiceIndex":338,"id":"exchange-143"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"観光アクションプランでありますが、品川区として、どこを観光スポットとしてアピールしていくのか、区としてだれかに品川区の観光はどこに行けばいいのと言われたときに、どことお答えをするのか、そこをまずお答えいただきたいのと、国際都市品川として、外国からの来訪者に対して、ハード面、ソフト面、どのように取り組んでいるのかお知らせください。続いて質問してしまいます。","respondent":"米田商業・観光課長、伊津野保健予防課長","answer":"それで、ハード、ソフトの展開ですが、ハードにつきましては、２年前に東京都のほうの補助もいただきながら、観光案内標識について、観光協会と観光案内標識設置計画に基づきまして、英語対応ではありますが、日本語。学校との連携でありますが、学校のほうでは講演会等で接種の勧奨というか、啓発を行っていると聞いております。","voiceIndex":341,"id":"exchange-144"},{"speaker":"石田（慎）委員","kind":"質問","question":"２３区での格差についてお伺いしたので、その点、再度お答えいただければと思います。目標が、現状４０％の中、８０％にしていく、その８０％にするために、どのような対策を講じなければいけないかという、その目標値だけがあっても、その対策案が示されなければ、ただ目標は８０％だと言っても、それを達成するのは困難だと思うので、その対策を改めてお聞かせください。よろしくお願いします。","respondent":"伊津野保健予防課長","answer":"２３区の格差につきましては、先ほどから申しているとおり、品川区のほうは低いほうであると考えています。それについても将来、検討していかなければならないかと考えています。","voiceIndex":344,"id":"exchange-145"},{"speaker":"須貝委員","kind":"質問","question":"私は、１５１ページ、環境費についてお聞きしたいと思います。指導費にかかわりますが、現在、有害物質というのがあります。そこでお聞きしたいのですが、環境課に何かそういう問い合わせ、何か臭うとか、ちょっとここはいろいろな化学物質を使っているのではないかとか、そういうような苦情があったときに、または環境課が発見した場合に、どのような処置をとるのか教えてください。","respondent":"野呂瀬環境課長","answer":"環境課の中には、いわゆる典型７公害とよく言われている中で、今は一番多いのが、やはり騒音と、あとは震動、そういうところの苦情が一番多うあります。やはり工事にかかわって寝ていられないよとかそういう。臭いというのは、皆無ではありません。","voiceIndex":347,"id":"exchange-146"},{"speaker":"須貝委員","kind":"質問","question":"今お話をお聞きしましたけれども、ただ、化学物質に対する規制はあると。例えば、クリーニング業、それから製造業、トリクレン、エチレン、さまざまな化学有害物質がありますよね。そこでお聞きするんですが、では、原発事故により拡散した放射能は、ヒトや生態系に対して、現代社会では最も有害な化学物質だと思いますが、これに対して、国や東京電力に対して、厳重注意をしたのか教えてください。","respondent":"野呂瀬環境課長","answer":"放射能は、委員おっしゃるとおり、有害な物質だと私も認識しております。","voiceIndex":349,"id":"exchange-147"},{"speaker":"須貝委員","kind":"質問","question":"今、そういうお話しだったのですが、現実、ここまで来なかったから実際よかったわけですよね。ですが、例えば今言った化学物質、工場でも何でもそうですが、使っていたら近隣の方にそんなに迷惑がかからなくても、ヒトが健康被害にならなくても規制はしますよね。これはちゃんとやめてくれと。ちゃんとそれなりの浄化装置をつけてくれと。原発が大体爆発したら上空へ飛び散る。ちょっと教えてください。","respondent":"野呂瀬環境課長","answer":"これは総務費の款別のときに、私、ちょっと言ったかと思うんですけれども、国の政策にかかわることですので、区としてそういう方針に対しての発言は控えしますと、これは何遍も言ってることだと思います。","voiceIndex":351,"id":"exchange-148"},{"speaker":"須貝委員","kind":"質問","question":"だって、人類にとって、区民にとっても、危険だというふうにわかっているならば、私は、区のどこかホームページ１ページでもそう、それから、区の広報でもそうですけれども、一応危険なんです、皆さん、これはわかってくださいという、そういう説明をいろいろなところでもやっていますけれども、やはり一自治体としてきちんと発信するということは大事なことではないですか。その辺についてお答えください。","respondent":"野呂瀬環境課長","answer":"それとともに、講演会、区民に対する講演会も保健所等の主催でいろいろやっております。そういう中で、区民の皆さんを放射能についての正しい知識を持っていただきたい、このように思っている次第です。","voiceIndex":353,"id":"exchange-149"},{"speaker":"若林委員","kind":"質問・要望","question":"１５９ページの共通商品券普及促進と、１４５ページの衛生統計調査費の二つです。共通商品券のほう、平成２３年度、この事業の目的として、地域商業の振興を図るということが大きな目的の一つになっております。そこで、プレミアム商品券を発行いたしましたけれども、この使えるお店の登録店舗数、それから商品券が使用された店舗数についてお聞かせいただきたいと思います。","respondent":"米田商業・観光課長","answer":"実際に使用された店舗数ですけれども、私のほうで今、正式な数字を申し上げられる状況にはございませんが、登録されているお店では、多い少ないはあると思いますが、使われているものだと、こういうふうに考えているところです。","voiceIndex":356,"id":"exchange-150"},{"speaker":"若林委員","kind":"質問","question":"今、正式な数字はないというのは、今後、もう少し時間がたつと、集計結果が出てくると、こういうデータが区なり、また商店街側にあると、こういう理解でよろしいでしょうか。","respondent":"米田商業・観光課長","answer":"その中では、商店街が全体として、個店の利便性を図るために、銀行への換金は商店街のほうで一括して行うというようなこともありまして、その辺の数字については、厳密に正確なものは出せてはいない状況ですが、９００を超えるお店で使われているということだけは確認しています。","voiceIndex":358,"id":"exchange-151"},{"speaker":"若林委員","kind":"質問・要望","question":"そうしますと、強い要請を行った、強い思いを持っている商店街のほうでも、毎年５億円とか、６億円とか発行されている商品券について、区のほうも１割のいわゆるプレミアムをつけて行っている事業ですので、これは商店街のほうにぜひデータ化等しっかりと求めて、例えば２,２００店舗のうちの９００店舗、残りどうするのか。あの場面では商品券は個店で使えるのかどうかお聞かせください。","respondent":"米田商業・観光課長","answer":"大規模店での連携事業での商品券の使用ですけれども、イトーヨーカドーやイオン等で連携事業でやっている場合についての商品券の使用ということはできません。","voiceIndex":360,"id":"exchange-152"},{"speaker":"若林委員","kind":"質問・要望","question":"これは今後の来年度以降に向かって、ぜひこの事業の目的と、この大型店と連携では、商品券がそこでも使えますよというのは、手続上の問題がいろいろあるのかもしれませんけれども、手続上でまた断られるのもしゃくですので、そこは乗り越えて、しっかりそこでどんどん商品券を使えるようにしてはどうかというのは工夫できるのではないでしょうか。これは要望しますので、ぜひ検討していただきたいと思います。","respondent":"工藤生活衛生課長","answer":"衛生統計調査費の中の人口動態調査、この中での死産ということの中で、胎児の人工死産の数です。平成２３年度２８件ということになってあります。","voiceIndex":362,"id":"exchange-153"},{"speaker":"若林委員","kind":"質問・要望","question":"今般、もう報道されていますので、昭和大学等で新しい出生前診断というのがどうやら導入されるそうだということで、これは全部聞きます。新たな出生前診断とは、どういうものなのかというのが一つ。今後このようなことについて、例えば昭和大学と情報収集、また差別や被害に結びつかないような区の対応というのは、どのように考えているかお答えいただきたいと思います。","respondent":"坂上品川保健センター所長","answer":"その簡便に受けた形で胎児の障害とかがわかったときに、人工中絶をするということに対しての、ある意味、障害を持った子に対する差別ということで問題になっているということを認識しております。","voiceIndex":364,"id":"exchange-154"},{"speaker":"若林委員","kind":"質問・要望","question":"今後の対応については、いわゆる今、妊娠中の方もおられます。学校等でこういう愛の手帳等を持っておられる、そういう障害の方もいらっしゃいますし、また大人もいらっしゃいます。ぜひ昭和大学等、情報収集をしっかりして今後のいわゆる二次被害とか、被害、差別につながらないようにしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":366,"id":"exchange-155"},{"speaker":"大沢委員","kind":"質問・要望","question":"お願いします。最初にお伺いしたいのは、資源持ち去りということで、午前中、うちの渡辺委員のほうから質問させていただきましたけれども、補足で質問します。先ほど来の理事者と我が議会との議論を踏まえての話ですので、基本的なところははしょってご答弁いただきたいと思います。この中で、先ほどお伺いしました抜き取り取り締まりの所作として、現認、指導、没収という三つの過程がある。","respondent":"太田品川区清掃事務所長","answer":"だから、命令違反にならないので過料が出せない。問題は、現認できない場所でいろいろな工夫をしてパトロール隊をくぐり抜けて抜き取りをしている現実がある、ここが２３区、やはり抜き取りの大きな問題だというふうに私どもは理解をしています。","voiceIndex":368,"id":"exchange-156"},{"speaker":"大沢委員","kind":"質問・要望","question":"ぜひとも新しい試みも始めたということですので、うちのほうの施策として、罰則強化ということもありますので、そこのところもお考えに入れながら、今後、罰則、条例の見直しに向けた手続もやっていただきたいと、こういうような要望を出してこの質問を終わります。次ですが、新型インフルエンザについてと、大井保健センターについてお伺いします。以上、３点お伺いしたいと思います。","respondent":"伊津野保健予防課長、矢野品川区保健所長、武内危機管理室長","answer":"これは来年の春ごろ施行される予定でありますが、その中でワクチンの接種につきまして、住民に対するパンデミックワクチンの打ち方について。そのことを踏まえて、今後新たな新型インフルエンザが発生した場合には、より円滑に、また区民が安心して対応できるように整えてまいりたいと考えています。そういった中で本部対策が設置後、その辺の広報等はしっかり全庁的な取り組みとして体制をとっていくという、そういう体制になっております。","voiceIndex":370,"id":"exchange-157"},{"speaker":"大沢委員","kind":"質問・要望","question":"済みません、大井保健センター、先ほど来、品川と荏原がずっと出ておりまして、大井保健センターのほうを聞き方を忘れてしまいまして、通告だけして何を聞きたいかというのをお話しできなかったので、申しわけございませんでした。大井保健センターの現状ならびに今後のあり方について、改めて伺わせていただきたいと思います。","respondent":"川島大井保健センター所長","answer":"事業内容は、母子保健および精神保健、難病対策、成人の健康づくり等、他の保健センターと同様のものを実施しています。今後の存続に関してのご質問に関しましては、地域に近いところで区民に保健サービスを提供するということは大変重要な意味があります。","voiceIndex":374,"id":"exchange-158"},{"speaker":"大沢委員","kind":"質問・要望","question":"大井保健センターについては、しっかりと頑張っていただきたい。以上に思っております。次に行きますが、先ほど伺いました不妊治療とタイのビジネスサポートセンター、タイのビジネスサポートセンターにつきましては、ほかの委員、うちの委員につきましては沢田委員、そして須藤委員、そして他会派につきましては、藤原委員が質問をさせていただきました。それを受けて私は質問をする。","respondent":"江部健康課長、福島ものづくり・経営支援課長","answer":"特定不妊治療と申しますのは、東京都のほうでやってあります体外受精や顕微受精などということで、要は、不妊助成の対象が違うということで、区の事業と都の事業とが重なっているという状態だです。平成２４年度の予算特別委員会を受けまして、来年度予算には何らか反映できるようにということで検討を進めているところです。","voiceIndex":376,"id":"exchange-159"},{"speaker":"大沢委員","kind":"質問・要望","question":"それともう一つ、先ほどの不妊治療のところで、お話しいただいたのは、おのおのの種類を伺いたかったのではなくて、この表現から意図するところは何なのかということを聞きたかった、そこでどういうふうに帳尻といいますか、真意はしっかりと前回の答弁と今回の答弁と合わせていくのかということでお伺いしました。これで質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":379,"id":"exchange-160"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1362#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":116003,"voices":380}},{"id":"h24-20121009-4","meetingId":"h24-c-settlement","date":"2012年10月9日","dateIso":"2012-10-09","committee":"決算特別委員会","time":"午前１０時００分～午後５時３２分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を140件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"○午前１０時００分開会 ただいまより決算特別委員会を開会いたします。 それでは、平成２３年度品川区一般会計歳入歳出決算","agenda":"○午前１０時００分開会 ただいまより決算特別委員会を開会いたします。 それでは、平成２３年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"１７１ページの住宅・建築物耐震化支援事業について、時間があったらお聞きしたいと思います。補助２０５号線の整備なんですけれども、この間の第２回定例会の一般質問でも行いましたけれども、順調に整備のほうが進んでいるかと思います。","respondent":"稲田道路課長","answer":"その件につきましては、警視庁と協議を現在進めているところなんですが、現状の警視庁の考え方ですと、補助２０５号線が開通してから、三ツ又の交差点の部分の現状をよく把握しながら検討は進めていきたいという状況です。","voiceIndex":4,"id":"exchange-001"},{"speaker":"沢田委員","kind":"質問・要望","question":"引き続き交渉のほう進めていただきたいと思います。その中では今後自治体での対策が必要とした地点の具体的な安全対応方針を１１月末までに検討するようにという指示があったかということでしたけれども、これは品川区内でしたら、どういった箇所が調査されて、その箇所数は幾つぐらいあったのかということをお聞かせください。","respondent":"稲田道路課長","answer":"そのうち、９４カ所が対策が必要な箇所ではないかというふうに３者で立ち会って抽出していきました。その中で５７箇所、これが区道を管理する我々道路課部門が対応していかないといけない箇所というところで抽出されました。","voiceIndex":6,"id":"exchange-002"},{"speaker":"沢田委員","kind":"意見","question":"これは国がそういった、この間の事故が起きて、文部科学省でそういう話になったかと思うんですけれども、そもそも区のほうで、国に言われるまでもなく危険な箇所ということは以前から把握はされていたかと思うんですけれども、この今回の指摘によって、また以前から安全対策は進めていたかと思うんですけれども、どういったことが変わったのか、何をどういった形で改善されるということになったのか。","respondent":"稲田道路課長","answer":"そうすることによって歩行者がここを通るというのが明示されまして、車のほうにも明示することができるというところとあります。それから、警戒標識の設置、カーブミラーの設置、見通し等の関係でそういうものをやっていきたいと考えております。","voiceIndex":8,"id":"exchange-003"},{"speaker":"沢田委員","kind":"質問・要望","question":"続けて、歩道橋ということでちょっとお伺いしたいんですけれども、区内に歩道橋がたくさんあるかと思いますが、国道に係るのは国が管轄されていると思いますし、都道に係るのは都だと思いますけれども、区が維持管理を行っているのは何カ所あって、大体箇所によるかと思うんですけれども、１日の利用者数の調査とか、また、そういうことをされているのかということと、年間の維持管理ということでは。","respondent":"稲田道路課長","answer":"歩道橋です。区の管理する歩道橋は２２橋あります。こちらのまず維持管理につきましては、１０年とか１５年スパンで塗装の塗り替え、そういうものをやってきまして、維持管理をしていると。日常におきましては、道路橋の維持費がございまして、傷んだところを補修していく。","voiceIndex":10,"id":"exchange-004"},{"speaker":"沢田委員","kind":"質問・要望","question":"なかなか歩道橋を最近使われる方は大変少ないかと思うんですけれども、この歩道橋がいまだにあることで、歩道を、ただでさえ狭い歩道がますます狭くなって歩きづらいとか、そういったお話をよく聞くんですけれども、最近歩道橋ってそもそも設置されたことがあるのかということと、また、こういった歩道橋が撤去されるという可能性というか。","respondent":"稲田道路課長","answer":"しかしながら、やはり交通事故は減ってきていますけれども、全く事故がなくなったというわけではございませんので、横断歩道橋を今後撤去するというところに当たりましては、非常に慎重な対応、検討、調査というものが必要になってくると思います。","voiceIndex":12,"id":"exchange-005"},{"speaker":"沢田委員","kind":"質問・要望","question":"特に耐震補強設計について、お伺いさせていただきたいんですけれども、これは２分の１で２０万円上限の補助ということで、昨年度の平成２３年度の予算では１,０００万円ということでしたけれども、決算では４７８万円と、大体半額ぐらいしか利用されなかったということで、また平成２４年度は４,３００万円ということで、予算が今度は決算の１０倍ぐらいになっているわけなんですけれども。","respondent":"品川防災整備担当課長","answer":"そこを何とか助成してほしいという声が多いということで、平成２３年度からこの耐震補強設計のほうを新たに助成制度として設けたという状況です。","voiceIndex":16,"id":"exchange-006"},{"speaker":"沢田委員","kind":"質問","question":"やはり設計に助成するというのは、どちらにしろ設計から今度改修に移っていかないといけないということだと思うんですけれども、だったら私は改修のほうとか、建替の助成とか、そちらのほうに重きを置いたらいいのかなということでちょっと質問をさせていただきましたが、時間がないので、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-007"},{"speaker":"鶴委員","kind":"質問","question":"なので、いわゆるまずこういう歩行者優先道路、区道に設置されてある歩行者優先道路が幾つぐらいあるかということと、あと、現状はそれではいけないと思うんですけれども、そういうほとんど、まあ、言葉はあれですけれども、有名無実化になっているような箇所、そういったことが区としては一応認識しているかどうか、その辺あれば、その箇所も教えていただければと思います。","respondent":"谷口交通安全担当課長","answer":"委員のお尋ね、歩行者優先道路ですが、私の把握している中では現在１２カ所ですね、１２路線。","voiceIndex":20,"id":"exchange-008"},{"speaker":"鶴委員","kind":"確認","question":"まあ、それ自体が区でやることかどうかというところもあると思うんですけれども、ただ、道路標識上は、当然その時間帯に車が入っていけば、車は道路交通法ですかね、それで、厳密に言うと罰則されるという形になっていると思うんですけれども、それはそれとして、もっと大事な、先ほどガードレールとか通学路の話ありましたけれども、やはりそこに歩いている子どもとか、普通の歩行者に。","respondent":"谷口交通安全担当課長","answer":"その必要な対策とその有効性、その実施の可否等については、警察と検討協議をしてまいりまして、注意看板の設置だとか、さまざまな広報活動をやりまして、地域、学校、警察、道路管理者が一体となりまして、子どもの事故防止対策を第一に優先に取り組んでまいりたいと思います。","voiceIndex":22,"id":"exchange-009"},{"speaker":"鶴委員","kind":"質問・要望","question":"ぜひしっかり連携をとっていただいて、子どもだけではなくて、歩行者の事故防止に努めていただきたいと思います。別な場所でまた教えていただければと。次に行きます。確認になります。平成２３年度、震災直後での工事で決算書には４橋ですか、あるということで、予算書を見ますと、予算ベースでは５橋ということなんですが、ただ、その上で執行率が１０２％ということなんですね。","respondent":"稲田道路課長","answer":"江川橋の断面補修です。それから市場橋、これは塗装の塗り替えということで実施してまいりました。予算では浜川橋を考えていたんですけれども、東海道、まあ、地域の景観との関わり合いもございまして、その辺の検討が必要だろうと。","voiceIndex":24,"id":"exchange-010"},{"speaker":"鶴委員","kind":"質問・要望","question":"橋のところは、ありがとうあります、わかりました。今の件はわかり次第教えていただければと思います。とにかく命を守るという観点でインフラの整備ないし保全についての角度で推進をしていただきたいと思うんですが、今言ったようなところがあったかどうか、これを教えてください。","respondent":"稲田道路課長","answer":"そういうところにおきましては、現在ほとんどの橋梁が落橋防止と耐震化が終わってきている。残すところ４橋程度というところで行っております。","voiceIndex":26,"id":"exchange-011"},{"speaker":"鶴委員","kind":"質問","question":"質問させていただいたのは、計画の中で７０橋たしか管理されていると伺ったんですけれども、その中で、予防保全でがっと全部計画を立てていただいて、何カ年、何カ年という計画あると思うんですけれども、その中で架け替えにしたほうがいいと思うようなことが平成２３年度の中であったかどうかという質問だったんですけれども、そこがもしわかれば。","respondent":"稲田道路課長","answer":"長寿命化の計画の中において、架け替えをしたほうがいいという橋梁は１橋、今のところあります。北品川橋です。","voiceIndex":28,"id":"exchange-012"},{"speaker":"鶴委員","kind":"質問・要望","question":"今教えていただきました。では、時間もありますので、次の１７１ページ、耐震シェルター等設置助成に移りたいと思います。この件については、ことしの予算特別委員会で山元議員のほうからも質問していますが、確認も含めてします。その上で、現在、今走っているこの年度の設置件数ですとか、また、設置業者についての登録制ですね、これについての進捗状況を教えていただきたいと思います。","respondent":"品川防災整備担当課長","answer":"耐震シェルターのお尋ねですが、まず平成２４年度の実績ですけれども、現在品川シェルターに関しては８件、これはもう既に全部設置済みです。それから、一般のシェルターに関しましても、４件実績のほうがあります。","voiceIndex":30,"id":"exchange-013"},{"speaker":"鶴委員","kind":"質問・要望","question":"時間があれですので、答弁の時間残したいと思いますけれども、今、実績かなりぐっと増えたのかなと思います。テレビの効果も含めて、また講習の効果もあったのかなと考えます。なので、設置業者による施工ですかね、今までのやり方と違う形でやった部分と、その辺のもし違いがあれば教えていただきたいというところと、あと、予算のほうのとり方なんですね。","respondent":"品川防災整備担当課長","answer":"都費のほうはない状況です。ほかの一般シェルターに関しましては、国費、都費両方とも補助を行っている状況です。それから、金額のほうですけれども、品川シェルターのほうは全額今のところ８件負担なく支給をしている状況です。","voiceIndex":32,"id":"exchange-014"},{"speaker":"藤原委員","kind":"確認","question":"これからどうするのかお伺いをします。具体的に西大井四、五丁目のあたりの新幹線の下の山王銀座商店街のところの、豪雨になると水が出る、あそこの場所もいろんな施策をしていただいていると思うんですけれども、それがどういう進捗状況がということが１点と、もう一つは、やはり東京都から課長に来ていただいているということがプラスになっているのかというあたりも、その辺についてもお伺いをします。","respondent":"小林土木管理課長、谷口交通安全担当課長、藤田都市計画課長、多並公園課長、山崎マスタープラン担当課長、稲田道路課長、武藤河川下水道課長、溝口都市開発課長、大串住宅担当課長","answer":"道路、公園等の監察、占用のお尋ねですけれども、道路や公園には、例えば道路へのはみ出しなど、不正な利用形態もありますので。委員お尋ねの放置自転車対策、前任者からの引き継ぎですけれども、条例に規定どおり、駅周辺の通勤、通学。都道におけます電線類の地中化等の関係ですけれども、東京都のほうでは都市計画道路については基本的には電線類の地中化を進めるということで。昨年度１年間においては、公園、区内全体の公園で３８１台の撤去を行ったり、今後も丁寧にこのような対策を行っていきたい。","voiceIndex":35,"id":"exchange-015"},{"speaker":"藤原委員","kind":"質問","question":"監査という形で、監察という意味で、不法占拠をしているところというのは品川区にどのぐらいあるのか教えてください。それと、もう一つ伺っておきたいのは、道路公園課というのが道路課と公園課に変わりましたよね。分けましたよね。そこの半年たってメリットというのはどういう形で今、区民にとってのメリットというのはどういう形で出てきたのかということも教えてください。","respondent":"小林土木管理課長、多並公園課長、稲田道路課長","answer":"現時点においては、公園課、道路課ということで分けて、区民の方からいいますと、わかりやすく、公園なら公園、道路なら道路ということで。道路のほうにおきましても、やはり設計と維持管理部分が分かれていたんですけれども、それが一緒になることによって仕事の効率が上がり。","voiceIndex":45,"id":"exchange-016"},{"speaker":"木村委員","kind":"質問","question":"私からは１６３ページの道路維持費、それから、まあ、それだけ先行きます。危険な箇所が１９３カ所、そして特に危険な箇所、９４カ所ということで、区が対応するところが大体５７カ所ぐらいと言われましたけれども、今回このようなことを、調査があって、今回初めてわかったのでしょうか。そして、以前このようなところで事故は起きていないのかどうか、お答えください。","respondent":"稲田道路課長","answer":"道路管理者が対応する箇所、５７カ所というところで今回抽出されたんですけれども、私ども、安全対策は今までも行ってきております。毎年学校からの意見を聞いたり、それから、警察署との情報の交換などを行いながら、その時点での安全対策というところで行ってきております。","voiceIndex":51,"id":"exchange-017"},{"speaker":"木村委員","kind":"意見","question":"先ほどありましたけれども、ＮＨＫのニュースによると、品川区、夏休み前に南品川の区道で道路に色を塗って準歩道を整備されたとの報道もありました。子どもたちを守る方法として、道路課はどのような対応をお考えか、お聞かせください。そして、予算との関係もあろうと思いますが、どれほどのスパンとスケジュールで対応されるのか、ご説明をください。","respondent":"稲田道路課長","answer":"今回抽出されたところにおきまして、準歩道のカラー化をやっていきたい。それから、警戒標識の設置ですね。やはり運転者にスピードの抑制、これを行ってもらうというところで、警戒標識の設置、交差点の見通しというところでカーブミラーの設置等も考えておるです。","voiceIndex":53,"id":"exchange-018"},{"speaker":"木村委員","kind":"質問・要望","question":"道路課、そして教育委員会、そして警察との合同点検は、ことし限りなのか、またこれからも継続されるお考えがあるかどうか。平成２３年度の決算には、道路安全施設費の中の整備工事、約５,７２９万円余が執行されております。来年度は平成２３年度を超える費用が必要となろうかと思いますが、どのようにお考えでしょうか、お聞かせをください。","respondent":"稲田道路課長","answer":"ただ、今までは個々にやってきたところだったんですが、今回３者で同時にして同じ問題を考えてきたというところは非常に効果的であったですので、今後とも協力関係を持ちながらやっていきたいです。それから……。","voiceIndex":55,"id":"exchange-019"},{"speaker":"木村委員","kind":"質問","question":"よろしくお願いをいたします。次に、１６２ページの下から１０行目、駅周辺等放置自転車対策費についての質問です。その中で、放置自転車を減らすことを前提で質問をしていますが、絶対にゼロにはならないと思いますけれども、啓発費や撤去費を減らすためには１カ所でも多くの駐輪場をつくったほうがいいと思っています。歳入でもお聞きしましたけれども、再度お答えを願います。","respondent":"谷口交通安全担当課長","answer":"駅周辺のまちづくりなど、動向を注視しながら、自転車駐車場の確保に努めて調査研究をしてまいりたいと考えています。","voiceIndex":59,"id":"exchange-020"},{"speaker":"木村委員","kind":"意見","question":"今、歩道は人が優先なんですけれども、自転車が今平気で結構いろんな角度から通行してくるということで、大変人身事故も増えていると思います。このようなところに啓発費をどんどん回していく、そういうお考えはないのか。そして、このことに対して、区として何かもっとはっきりとした何かものを打ち出していく、何かそういうお考えはあるかどうか、お聞かせください。","respondent":"谷口交通安全担当課長","answer":"啓発費を自転車事故防止対策に向けるということで、今現在も実施をしておりまして、今スケアードストレートというスタントマンを活用しての事故防止対策、委員ご案内のとおりですが、それをもっと増やして。","voiceIndex":61,"id":"exchange-021"},{"speaker":"木村委員","kind":"質問・要望","question":"ぜひやっていただきたいと思います。次に、１６４ページの道路バリアフリー事業についてです。バリアフリー事業、平成２３年度はマイナス約４８０万円ぐらいですか、で、５,６５３万円余になっています。横断歩道の段差、これ、実際は１５センチぐらいということなんですけれども、横断歩道と普通の歩道との直接のところですかね、ここは大体のことだと２センチほどの高さがあるということ。","respondent":"稲田道路課長","answer":"これは視覚障害者が横断するときに必要なものでございまして、ゼロ段差をやっているときにおきましても、裏に点字ブロックを設置したりしてやっております。","voiceIndex":63,"id":"exchange-022"},{"speaker":"中塚委員","kind":"質問・要望","question":"私からは１６７ページのまちづくりマスタープラン策定費を伺いたいと思います。そもそもこの計画策定にかかわっている委託業者というのでしょうか、コンサルタントというんでしょうか、その業者がどこなのか、どのようなかかわりなのか、伺いたいと思います。この２路線について、道路整備に伴って、立ち退きなど、影響を受ける住宅戸数、商店街、公共施設の数をご説明いただきたいと思います。","respondent":"山崎マスタープラン担当課長、藤田都市計画課長","answer":"コンサルタントの関係です。昨年度が国際航業株式会社、本年度がパシフィックコンサルタンツ株式会社です。２７号線のほうにつきましては、約２００戸が計画線にかかる建物です。公共施設については２つ、商店街については２商店街ということになってあります。将来都市構造図におけます拠点の考え方です。","voiceIndex":66,"id":"exchange-023"},{"speaker":"中塚委員","kind":"質問","question":"初めに都市計画道路ですけれども、２７号線は桜新道から品川郵便局裏と言えばよいのでしょうか、整備を検討と、２２０戸の住宅が影響します。この５本の都市計画道路を動かそうとしているわけですけれども、それぞれ完成はいつを目指しているのか、改めて伺いたいと思います。住宅戸数が１,１００戸ですから、数倍規模に影響が及ぶと思うんですけれども、そこのご見解を伺いたいと思います。","respondent":"藤田都市計画課長、山崎マスタープラン担当課長","answer":"３１号線、２０５号線、２７号線につきましては、マスタープランの中に書かれた都市計画事業ですので、これらの事業については、マスタープランの中で目標に向けて事業を進めていくというような考え方です。この地域生活拠点の考え方ですけれども、より身近な生活圏として、医療、福祉、教育等の生活サービス機能、それから、地域コミュニティー機能の整備、特徴ある商店街の魅力の向上、快適な歩行空間の整備などを図るとともに。","voiceIndex":70,"id":"exchange-024"},{"speaker":"中塚委員","kind":"質問・要望","question":"戸越公園のほうを伺いたいんですけれども、この地域生活拠点という位置づけでは、西大井駅前と同じだったと思います。沿道開発につきまして、今回の補正予算でも調査費用が盛り込まれましたが、この放射２号線、２９号線の沿道というのは、結構路線としては長いですけれども、どこからどこ、全部なのか、一部なのか、その調査の範囲を伺いたいのと、沿道何メートルなのか、改めて伺いたいと思います。","respondent":"山崎マスタープラン担当課長、藤田都市計画課長","answer":"いろいろこれからその沿道の地権者の生活再建も踏まえながら、本事業については丁寧に対応していかなければいけないということの１つの一例として、そうした従前居住者対応の例示として。コンクリートの壁にするかというようなご質問もありましたけれども、先ほど申したとおり、どのような形で検討を進めるかで答えは変わってくるのかなと思いますので、その辺についても十分な検討をしたいと考えています。","voiceIndex":73,"id":"exchange-025"},{"speaker":"中塚委員","kind":"確認","question":"それと、素案を見ると、大井地区では２９号線、３１号線の整備を進めるとともに、地区計画等を活用したまちづくりを具体的に検討とあります。この比較的まとまった未利用地とはＪＴ跡地のことを指しているのかどうか確認したいのと、周辺と調和したまちづくりとは、大崎や大井町や今後進める武蔵小山や、こうしたまちとの調和という意味合いなのか、どこを指しているのか伺いたいと思います。","respondent":"山崎マスタープラン担当課長、藤田都市計画課長","answer":"豊島区の事例につきましては、都市計画道路整備に合わせ、従前居住者向けの住宅整備、共同化を実施した先行事例として参考に提示をしています。しかしながら、不燃領域率の低いエリアとなっていますので、特定整備路線ということではなく、例えば不燃化特区のほうの本格実施、こういったような事業についても１つの検討材料になるのかなと考えています。","voiceIndex":76,"id":"exchange-026"},{"speaker":"松澤委員","kind":"質問","question":"１点目は１６４ページ、補助１６３号線整備について、２点目が、今お話が出ていましたけれども、木密地域不燃化１０年プロジェクト、特定整備路線の計画進捗について、３点目が、１６８ページのしながわお休み石設置事業についてお伺いをしたいと思います。これの進捗状況、果たしてこれが、平成２７年度まで事業認可とっていますけれども、この完成の見通しについてもお伺いしたいと思います。","respondent":"稲田道路課長、藤田都市計画課長","answer":"１６３号線の測量経費についての内容ですが、１６３号線のガードから大崎に向かったほうの道路の測量等を実施いたしました。東京都のほうには一日でも早く完成ができるようにこれからもお願いをしていくという考え方です。","voiceIndex":82,"id":"exchange-027"},{"speaker":"松澤委員","kind":"質問","question":"１日８,０００台から、もうちょっと多いかもしれない車があそこを通るわけですから、当然右折、大崎から区役所の前を通って右折する、その車路は当然出てきます。上げると恐らく４０億円近くかかるというんですかね、１センチ、２センチ上げたって、ぽこんとそこだけ上げるわけにいかないですから、全体、山のように上げてくると。この難工事を何としても２６号線完成までにやらなくてはいけない。","respondent":"稲田道路課長","answer":"当然整備を進めていくというところでございまして、重要なポイントだと考えております。２６号線の開通に遅れることなく頑張っていきたいと思っています。","voiceIndex":85,"id":"exchange-028"},{"speaker":"松澤委員","kind":"質問","question":"実は２６号線、大崎高校の入り口からこちらの豊町二丁目ですかね、歩道は完成しているんですよね。これを開放するとかというお話を前に伺ったことがあります。私個人的には開放反対派なんですけれども、あれが開放するという話が今度の東日本大震災によって電気の関係で遅れていると聞いていますけれども、あれ、本当に開放する気があるのか、その辺の計画をお聞きしたいと思います。","respondent":"藤田都市計画課長","answer":"今年度中を目途に調整をしていきたいというふうに聞いてございまして、現在それを進めているところということで、地域の方々とも十分なお話をしながらこの答えを出していかなければいけないのかなと私どもも感じておりますので。","voiceIndex":87,"id":"exchange-029"},{"speaker":"松澤委員","kind":"質問・要望","question":"あそこは坂になっていますので、大変にそこに歩行者と自転車が通るというので、危険があるのではないかという声があるのと、やはり見通しが悪いので、防犯カメラを設置していただきたいという声が大変にあるわけです。その辺をクリアしない限りは開放してもらいたくないと思っているんですが、その辺の考え方をお聞きしたいと思います。","respondent":"藤田都市計画課長","answer":"いずれにしても最終的にでき上がったときには開通をさせるわけですので、その際に地域の皆様方が安心して通行できるような形、そういったものを目指して東京都のほうと調整を進めていきたいと考えています。","voiceIndex":89,"id":"exchange-030"},{"speaker":"松澤委員","kind":"質問・要望","question":"２点目にまいります。木密地域不燃化１０年プロジェクト、今も前の委員の話がありましたけれども、東京都が６月に２３カ所を指定した。品川区では２９号線と放射２号線の２路線。いろいろほかでは動いてきているんですね。実はあそこには一番の問題点として戸越公園の高架化があると思うんですね。この方たちとの整合性というんですか、どのような形で協働していくのかについてお教えいただきたいと思います。","respondent":"藤田都市計画課長、山崎マスタープラン担当課長","answer":"特定整備路線としての補助２９号線の関係ですが、２９号線としては、６月の公表以来、東京都として生活再建のための支援策の検討ということで、今それを進めているということで、この秋、もう秋にかかってありますが。今後その整備の方針等々につきまして、地元のまちづくり協議会のほうと正確な情報のやりとり、あるいは丁寧な説明を通してスムーズな事業展開に努めてまいりたいと、こういった考えで進めてまいりたいと考えています。","voiceIndex":91,"id":"exchange-031"},{"speaker":"松澤委員","kind":"質問・要望","question":"あるいは、賛成なんだけれども、これによって自分の町会が二分されてしまうという町会もあるんですね。慎重に事を進めながら、粛々とこの計画を進めていただきたいと要望しておきます。３点目、しながわお休み石設置事業、８基３０９万４,５００円。これ、１基、１つ３７万円ぐらいになるんでしょうか。この辺の数字の考え方と、このお休み石事業についてお伺いしたいと思います。","respondent":"山崎マスタープラン担当課長","answer":"こちらのほうは、設置の工事費等々も含んだ総額です。それから、お休み石につきましては、平成１０年度から本格的に制度がスタートして、昨年末までに２６８基、区内随所に設置をしているものです。","voiceIndex":94,"id":"exchange-032"},{"speaker":"松澤委員","kind":"提案","question":"このお休み石というのは、区政モニターの席の中で提案されて、これを受け入れて品川区で事業化したということで、大変にすばらしい事業だと思って、これがもう平成１０年からというと、１４年、もう１５年ぐらいになるという形になるんでしょうか。これが、お休み石って、座ったことありますかね。何かの記念にお休み石をつくってくださいということで、これ、５万円から１０万円出すと記念につくってくれる。","respondent":"山崎マスタープラン担当課長","answer":"平成２３年度におきましては、一口５万円でお願いしておりまして、５口です。一昨年が７口。ということで、大体七、八口が平均で推移しています。","voiceIndex":96,"id":"exchange-033"},{"speaker":"松澤委員","kind":"質問・要望","question":"実は私の知り合いが、８０歳になって腰が最近痛くなって、お休み石座ったら、すごくいいね、だから８０歳の記念につくりたいということで、２基申し込んでつくっていただきました。とてもいい制度だと言うんですね。これが事業見直し、Ｃになっているので、この辺の考え方、まあ、この辺はちょっと時間がないから聞けませんけれども、この事業は推進していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":98,"id":"exchange-034"},{"speaker":"阿久津委員","kind":"提案","question":"ちょっとこれは極論なんですけれども、近所の住民の方からも提案があって、その方、アメリカ在住が長かったんですが、アメリカなんか行くと、八潮のあの直線道路にあるみたいなでこぼこの道、減速をせざるを得ないような道、ああいうのを品川区でも取り入れたらどうなのということでご提案も受けまして、そういうご提案もあったんですが、なかなか道路をうねうねさせるというのは難しいかもしれないんですが。","respondent":"稲田道路課長","answer":"そうはいいましても、先ほど申しましたような現状があるですので、今後検討できる対策、いろいろ新しい工法も出てきておりますので、考えながらやっていきたいと考えています。","voiceIndex":100,"id":"exchange-035"},{"speaker":"阿久津委員","kind":"質問","question":"加害者側が警察官に説明しているところにも私立ち会ったことあるんですけれども、車が右折したらいきなり自転車が出てきて、何もわからないままぶつかってしまったということを警察官に説明していたり、非常に事故が多いと思うんですが、これも我々の先輩方からもいろいろ引き継ぎ事項であるんですけれども、これは区のほうにも何度も申し入れたし、また。","respondent":"藤田都市計画課長","answer":"国道のほうも、概成区間ということで、将来的にはやはり拡幅になるということで、繰り返しになりますけれども、そういった事業とあわせて進めないとなかなか改善ができないというような部分かなと考えております。","voiceIndex":102,"id":"exchange-036"},{"speaker":"阿久津委員","kind":"質問・要望","question":"私がお願いしたいこと、今課長、全部言っていただいたので、そのように推進をして、ぜひ強く関係機関に働きかけをしていただきたい。地域の方のご意見をよく聞いていただいて、働きかけをしていただきたいと思います。","respondent":"山崎マスタープラン担当課長","answer":"お休み石につきましては、事業開始から１６年、２６８基の成果を踏まえつつ、いろいろ分析をさせていただいて、今回事務事業評価もＣという評価をいただきました。","voiceIndex":104,"id":"exchange-037"},{"speaker":"阿久津委員","kind":"質問・要望","question":"確かにちょっと木でできているので、古くなってしまってぼろぼろになってしまっているというご意見をよく伺いますので、修繕のほうまた進めていただけるということで、よろしくお願いいたします。ですから、歩道の幅が問題となるということもあるとは思うんですが、これは東京都とか国に何か働きかけるすべはないのか、そこのところの考え方、教えていただきたいと思います。","respondent":"中村建築課長","answer":"この安全性につきましては、十分配慮すると同時に、さらに東京都や国に対しましても、こういった基準をもっと明確に、あるいは設置しやすいような形で直して考えていただけるような認識を持っていただけるように、これからまた機会ごとに働きかけてまいりたいと考えております。","voiceIndex":106,"id":"exchange-038"},{"speaker":"阿久津委員","kind":"質問","question":"５月に地元のまちづくり協議会のほうの品川駅南地域の未来を創る推進協議会がまとめた提言書が区長のもとに手渡されて、それをもとに平成２４年度に品川駅南地域まちづくりビジョン策定を予定しているということで、たしかちょっと伺ったところによると、この９月ぐらいにある一定の方向性が出ると聞いていたんですけれども、それについてまだ何も伺ってないものですから。","respondent":"溝口都市開発課長","answer":"現在私どものほうが進めております品川駅南地域のまちづくりビジョンの策定状況についてお答えいたします。","voiceIndex":108,"id":"exchange-039"},{"speaker":"阿久津委員","kind":"質問","question":"わかりました。状況についてはわかったんですけれども、１つ、２つでもいいんですが、どんな方向性なのか、少し教えていただけたらと思います。","respondent":"溝口都市開発課長","answer":"そういったものを受けまして、しっかり品川駅の南の玄関口としてふさわしい拠点性を備えるですとか、また、近くには品川浦等の水辺もありますので、多彩な表情を持った、水辺を親しむまち、そういったものを生かしながら。","voiceIndex":110,"id":"exchange-040"},{"speaker":"阿久津委員","kind":"質問・要望","question":"よくわかりました。先ほど北品川橋の架け替えの話もちょこっと出ましたけれども、多分そういったこともいろいろ勘案しながら今考えられているのかなと思います。ぜひ地元の方のご意見、そしてご要望を取り入れて、地域が活性化するようなまちづくりのマスタープラン、ぜひつくっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":112,"id":"exchange-041"},{"speaker":"原委員","kind":"質問","question":"私のほうからは、成果報告書の１６２ページ、土木管理費、用地管理費６,２７０万円、それから、１６４ページのほうの道路改良費１４億８,３８０万５,５４２円、１６５ページ、私道整備事業、それが８,４２６万５１１円などについて、あと、関連してお伺いをしてまいります。よろしくお願いします。","respondent":"小林土木管理課長、中村建築課長","answer":"道路台帳関係の事務ですが、道路法第２８条により義務づけられている道路台帳について、随時路線等に変更が生じます。建替える際に、建築主、あるいは設計者がこの道路が建物の建替えのできる道路なのかどうか、こういったものを正確に把握できるために、把握していただくために、台帳を整備いたしまして、窓口で混乱のないように閲覧をしていただく。","voiceIndex":115,"id":"exchange-042"},{"speaker":"原委員","kind":"質問","question":"そうしましたならば、平成の２２年度からは区条例等によりまして区有の通路や法定外の公共物の台帳整備も進みまして、道路台帳の補正実績の実施数量が平成２１年度が５万６,３３２平米だったものが、平成２２年度には８万９,２６８平米と伺っておりますけれども、区有道路、それから、あとは法定外公共物についてちょっとご説明をいただければと思います。","respondent":"小林土木管理課長","answer":"今ご指摘のありました、平成２２年３月に法定外公共物管理条例を制定いたしまして整理いたしましたときに、公共の用に供する道路、河川、水路、あるいは溝渠ならびにこれに属する工作物等のうち、道路法、河川法、そして今ご説明しました区有通路条例が適用されていないもの。","voiceIndex":118,"id":"exchange-043"},{"speaker":"原委員","kind":"質問・要望","question":"、ご丁寧に。そうしますと、それで本委員会の資料といたしましては、事務事業評価結果一覧がこれは６９ページなんですけれども、指定道路等台帳整備事業、それからあと、細街路拡幅整備事業、私道整備事業について伺いたいんですけれども、指定道路台帳についてはどのぐらい電子化が進んでおられるのか。それからあとは、防災機能上の向上のために、細街路拡幅整備事業。","respondent":"中村建築課長","answer":"ですので、品川区は助成制度におきましてもかなり手厚い制度になっているとは考えられますが、ただ、今後本当に必要とされている方に対しての、必要とされている方の申請に対して整備を進めていけるように。","voiceIndex":120,"id":"exchange-044"},{"speaker":"原委員","kind":"質問・要望","question":"というのは、やはりいつも、本当に所管のセクション、人数少ない中で必死に動かれていて、スケジュール的にもすごい大変なことを十分私は理解をしているつもりなんですけれども、実際に品川区の行政の維持管理の土地だけではなくて、言葉が適切かどうかわかりませんけれども、宝探しのような形で、もしこれ、品川区が所有するものが出てくれば、というのは、具体的には境界、官民境界なんかでよくある。","respondent":"小林土木管理課長","answer":"これにつきましては、この間、平成１３年度から国が一括で譲与してきたもの、いただいた段階で既に境界は決まらず、そしてまた不法占用も散見されるという状況の中で、区として積極的に優先順位をつけて貸与をし、境界も含めて確定する中で、機能を喪失したものにつきましては。","voiceIndex":122,"id":"exchange-045"},{"speaker":"原委員","kind":"意見","question":"本当に少ない職員の数で頑張っておられるのはわかるんです。わかるんですけど、きょう午前中に藤原委員からもお話があったように、不法占拠状態の問題ですとか、それから、やはり国から来たときに、確定はされているというものの、まだまだ資料的に不明瞭だったり、不確定だったりするところがありますので、大変恐縮ですけど、もう１回そこの思いをお話しいただければと思います。","respondent":"小林土木管理課長","answer":"ご指摘の点につきましては、最終的には区民の財産という観点、そして、それにつきましては、公共性と同時に公平に対応していく行政としての姿勢という観点から、積極的に払い下げ、もしくは、払い下げの希望があるところは。","voiceIndex":124,"id":"exchange-046"},{"speaker":"原委員","kind":"質問・要望","question":"実際に実例的に私道のつけかえの問題ですとか、そういったこと、いつも、我々、予算とか決算特別委員会のときには、どうしても都市計画とか開発のほうに目が行きがちなんですけれども、やはり基本の基本ですので、土地は動きませんので、だけれど、そうかといって、これが個別で一つ一つ案件が違ってまいりますので、その辺のところを注意深く運んでいただきたいと思いますので、これは最後、もう一度。","respondent":"小林土木管理課長","answer":"それぞれのその思いだとか流れを踏まえて、しかし、区として管理の徹底、公平性の確保ということで、ケース・バイ・ケース、個々の求めを公平に判断しながら適切に対応してまいります。","voiceIndex":126,"id":"exchange-047"},{"speaker":"稲川委員","kind":"質問","question":"それに伴って、西口のロータリーに進入してくる車両というんですか、まあ、人も増えると思うんですが、車両も増えることと私は予想しております。そしてその中でも危険度が高いところにお住まいの方が多いと思いますが、そういう部分でスピーディーに行うのも含めて、優先順位ですか、危険度が４より５を先にやるとか、そういったことをどうお考えなのかをお聞かせください。","respondent":"溝口都市開発課長、品川防災整備担当課長、稲田道路課長","answer":"ですから、今後まちづくりを進めていく中で、そういった大井町駅のハブ化ですとか、そういったものを進めていきたいと考えております。今年度、１件用地購入ができる見込みとなっております。それから、整備のほうが２件できればというような形で進んでおります。ただ、その先の原踏切におきましては、現状まだ調査等行っていないというところでございまして、今後、その先の２９号線との関係も出てくると思いますので。","voiceIndex":129,"id":"exchange-048"},{"speaker":"稲川委員","kind":"提案","question":"これに関しては、よく聞く話で、やる気満々で診断を受けたけど、なかなか診断に来ないということで、要するに大体年内中には診断もすべて終わって、なおかつ建替改修も行って、新年をそこで迎えるような、ライフスタイルというんでしょうか、ライフスケジュールというんですかね、結構みんなそれをつくって多分改修とか行うと思いますので、人的な部分もあろうかと思いますが。","respondent":"品川防災整備担当課長","answer":"耐震診断の診断が終了したという表示に……。","voiceIndex":133,"id":"exchange-049"},{"speaker":"本多委員","kind":"質問・要望","question":"１６５ページの涼のみち整備事業、１６８ページの可動式ホーム柵整備助成、１７０ページの百反歩道橋架替関連整備費、１６９ページ、都市開発費、１つずつお聞きします。初めに、涼のみち整備事業なんですが、遮熱性舗装、計画どおり進んだのか、その平成２３年度の効果というものをお聞かせいただきたいと思います。","respondent":"稲田道路課長","answer":"遮熱性舗装の平成２３年度の実績ですが、西小山駅前広場、７３９平米実施しました。それから、準歩道遮熱性舗装というのを試験的に５４２平米ほど実施しております。","voiceIndex":138,"id":"exchange-050"},{"speaker":"本多委員","kind":"質問・要望","question":"さらに６度下がったというようなことでいいんでしょうか。まあ、効果があったというふうに理解します。","respondent":"稲田道路課長","answer":"スタンドパイプを使って路面の温度を下げるというご提案なんですけれども、私どもとしましては、環境課がやっています打ち水大作戦とかいうので、地域の方に夕方水を路面にまいていただけると、非常にそういう面では全域に広がって効果があるのではないかと考えておりまして。","voiceIndex":140,"id":"exchange-051"},{"speaker":"本多委員","kind":"質問","question":"次の質問に移ります。１６８ページの可動式ホーム柵なんですけれども、先ほども出ておりまして、区内４０の駅がある中で、１０カ所済んだということで、この財源も３分の１ずつ、国、区、事業者ということなんですけれども、この鉄道事業者がその３分の１の補助がないと安全対策をしないのではないかという疑問を持つんですが、これについてはどのように考えるんでしょうか。","respondent":"山崎マスタープラン担当課長","answer":"東京都とともにこうしたホーム柵の整備を進める上での課題をまず検討しようというようなことで、第一歩を踏み出しているというような状況です。","voiceIndex":142,"id":"exchange-052"},{"speaker":"本多委員","kind":"質問・要望","question":"安全をさらに進めていただきたいと思います。この転落８件あったということなんですけれども、ホーム下の待機避難というのが鉄道事業者のホームによってあるところとないところとかあると思うので、この辺は、何ていうんですかね、区がいくら指導してもやっていただくのは鉄道事業者になると思いますので、その辺、万全の体制をしていただければと思います。次の質問に移ります。車のほうですね。","respondent":"溝口都市開発課長","answer":"百反ずい道の一方通行化についてお答えいたします。これはやはり一方通行化することによって、初めて現況の幅員の中で歩道設置ができるというものですので、多少車にお乗りの方には遠回りと不便になるところはありますが、交通安全上は必要な事業だと考えております。","voiceIndex":146,"id":"exchange-053"},{"speaker":"本多委員","kind":"質問","question":"歩道の整備は本当に進めていただいて、車道については、これ、もうちょっと工夫ができないのかなと思うんですので、百反ずい道もそうですし、あと、広町一丁目周辺地区道路、区画道路１号のＡ区間についても、その関連で一方通行にしていくという予定なんですが、これはもう何ていうんですかね、整備をそうされたときの混乱というのがもう目に浮かぶようなんですが、工夫ができないでしょうか。","respondent":"溝口都市開発課長","answer":"そういった中で考えておりますので、なかなか現況の中で車道を広げるとか、そういったものは、百反ずい道については、物理的に難しい部分もありますので、どうしても一方通行化していかなければいけない部分があります。","voiceIndex":148,"id":"exchange-054"},{"speaker":"本多委員","kind":"質問","question":"歩道の幅というのはどのくらいを考えているんでしょうか。歩道の必要な部分をとっても、車道が現状のとおりにいけないものかということです。歩道の幅、お聞かせください。","respondent":"溝口都市開発課長","answer":"現在百反ずい道付近に設置する歩道の幅員につきましては、１.５メートルを予定しております。すいません。間違えました。申しわけありません。１.５メートルではなくて、すいません、２.５メートルの歩道幅員を確保するという形で現在計画しております。","voiceIndex":150,"id":"exchange-055"},{"speaker":"塚本委員","kind":"質問・要望","question":"利便性の大変高い公共交通、今現状でもサービスがあると思う中で、一方、区民の方からはさまざまな、より充実した公共交通、バスなどの、コミュニティーバスなどの公共交通の要望がいろいろ出ているという中で、やはり費用対効果というのを念頭に置くというのは十分に置かなければいけない点だと思いますけれども、コミュニティーバスのような運用形態、こういったものも含めて。","respondent":"藤田都市計画課長","answer":"さまざまな状況の変化があれば、需要が出てくれば、それに合わせたバス事業者としてもさまざまな策を考えると思いますので、区としてもさまざまな状況をバス事業者に提供しながら。","voiceIndex":153,"id":"exchange-056"},{"speaker":"塚本委員","kind":"質問・要望","question":"この区民のニーズというものに応えるという点で、さまざまな可能性、これを追い求めるというような姿勢でぜひ臨んでいっていただきたいと思うんですけれども、そういった中で、この前の先だっての一般質問のいただいた答弁の中で、補助２６号線と補助１６３号線、この公共交通ネットワークを検討する必要があると、こういうふうなお話がございました。","respondent":"藤田都市計画課長","answer":"補助２６号線ですけれども、完成に合わせて、ぜひ、武蔵小山のほうにも駅前広場ができましたし、そういう観点で大井町と武蔵小山のほうを結ぶような路線の検討というものをお願いをしているところです。","voiceIndex":155,"id":"exchange-057"},{"speaker":"塚本委員","kind":"質問","question":"もうちょっと詳しくお伺いしたいんですけれども、補助２６号線につきまして、これはいわゆる採算性という部分では、今武蔵小山から大井町というお話出ましたけれども、一定の採算性をバス事業者としては見ておられるのかどうかというところと、あと、１６３号線、大崎から大井町ということで、あそこのガード下、区役所の坂下ったところのガード下。","respondent":"藤田都市計画課長","answer":"１６３号線ですけれども、大井町のところから大崎のほうに抜ける、現行のところの都市計画道路としての整備が進めば、そちらについても改めて区のほうからお願いをするということで、現行の今の通りのままバス路線を増すというのは若干無理があるかなと考えており。","voiceIndex":157,"id":"exchange-058"},{"speaker":"塚本委員","kind":"意見","question":"鉄道部分というのはあくまでも九州産業全体の中でのＰＲ部門なんだと。都市計画全体の中でこういった民間事業者とのいろんな議論を交わす中で、ぜひさまざまな路線で採算性がもしとれるのであれば、あまり採算性がとれないところも走らせてもらうとか、こういった面も含めてぜひ検討をお願いしたいと思うんですけれども、もう一度最後にご答弁お願いしたいと思います。","respondent":"藤田都市計画課長","answer":"東京の中の交通、民間事業者の営業といえども、公共的な要素が非常に高いものだと考えています。そういう中で、まちはもう既にでき上がっている。その中にバスを通すわけで、なかなかほかの部門での採算の確保というのが都心の中では非常に難しい部分もあるのかなと考えています。","voiceIndex":159,"id":"exchange-059"},{"speaker":"南委員","kind":"質問・要望","question":"コミュニティーバスについて関連で質問したいと思います。とりわけ南大井地域については、京急バスしかありません。ここは鉄道事業者ですから、どうしても採算を考えると、それ以上の運行は考えてないと、こういうことになるわけで、区民の利便性をしっかり図るべきだと思うので、その点についてどういうふうに全域的に検討されているのかを伺いたいと思います。","respondent":"藤田都市計画課長","answer":"区内の交通について、区のほうとしても、不便を感じる方がいないように、さまざまな施策をもって展開していく。総合的にはそういうふうに考えているところです。","voiceIndex":162,"id":"exchange-060"},{"speaker":"南委員","kind":"質問・要望","question":"しかも、これから高齢化社会ですし、身体的な障害のある方々もやはりあるわけだし、そういう方々の利便性を考えたときに、福祉タクシーがあるからとおっしゃるけど、福祉タクシー、利用できるようにはなってないではないですか。したがって、きちんとした解決を本格的に考えていただきたいと考えていますけれども、その辺についていかがでしょうか。","respondent":"藤田都市計画課長","answer":"鉄道の関係ですけれども、京浜急行線、この間、１０月２１日から、少しダイヤ改正をする予定をしています。その中では、昼間の時間帯ですけれども、各駅停車の本数を逆に今増やすというふうにしております。","voiceIndex":164,"id":"exchange-061"},{"speaker":"南委員","kind":"質問・要望","question":"ぜひ検討していただきたいと思います。前向きにお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":166,"id":"exchange-062"},{"speaker":"石田（ち）委員","kind":"質問","question":"私は１６８ページの可動式ホーム柵整備助成と、あとちょっと前に戻って、１６３ページの視覚障害者用誘導タイルについて伺いたいと思います。今、ホームドアについては、先ほどもありましたけれども、大井町駅でも転落事故８件あるということでした。","respondent":"山崎マスタープラン担当課長","answer":"委員おっしゃられた３,０００人規模の駅ということは、駅に至るまでの視覚障害者がルートをたどるときに、ワンルートを確保しましょうということで、エレベーター整備などを対応してきたというようなことです。","voiceIndex":168,"id":"exchange-063"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"具体的な計画はまだこれからということなんでしょうか。なので、１０万人を超える、利用率を超える駅といったら、大崎、五反田、大井町、近隣では目黒、大森とありますけれども、で、この視覚障害者の方々から要望が多い旗の台駅ですね、心身障害者福祉会館があるということで、利用頻度が高いという、これは毎年要望が出されているんですけれども、旗の台駅での転落事故というのは起きているんでしょうか。","respondent":"山崎マスタープラン担当課長","answer":"先ほど１０万人、あるいは３,０００人、１万人以上ということですけれども、整理しますと、１０万人以上のところはホームドアの対応が方向性とすれば必要でしょうと。","voiceIndex":170,"id":"exchange-064"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"変な聞き方になってしまってすいません。旗の台駅についても、具体的な計画、どこの駅についても具体的な計画はないということでいいでしょうか。技術的なこと、あと、コストもありますがということでしたけれども、そういったことはもう乗り越えて命を守るということにもっと積極的に取り組んでいただきたいと思います。いかがでしょうか。","respondent":"山崎マスタープラン担当課長","answer":"こちらのほうも、東京都のほうと連携をしつつ、そうした整備がせめてできるところについては整備をして、そうした整備に基づいて今後の検討の糧にしようということで、パイロット事業に区とすればいち早く手を挙げたんです。","voiceIndex":172,"id":"exchange-065"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"はい、わかりました。でも、旗の台駅はやはり視覚障害者の方からの要望も本当に高い駅ですので、強力に進めていっていただきたいと思います。それで、あと、次、時間ないんですけれども、エスコートゾーンについてですけれども、平成２１年度の決算特別委員会でも、２カ所しか、ここの区役所の前の２カ所しかエスコートゾーンがないということだったんですけれども、そこから進展はあるでしょうか。","respondent":"山崎マスタープラン担当課長、谷口交通安全担当課長","answer":"大井町の駅から社会福祉協議会、それから区役所というところで、一番優先度の高いルートだというところで、その整備に向けて検討させていただいて、警視庁のほうでは設置をしますというところまで決まっています。今のエスコートゾーンの関係につきましては、私もこちら来ましてから、担当課のほうに赴きまして、設置に向けて鋭意努力しています。ご理解のほどよろしくお願いします。","voiceIndex":174,"id":"exchange-066"},{"speaker":"西本委員","kind":"質問","question":"１６２ページの地籍調査事業、同じページで、交通安全啓発費および駅周辺等放置自転車対策費、１６３ページの道路新設改良費、これ、補助２９号線、３１号線についてお聞きします。地籍調査、先ほどもほかの委員から、調査、非常に大切だということで質問がありました。これはどういうことが起きているのかということについてのご説明をお願いいたします。","respondent":"小林土木管理課長","answer":"したがいまして、品川区におきましては、平成２３年度につきましては、平成２４年度に向けた準備として、三角点および水準点の改正成果の公表を前提として、２級基準点の一部を１級基準点相当ということで改測するなど、１級基準点の１３点、２級基準点の４３点について改測。","voiceIndex":179,"id":"exchange-067"},{"speaker":"西本委員","kind":"質問","question":"東日本大震災の影響が出ているんだというご答弁でした。それの進め方、それからまた、こんなにずれているんだよという、また地籍調査を今調べ直しているよというような区民の皆様に対する広報といいますか、それに対してどのように考えておられるかをお聞きします。","respondent":"小林土木管理課長","answer":"蛇足ではありますが、今回の震災によりまして、そのうち約１.２％ほどの遅れを生じてありますので、現時点での計画では、平成３１年度、終了目標は、区面積に対して１０.６％の地籍街区調査を終了するということを目標に進めてまいりたいと考えております。","voiceIndex":181,"id":"exchange-068"},{"speaker":"西本委員","kind":"質問・要望","question":"交通安全啓発と、および自転車対策についてお聞きしますが、再三機会があると注意勧告という形でお願いしているんですけれども、子どもとの２人乗りですね。これは本当にやめてほしいです。これに対してやはり何かしらの、まあ、所管違うかもしれませんけれども、何か啓発をしていかないと大事故になってしまいますので、何とかしていただきたいと思いますので、その方法についてまず１つ、１点目。","respondent":"谷口交通安全担当課長、安藤文化スポーツ振興課長","answer":"今、母親に対する自転車教室等も実施しておりますので、その場で、要は幼児２人乗りの自転車の危険性、乗せるときだとか降ろすときの危険性について、区としましても啓発を行っていきたいと考えております。そんな中で、今回１０月１日から駐輪場を整理したというふうに伺っております。使用については、今回２時間まで使用するのは無料と。それ以外については一律お金をいただきますというような話を伺っております。","voiceIndex":183,"id":"exchange-069"},{"speaker":"西本委員","kind":"質問","question":"そうなると、駐輪場の例えば優先枠を、きゅりあんの使うところの優先枠をつくって、半券とか、そういう駐輪券を配布するとか、それからあと、きゅりあんの主催者側のほうとしても、結局無料というわけにはいかないかもしれませんけれども、有料でも、その半券を配布するとか、有料で配布するかという形で、何かしら対応していかないと、その施設に行こうと思っていろいろと。","respondent":"武内委員長、安藤文化スポーツ振興課長","answer":"すいません。自転車の全体的な考え方ならいいんですけれども、きゅりあんの自転車の駐輪場の考え方になるとちょっと款が違いますので、そこを踏まえて答弁いただければ。私のほうからは、今きゅりあんというお話を伺いました。きょうは、今ご意見いただきまして、これをきゅりあんをはじめ、関係団体の方にお伝えをしていきたいと考えています。","voiceIndex":186,"id":"exchange-070"},{"speaker":"西本委員","kind":"質問・要望","question":"申しわけありません。自転車を整備をするときには、その周り、どういう使い方をされている人たちがいるのかというところまで広い目線で見て整備をしていくべきだろうと主張させていただきたいところでした。私も、これ、３１号線ですけれども、歩いて見ました。１０年間でやろうとしている東京都の関係もありますけれども、どのようにやっていくのかということについてのお考えをお聞きします。","respondent":"藤田都市計画課長","answer":"１０年でできるか否かですけれども、なかなか厳しいというものの、東京都では生活再建のための支援策を新たに講じることで事業として進めたいと考えています。これらの事業について適切な時期に東京都と連携して地域の皆様方にお話をしていきたいと考えています。","voiceIndex":189,"id":"exchange-071"},{"speaker":"金野委員","kind":"質問・要望","question":"要は、駅前で大変に利便性が高くなりましたし、皆さん本当に駅前ですごく使いやすいというお声をいただいておりますし、また、線路沿い側は喫煙所等もありますけれども、歩道の幅も十分ではない現状でもある中ですが、やはり駐輪場の設置をされたということは定着をしてきて、また、歩行者からも一定のご理解をいただけているのかなというふうに見られますので、そうしたことも考えると。","respondent":"谷口交通安全担当課長","answer":"それで、線路沿いの駐輪場を残すかどうかということなんですけれども、今設置してある、今のところ１３０台、要は線路際のところですね、一応１３０台は残す予定でおります。それで、区民の方の利便性を図りながら放置自転車対策に努めてまいりたいと考えております。","voiceIndex":192,"id":"exchange-072"},{"speaker":"金野委員","kind":"質問","question":"ちょっと私の聞き方が一方だけになってしまったんですが、いわゆるショッピングモール、阪急側のほうの一時貸しのほうも継続を、いわゆるあそこ、移設したところ、全部継続をというところをお願いしたいなというところなんですけれども。その点ではどうお考えでしょうか。","respondent":"谷口交通安全担当課長","answer":"委員ご質問の阪急側、これにつきましては撤去予定です。新たに陸橋下、ここに多く、従前の台数以上に設置台数を考えているところでございまして、バイクにつきましても設置台数を今予定をしています。今、東京都とも調整をしておりまして、協議中です。","voiceIndex":194,"id":"exchange-073"},{"speaker":"金野委員","kind":"質問・要望","question":"次にまいります。それから、ナビマークですけれども、自転車利用の方や歩行者にはどうもご理解というか、あまりわかってもらえてないような感が見受けられます。平気でその中を逆走してくる人とか、あるいはそこを歩いてしまっている人とかあるんですけれども、もう少し周知をするような方向性で何か工夫をされたほうがいいのではと思うのですが、いかがでしょうか。","respondent":"谷口交通安全担当課長","answer":"これも引き続き警視庁のほうに確認しましたら、また路線を検討しながら進めていくということでお話を聞いております。区としましても、都市計画の中で実施できれば、道路課と絡みますけれども、検討していきたいと考えているところです。周知の方法です。","voiceIndex":196,"id":"exchange-074"},{"speaker":"金野委員","kind":"質問・要望","question":"かなりついているということで今ありましたが、これからも必要な箇所につけていただきたいと思いますし、また、周知の方法については、色を変えるというような立会道路のような形で、カラー舗装というのもできるのかなというところではどうなのかというのはお聞きしたいと思います。それをあとご答弁いただいて、次の質問にまいります。この模様を簡単にお知らせいただきたいと思います。","respondent":"稲田道路課長、大串住宅担当課長","answer":"ただ、ほかの路線につきましては、まだその辺の検証、始まったばかりですので、その辺のところはまだ検討しておりません。私のほうからは品川区マンション管理組合防災対策等検討交流会についてお答えをしたいと思います。こちらにつきましては、今委員おっしゃっていただいたように、９月２７日に第１回の交流会を実施したところです。","voiceIndex":198,"id":"exchange-075"},{"speaker":"金野委員","kind":"質問・要望","question":"さきのこの間の一般質問でも私はこのマンションの管理組合というか、この防災対策向上のための誘導策ということでお話をさせていただきましたが、これはいわゆるご答弁では個人の財産にはということでご答弁をいただいて、それは一定の理解をしているところですけれども、いわゆるなぜこういうことを考えたかというと、目的の１つとしては、特に海側のその防災対策。","respondent":"大串住宅担当課長","answer":"そういったマンションの皆様へのご協力、こういったことも次回以降また交流会を開催していきますので、そういったところもテーマにしながら、この交流会、続けていきたいと考えています。","voiceIndex":201,"id":"exchange-076"},{"speaker":"山内委員","kind":"確認","question":"先ほど課題の中で乗り入れ車両のことをお話をされていましたけれども、基本ＪＲを考えますと、乗り入れ車両というのはあまり考えられないのかなという思いがするんですけれども、そうやって考えると、品川区にもＪＲ東日本の駅が、山手線とそれから京浜東北線ありますけれども、今後どういう経緯でこのホームドアというものが設置をされていくのか、そのあたりをもう１回伺います。","respondent":"山崎マスタープラン担当課長","answer":"ＪＲ目黒駅ですが、平成２２年に供用開始となったものです。それで、ＪＲ東日本に対しましての補助の関係ですが、補助はいたしておりません。","voiceIndex":204,"id":"exchange-077"},{"speaker":"山内委員","kind":"確認","question":"すいません。それは確認です。それから、五反田駅が平成２７年。これはどういうことか。さっき木村委員のほうから、道路のことに関して、道路パトロールをやっているということを伺ったんですけれども、そういったパトロールをする人が、「昔、ここあったけど、こうではなかったんではないの」とかって、そういった声とか上がってこないのかなと思うんですけど、そのあたり、ちょっと伺いたいと思います。","respondent":"小林土木管理課長","answer":"今後十二分の企業者の監督、竣工の検査等のときには、その辺のスケジュール、きちっと地域にご報告しながら円滑に進めていけるよう、企業の監督等の強化も含めて十分対応してまいりたいと思います。","voiceIndex":208,"id":"exchange-078"},{"speaker":"山内委員","kind":"質問","question":"そうですね。地域の人にしっかりと説明をしていただかないと。最後、１６６ページのマンホールの浮上抑制対策に関してなんですけれども、これ、区道に関するマンホールの対策だと思うんですけれども、今、マンホール、どれぐらいあるんですか。それから、その対策というのはどういう対策。やはり先ほども課長の答弁の中で、埋設物、東京ガスといった話が出ました。","respondent":"武藤河川下水道課長","answer":"マンホールの浮上、飛散によるそういった危険な事故防止につきまして、例えば下水道局におきましては、ふたが飛ばないような構造にするなど、さまざまな取り組みをしながら対策を進めていると聞いております。","voiceIndex":210,"id":"exchange-079"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと、３つ目が、木密不燃化１０年プロジェクトの実施方針の中で、平成２５年度以降も順次特定整備路線を指定していくと書かれていますけれども、区として新たに指定を求めていくということが今後あるのか、中延駅前の補助３０号線についてはどう考えているのか、お聞かせいただきたいと思います。","respondent":"藤田都市計画課長、品川防災整備担当課長","answer":"平成２５年度以降の路線の関係ですが、ちょっと委員がお話しになっている記述があまりよく理解できないんですが、３０号線については、まず区が行う路線としてなっていると思いますので。その中を中心としまして、補助２９号線を絡めてどこにするかを現在検討中です。","voiceIndex":213,"id":"exchange-080"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと、あとは、放射２号線と補助２９号線が今回指定されて、さらに品川区としても３１号線、２０５号線、補助２７号線を一緒に進めていくという方向ですけれども、この５路線でそれぞれ町会が何町会、幾つあるのかということと、そのうち道路によって分断される町会の数が幾つあるのかについて数を教えていただきたいと思います。","respondent":"品川防災整備担当課長、藤田都市計画課長、冨久増用地担当課長","answer":"可能性ですが、先ほどと同じ答弁にはなりますが、この地域の危険度、それから不燃領域率等、その辺の指標を踏まえて今後検討していきたいと考えております。２０５号線については４町会ありますが、ちょうどそれぞれ境に当たってありますので、これについては４町会ともそういう影響はないと考えています。道路事業に伴う補償の関係ですが、基本的には公共事業に伴う損失補償基準、これに基づきまして適切に補償がされていくと考えております。","voiceIndex":216,"id":"exchange-081"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"町会が補助２９号線で１２町会、放射２号線で５町会、合わせて２１町会ですか、これの２１町会もの町会が、私はこの２０メートル、２５メートルの道路で分断されていくということは、本当に地域のまちということに対しても大きな影響を与えることになると思うんですね。そして、この道路上にある建物は立ち退きをせざるを得ない。","respondent":"藤田都市計画課長、冨久増用地担当課長","answer":"こういう中に、区としてもさまざまな分野で力が出せることについては、出しながら、そのきずなの深さを持ち続けてもらうということにつなげていきたいと考えています。公共事業に伴う補償につきましては、原則は金銭補償です。したがいまして、損失をする対価に対しての補償ということになりますので、そういった観点での補償を行っていくということになります。","voiceIndex":220,"id":"exchange-082"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今でも２国ができたことによって、２国のこの広い道路と向こう側とこっち側というのの町会の活動のやり方というのは本当に大変だということも日々お伺いをしていますけれども、そういう町会を改めてこの道路をつくることで２１町会もさらに生み出していくという、こういうことに対しては本当にきちんと考えていかなくてはいけない問題なのではないかなと思っています。道路だけでは延焼遮断帯にはならないと。","respondent":"藤田都市計画課長","answer":"これにつきましては、今年度補正予算の中でもご提案申し上げたとおり、用途地域の見直し、あるいは容積率の検討、そういうことも必要でしょうし、それらによらない。","voiceIndex":223,"id":"exchange-083"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"まちづくりというのはやはりそこに住んでいる人を主役にして進めていくということが必要だと思うんですが、事業決定をする前に住民の意見と要望を聞きながら双方向で進めるというやり方でしていただきたいと思うんですが、いかがでしょうか。","respondent":"藤田都市計画課長","answer":"東京都のほうと連携を図りながら、まずは東京都のほうでどういう範囲に説明をするか考えていただいて、それにあわせて区も協力をしていくということになろうかなと思ってあります。","voiceIndex":225,"id":"exchange-084"},{"speaker":"浅野委員","kind":"質問","question":"１６５ページの私道整備事業、１７１ページの住宅・建築物耐震化支援事業についてお伺いします。それともう１点ですけれども、今回かなりほかの費用の流用とか、そういう形で対応されておるかと思うんですけれども、こちらのほうで補正予算組まなかったと思うんですが、あえて補正予算を組む、組まないというのはどのような判断なのかということを１点お伺いしたいと思います。","respondent":"中村建築課長","answer":"来年度につきましてもまた同じような考え方で、まずは当初の予定どおり、当初予算の中で執行して、さらに申請件数がどのぐらい出てくるかというのはまた不明確なところですので。","voiceIndex":228,"id":"exchange-085"},{"speaker":"浅野委員","kind":"質問・要望","question":"また時期が変わって、今後どのような支援策になるかということは、まだご公表いただいてないようですけれども、ぜひとも、後から来ると条件が悪くなるということがないようにうまく対処をしていただければと思いますので、この点は要望にしておきます。もう一つ聞きますけれども、空き地のままにされたというのは、実際発生をしたのかどうか、この件についてもお伺いします。","respondent":"品川防災整備担当課長","answer":"耐震制度の除却補助の件ですが、まず平成２３年度の７月より除却制度を始めました。この時点で助成率を２分の１、上限額を１５０万円までということで制度を始めたんですが、残念ながら、平成２３年度は実績ゼロ件に終わりました。","voiceIndex":232,"id":"exchange-086"},{"speaker":"浅野委員","kind":"質問","question":"これは私からの進言ということで検討していただければと思います。ちょっと話は変わりますけれども、今回この建物の除却についての項目が決算書のほうには載っていなかったということなんですけれども、実際ゼロということだったので、載せてないとは聞いておりますが、この載せてないようなこのような主要施策ですか、ほかに何件ぐらいあったのかということについてお伺いします。","respondent":"本城企画財政課長","answer":"実績の調書のほうですが、基本的にこちらのほうは、実績があったもののみ、その概略を書くという位置づけでしていますので、そちらについては記載がないんですが、大体何件ぐらい発生したかですと、大づかみでいうと、大体大きい事業で見ると１０件程度だと考えています。","voiceIndex":234,"id":"exchange-087"},{"speaker":"浅野委員","kind":"質問・要望","question":"いろいろな今回の除却の件についても、さまざまな理由があって延びたということでありますので、これはぜひとも今後とも入れていっていただくようなことで考えていただきたいと思いますけれども、ご見解をお願いします。","respondent":"本城企画財政課長","answer":"今ご指摘いただきましたとおり、予算書と対応する形で、全体として決算の中でよく理解がきちんとできるように、どういう形が可能であるか、ちょっとこちらのほうで工夫していきたいと考えております。","voiceIndex":236,"id":"exchange-088"},{"speaker":"石田（秀）委員","kind":"質問","question":"１６３ページ、先ほど来出ている都市計画道路、行きます。２９号線と放射２号線、特定整備路線だという話です。そもそも論を伺いたいんですが、先ほど来さまざまなお話が出ていますが、なぜこの路線を整備するのかということです。そういう視点に立って、この路線をどういう意味で、私は命を守るためにこの路線を指定してきて、２０２０年までにしっかり整備していこうという気持ちがあるんだと思うんですね。","respondent":"藤田都市計画課長","answer":"その中のプランの１つに木密地域を燃えないまちにしていこうということで、事業として取り上げられているものです。現在東京の木密地域、整備地域として約７,０００ヘクタールありますけれども、これを１０年間に重点的に、集中的に取り組みを実施し、燃え広がらないまちにする。","voiceIndex":239,"id":"exchange-089"},{"speaker":"石田（秀）委員","kind":"確認","question":"だから、これはもし何かお考えがあれば、もう１回お聞きをします。ここら辺もまだ決まってないとよく言うんだけど、ここは一番ポイントがあって、そういう部分である程度生活再建まで見てくれるよということがないと、これは本当に意見が分かれてしまって、大変なことになるような気がするんだけど、ここは必ず見るって、よく何か答弁のとき、必ずあるけど、ここのところを確認したいのが１点。","respondent":"藤田都市計画課長","answer":"既存不適格になってしまうような建物、これは私どものほうも東京都のほうになるべく早くこの支援策をはっきりさせて、それについて住民の皆様方に周知を図っていく、それがまず必要であると言ってありますけれども、早めたとしても、あるいは周知期間をとったとしても。","voiceIndex":241,"id":"exchange-090"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"先に我々に情報を流せということは言いませんが、やはり区民に、まちに知れるときには、同時で結構ですので、議会にも情報は流してほしいなというのがありまして、よく先に地域が知っていて、「こういうこと知っているか」なんて言われると、我々知らないというとき、よく聞くと、これは東京都が流しましたとか、そういうことだけはないようにしていただきたいんだけど。","respondent":"藤田都市計画課長","answer":"今支援策等についても、具体的な検討が東京都の中で行われているとは思うのですが、私たちのほうに少しでも情報をということで今お願いをしていますが、なかなか情報が出てこないという段階です。","voiceIndex":243,"id":"exchange-091"},{"speaker":"石田（秀）委員","kind":"意見","question":"本当にぜひとっていただいたとき、同日かもしれないですが、ぜひ議会は、議長もいらっしゃるし、我々がまちから、皆さんから、「おい、こんな説明があってどうなっているんだ」と言われることだけはないようにぜひお願いだけして終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":245,"id":"exchange-092"},{"speaker":"井上委員","kind":"質問・要望","question":"私は１６２ページの交通安全啓発費、駅周辺等放置自転車対策費、１６３ページの道路安全施設費、１６７ページの景観審議会および景観アドバイザー委託についてお伺いをいたします。視覚障害者用誘導タイル敷設についてですけれども、障害者団体によれば、８年来要望している大井町駅から社会福祉協議会までの歩道に動きがあるように聞き及んでおりますけれども、現在の状況をお知らせください。","respondent":"山崎マスタープラン担当課長","answer":"大井町駅から福祉拠点としての社会福祉協議会、それから、区役所も含めまして、この動線については最優先で整備をしていくんだということで、警察あるいは東京都のほうと協議も済んでおります。施工時期は未定ですけれども、整備をするということは決定をしている段階です。","voiceIndex":248,"id":"exchange-093"},{"speaker":"井上委員","kind":"質問","question":"それが事実なのかどうかということをお伺いをしたいと思います。もしそうであるならば、私たちは両方のところを歩くことができますけれども、障害者の方たちだけに、鉄道側というか、東急線のほうに渡って歩いてくださいねというのは、明らかに障害者基本法の差別禁止に当たると私は考えますけれども、どういうふうな事実関係があって、区はどう認識していらっしゃるのか、教えてください。","respondent":"山崎マスタープラン担当課長","answer":"こちらのほうは、視覚障害者の方がある拠点に誘導する際のガイドラインというものです。基本的な考え方につきましては、連続的な設置を行う箇所については、原則１経路とすることがガイドライン上望ましいとされているということになってあります。","voiceIndex":250,"id":"exchange-094"},{"speaker":"井上委員","kind":"質問・要望","question":"私たちは晴眼者として目が見える人たちはどちらでもいいけれども、目の見えない人たちはこちらだけを歩いてくださいねというのは、やはり社会的障壁をみずから私たちがつくっているということだと思いますので、ここは東京都が一方に点字ブロックがあるからそちらにしてほしいと言われたとしても、ぜひ品川区としては、人権尊重都市品川宣言をしている品川区ですから。","respondent":"山崎マスタープラン担当課長","answer":"基本的には視覚障害者等の意見を踏まえた上で、そうした原則を踏まえつつ、よりよい誘導ができるような形で対応できるのがベストだということで考えておりますので、今後も、東京都あるいは交通管理者等々と連携をしながら。","voiceIndex":252,"id":"exchange-095"},{"speaker":"井上委員","kind":"提案","question":"ぜひ力強く主張していただきたいと思います。なぜそういったことを採用しなかったのか、今これからどんなふうにそのことを考えていらっしゃるのか、見解を伺います。","respondent":"山崎マスタープラン担当課長","answer":"趣旨としましては、そういった趣旨は十分受けとめまして、ただいままちづくりマスタープランのほうでもそうしたやさしいまちづくりの推進という分野で、まず大きくまちづくりマスタープランで規定をして、それから。","voiceIndex":254,"id":"exchange-096"},{"speaker":"井上委員","kind":"質問","question":"次は放置自転車対策なんですけれども、この中に道路環境美化作業委託というのが予算書にはありませんけれども、これが決算書に載っております。これはどういった経過と事業内容なのか、委託先がどこなのか、伺います。この中で品川区は今後とも計画の検討を考えていないと多分答えられたと思いますが、２３区中何区が今後考えていないと回答したのか、そして、品川区がこう答えた理由を教えてください。","respondent":"谷口交通安全担当課長","answer":"道路環境美化作業委託ということで、補助事業として実施をしたところです。","voiceIndex":256,"id":"exchange-097"},{"speaker":"井上委員","kind":"質問","question":"その失業対策ということなんですけれども、成果、どのぐらいの人がここにかかわって、失業、雇用対策になったのかということはおわかりでしょうか。","respondent":"谷口交通安全担当課長","answer":"ちょっと私の記憶しているところでは、２３人の方が従事されておるです。","voiceIndex":260,"id":"exchange-098"},{"speaker":"井上委員","kind":"提案","question":"それで、ネットワークのほうは計画を考えていないということなんですけれども、道路が狭かったりとか、いろいろあるかもしれないけれども、品川区は自転車専用レーンなどもつくっていこうというふうに考えていただいているかと思うんですが、まずできることで、マナーやルールの徹底というのが必要で、そういったことで人を自転車から守り。","respondent":"谷口交通安全担当課長","answer":"私はそこで当然ながら注意をしたりとかしますけれども、これは繰り返しの安全教育、警察署で実施しておりますけれども、これは繰り返し繰り返ししかありません。で、皆さん自身に意識づけを図っていく。これしかないと考えています。","voiceIndex":262,"id":"exchange-099"},{"speaker":"高橋委員","kind":"質問","question":"成果報告書１６７ページ、まちづくりマスタープラン策定費についてお尋ねいたします。今後の、ちょっと大きな話になってしまいますけれども、まちづくりの方向性についてお伺いしたいと思います。約数十ページというボリュームのあるものになっていますが、全体の構成は、まず市街地の歴史が、変遷ですか、ありまして、課題と目標、分野別、そして地区別の方針となっています。これについてお尋ねいたします。","respondent":"山崎マスタープラン担当課長","answer":"駅前の開発など、地域のまちづくり気運が高まっている武蔵小山駅周辺につきましては、現行計画における地域に密着した生活拠点を地区活性化拠点と改め、特徴ある商業集積を踏まえつつ、より広域の区西部の中心核といたしまして、新たな都市機能の集積など。","voiceIndex":265,"id":"exchange-100"},{"speaker":"高橋委員","kind":"質問","question":"今、品川・天王洲と武蔵小山のことをお伺いしたんですが、今後の重要な位置づけという形で見直しがあったと思われます。その際には、当然地域の方々との調整、協議、または関係機関との調整があると思うんですが、現在お答えできる範囲で結構ですので、お伺いしたいと思います。","respondent":"溝口都市開発課長","answer":"それを受ける形で品川区のほうでもまちづくりビジョンの策定を今現在進めているところです。続きまして、武蔵小山駅周辺につきましては、現在駅に沿った形で３つの地区で再開発の準備組合等が起こっておりまして、まちづくりを含めた検討が地元の中で進められているところです。","voiceIndex":267,"id":"exchange-101"},{"speaker":"高橋委員","kind":"質問","question":"さまざまな機関と協議をされているというお話を伺いました。区のほうが主導権をとりながら、そして地域の方々のご意見を伺いながらまちづくりをしていくのは大変重要なことだと思います。その点、どういった理由で変わって、そして戸越公園の今後でいいんでしょうか、その点についてお伺いします。","respondent":"山崎マスタープラン担当課長","answer":"戸越駅周辺につきましては、木密不燃化１０年プロジェクトで東京都のほうが整備を予定をしている２９号線に接すると。この道路整備に合わせて沿道のまちづくりをしていく観点で、地域生活の拠点という形で新たに拠点に位置づけたと、こういう経過です。","voiceIndex":269,"id":"exchange-102"},{"speaker":"高橋委員","kind":"質問・要望","question":"今２９号線のお話が出たんですが、他の委員からさまざまな質疑があったので、２９号線関係で都市計画道路についてお伺いいたします。こうした都市計画道路の変遷、長い間にさまざまな変遷があったと思うんですが、そのことを簡単にお知らせいただき、それと関連して、先ほどから整備していく都市計画道路、そちらと関係して、その位置づけについて改めてもう一度ご説明いただきたいと思います。","respondent":"山崎マスタープラン担当課長","answer":"ただ、実際の計画実施となりますと、戦後の社会経済状況といった側面、それから、少し後になりますけれども、高速道路計画などができまして、さまざまな要因によりその整備があまり進捗しなかったと。","voiceIndex":271,"id":"exchange-103"},{"speaker":"高橋委員","kind":"質問・要望","question":"これまで以上に浸水対策に取り組んでいっていただきたいと思うんですが、今後この分野に関する方向性、具体的な取り組みについてお伺いします。","respondent":"武藤河川下水道課長","answer":"さらに言いますと、合流式下水道という方式で、下水道管が整備されている特性上、どうしても大雨の際に一部汚水が河川に流れ出るといった多くの課題を抱えていることから、東京都のほうで、今雨が川に流れているのを全部地下に大部分を流し、その放流先も。","voiceIndex":273,"id":"exchange-104"},{"speaker":"高橋委員","kind":"質問・要望","question":"ちょっと時間があれなので、津波対策のことをちょっとお尋ねできないんですが、都との連携で進めていっていただきたいと思います。最後になりますが、住宅分野に関することをちょっとお尋ねいたします。今後の区のマスタープランの住宅政策の方向性、またその中心になるところについてお伺いしたいと思います。","respondent":"山崎マスタープラン担当課長","answer":"今後こうした住宅につきましては、安全で快適かつ良質な住宅ストックとして区民の皆様に長く提供していくため、長寿命化の観点から、予防等の修繕を計画的に実施していくなどとともに、民間分譲マンションの適正な管理等々を組み合わせて、施策を構築してまいりたいと。","voiceIndex":275,"id":"exchange-105"},{"speaker":"高橋委員","kind":"意見","question":"マスタープランについてはまだいろいろお尋ねしたいところあるんですが、ちょっと時間の関係でこれまでということで、これは最上位の計画でありますので、国、東京都の連携、そして、区民のために、区民の方々のために将来像の実現に向けてぜひ邁進していただくことをお願いして終了いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":277,"id":"exchange-106"},{"speaker":"山元委員","kind":"質問・要望","question":"私からは河川費の中の１６７ページ、勝島の海桟橋設置・運営委託についてお伺いしたいと思います。実際もうスタートしておりますけれども、今回この決算、６５０万円ちょっとですかね、この内訳というんでしょうか、どのようになっているのか、ちょっと教えていただきたいと思います。","respondent":"武藤河川下水道課長","answer":"勝島の海にかかわるご質問です。決算の内訳ですが、勝島の海を区民の水辺として親しんでもらうために、まずボートの整備、ボートの接岸できる桟橋の整備としまして約３７８万円の設置工事を実施しております。","voiceIndex":279,"id":"exchange-107"},{"speaker":"山元委員","kind":"質問・要望","question":"ボート、また桟橋で三百七十うん万とおっしゃっていましたが、実際もう１年過ぎました。これは、料金ですね、乗るのにどのぐらいの料金かかって、そして何分ぐらい乗れるのかなというのを教えていただきたいのと同時に、これは買い上げたというか、レンタルとかではなく買い上げたのでしょうか。","respondent":"武藤河川下水道課長","answer":"昨年度、平成２３年度は７月から１０月にかけての土日に運営させていただきました。利用料金ですけれども、船、１艇当たり３０分で、一般は２００円、しながわ水族館を利用した方につきましては半額の１００円という形で利用していただいております。","voiceIndex":281,"id":"exchange-108"},{"speaker":"山元委員","kind":"質問","question":"ところが、事務事業評価を見ますと、Ｃの見直しということで、その事業の目的を再検証し、利用可能な期限とか、また利用料金の設定と、そしてまた運営方針の抜本的な見直しを検討するということでありますけれども、この辺、数的に、まあ、寒い時期は無理かなと思いますけれども、なかなかの人数ではないかなと思いますが、Ｃの見直しに至った経緯といいますか。","respondent":"多並公園課長","answer":"総合的な観点から、今後、今までの利用実態も含めながら、料金の体系だとか、また、実施期間をどのような形にするかというのを今後さまざまな観点から検討していく、そのようなことです。","voiceIndex":283,"id":"exchange-109"},{"speaker":"山元委員","kind":"質問・要望","question":"都立高専の先生と八潮学園の先生方を中心に毎年手づくりのボート２艘つくっているということで、実は１０月６日、つい最近でありますけれども、勝島運河において、シャチ号とユーエス号の進水式が行われました。これは本当に子どもたちがつくって、本当に初めて乗って楽しそうにしておりましたけれども、この進水式、この勝島の海で進水式を行うというのはどうなんでしょうか。いかがなものでしょうか。","respondent":"武藤河川下水道課長","answer":"今委員、お話のありました区民の団体活動につきましては、水辺を利用するという件につきましては好ましいものと考えておりますけれども、そのご提案があった際に、その内容を判断させていただきながら、今後検討していきたいと考えています。","voiceIndex":285,"id":"exchange-110"},{"speaker":"山元委員","kind":"質問・要望","question":"１７２ページの住宅費の中の住情報ネットワーク整備事業について、八潮地区の住み替え支援業務についてお伺いをしたいと思います。１年がたちましたけれども、実際今までの相談件数、また成立したのは何件ぐらいなのか、またその中に情報発信としてどのような周知をしながら、そしてセミナーが行われたと聞いておりますけれども、どのようなセミナーが行われたのか、その辺も教えていただきたいと思います。","respondent":"大串住宅担当課長","answer":"それとセミナーです。セミナーといたしましては、全部で４回開催をいたしました。６月、１２月、１月、３月と。それぞれ参加者の数が、回によっては異なりますが、大体一番少ないときで１３人、多いときですと４３名の方がご参加いただいているといったところです。","voiceIndex":287,"id":"exchange-111"},{"speaker":"山元委員","kind":"質問・要望","question":"ただ、利便性というか、移動の利便性に対してはちょっと不満があるということでありますけれども、そのようなことを踏まえて、今後どのように住み替え、八潮地区の住み替え支援事業に対してどのような取り組みをしていきたいのか、その辺のお話を聞かせていただきたいと思います。","respondent":"大串住宅担当課長","answer":"今後のこの事業の方向性です。大井林町高齢者住宅への転居といったところで昨年はやりましたけれども、今後は八潮の活性化といったところでこの事業を進めていきたいと考えておるところです。","voiceIndex":289,"id":"exchange-112"},{"speaker":"須藤委員","kind":"質問","question":"最初に１６５ページの下水道管改修事業に関連して、１６６ページにマンホール浮上抑制対策事業というのがありまして、先ほど山内委員がお聞きしましたら、マンホールが液状化で持ち上がらないようにするんだという話をされたと思うんですが、マンホールのふたを飛ばないようにするというのが東京都の施策で行われてきているので、私はこれを見て、山内委員と一緒に。","respondent":"武藤河川下水道課長","answer":"委員ご質問のこの下水道管改修事業のマンホール浮上抑制対策事業、この事業につきましては、昨年度東日本大震災のときに千葉県の浦安市でも被害が出て、報道等でかなり皆さんごらんになったかもしれませんけれども、地震の際の液状化現象によって、マンホールそのものが。","voiceIndex":292,"id":"exchange-113"},{"speaker":"須藤委員","kind":"質問・要望","question":"これはそれでわかりました。ただ、ふただけ強固にしていって、そこが飛ばないようになって、まちの浸水は防げるけど、その水自体が今度各自のところへ入ってきてしまうんだろうという懸念が出てくるので、東京都の施策とそのことを上手に整合性、区の下水道管の整備と整合性を持たせながらやっていただきたいと思うので、これは要望しておきます。","respondent":"稲田道路課長","answer":"この間の台風におきましても待機をしていただきました。ただ、今ここで何回出動しているのかというのが出ないんですけれども、台風が主ですね。台風の状況に応じて待機していただいて、出動もするです。","voiceIndex":294,"id":"exchange-114"},{"speaker":"須藤委員","kind":"質問","question":"公園管理のところで、大規模公園の委託をしてもらっているので、朝ほどいろいろ言っていた、クレームも来たり、放置自転車もみんなそこが、五百何台撤去したり何かしているよというようなお話をいただいたんだけれども、そういった委託をしていることと、それから、１６９ページに公園施設の長寿命化対策というのがあって、そのあたりと連携は、公園の長寿命化をするために委託をしている会社というか。","respondent":"多並公園課長","answer":"民間の公園の委託についてと、あと長寿命化の関係です。民間の委託につきましては、１０年ほど前ですね、官から民へということで、民間委託ということで、今、直営から民間にということで現在行っているところです。","voiceIndex":296,"id":"exchange-115"},{"speaker":"須藤委員","kind":"質問・要望","question":"その委託している先もそれなりによく見てくれていると思うので、そうしたら、設計というか、長寿命化するときも、その辺の声をしっかり聞きながら対応していただきたいと思います。最後に１６８ページのしながわ水族館あり方検討業務支援委託というので、これもまた委託になっているんだけれども、このあたりは何を委託して、どういうことがわかってきたのかなと、教えてください。","respondent":"多並公園課長","answer":"水族館のあり方の検討の支援委託の件です。昨年度委託の中であり方検討ということで、主なもので言えば、日本動物園水族館協会の副会長であったり、大学教授などの学識経験者をメンバーとした外部懇談会というのを３回ほど実施いたしました。","voiceIndex":298,"id":"exchange-116"},{"speaker":"飯沼委員","kind":"質問","question":"もう１点なんですが、区はこの間、２００７年実施アンケートや２０１１年町会、商店街で寄せられた意見を参考に策定し、地域の賛同をいただいているものと受けとめている、こう答弁をされていますが、ビジョン、誘導指針ができてからですけれども、意見を伺った対象者は誰なのか、地権者とその他の方を分けて、どのくらいの方に何回ぐらいご意見を聞いたか、具体的に教えてください。よろしくお願いします。","respondent":"溝口都市開発課長","answer":"私のほうからは武蔵小山周辺地区の街並み誘導指針、またビジョンについての説明会の開催について等、３点についてお答えします。","voiceIndex":303,"id":"exchange-117"},{"speaker":"飯沼委員","kind":"提案","question":"なぜ説明をしないか、理由をご説明をいただきたいと思います。８月２４日、２５日、１棟ではなく、どうやら駅前に４棟もできるということがわかってきたんですが、まちの将来像が地域住民に知られない、そういった間に変わってしまう。今回の無謀な提案は撤回すべきと思います。今後の総事業費と税金投入どのくらいか教えてください。そして、区はまたどのような指導を行ってきたのか教えてください。","respondent":"溝口都市開発課長","answer":"そういった意味で、今回８月になりますが、計画がある程度まとまった段階でしっかりと近隣の方を対象に説明会等開き、手続等を進めております。","voiceIndex":305,"id":"exchange-118"},{"speaker":"飯沼委員","kind":"質問・要望","question":"説明、地域の住民の方、求めています。逃げないでぜひ。方針です。きちんと区が説明すべきであると思いますので、これは強く求めておきたいと思います。そして、区は風害をこの間認めていませんけれども、区内あちこちで起こっている風害調査をぜひ行っていただき、事業者の評価をうのみにするのではなくて、実態をしっかりとつかんで、風害を認知をし、対策を立てるべきと思いますが、いかがでしょうか。","respondent":"溝口都市開発課長","answer":"風害についてのお問い合わせです。風害につきましては、これまでにつきましても、風洞実験などを行いまして、適正に評価をしていく。","voiceIndex":307,"id":"exchange-119"},{"speaker":"飯沼委員","kind":"質問・要望","question":"風害の影響なんですけれども、実態調査をしないで風害がないといったとらえ方はやめていただきたいと思います。風洞実験をきちんとしているんですかね。ぜひそれをわかっていただきたい。調査をしていただきたいと思います。武蔵小山に４棟が予定をされると、コンクリートの壁ができてしまうんですね、１４０メートル級の。これは区の役割と考えますが、いかがでしょうか。","respondent":"溝口都市開発課長","answer":"これまでの開発と同様に、周辺のまちへの環境についても十分に品川区としては指導していきたいと考えております。","voiceIndex":309,"id":"exchange-120"},{"speaker":"石田（慎）委員","kind":"質問","question":"よろしくお願いします。私のほうからは１６７ページ、１６９ページのまちづくり全体について、１６６ページ、１６７ページの水辺について、それとちょっとページ数があれなんですが、中央環状品川線についてお聞きをしたいと思います。時間があれば、橋梁費と台風対策についてもお伺いをしたいと思います。","respondent":"山崎マスタープラン担当課長","answer":"そうしたまちづくりの各分野にかかるそれぞれの事業については、事業を進める際に、これはやはり事業の進め方というのは、区のみでまちづくりを進めるということではなく、やはり地元の皆様、それから、事業者の方、こうしたところと連携、調整を図りながら。","voiceIndex":313,"id":"exchange-121"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"例えば１６９ページ、五反田駅周辺地区コーディネート業務委託、これ、業務を委託しているわけですよね。それと、水辺についてですが、現在ある品川区内の桟橋の利活用について、区のお考えをお聞かせをいただきたいのと、また、今後災害時の避難等の整備や観光振興に資するための桟橋の整備について、区のお考えをお知らせください。","respondent":"溝口都市開発課長、武藤河川下水道課長","answer":"そのゾーンを具体的にどのような形でまちづくりを進めるかといった方針を定めまして、今現在コーディネートといたしましては、そのにぎわいゾーンの整備のまちづくりビジョンの実現に向けて、例えば桜の植樹をどうするのか、また。そうした中で、区としましても、できる限りそういった水辺の接点である桟橋の整備を進めるべく、現在天王洲運河にそうした活用ができる桟橋の設置について今年度整備を進めているところです。","voiceIndex":315,"id":"exchange-122"},{"speaker":"石田（慎）委員","kind":"意見","question":"コーディネートの部分なんですが、いまいち区のかかわり方が、どのように、調整役という認識でよろしいのか、そこだけお答えください。水辺についてですが、護岸沿いの遊歩道の不連続性の解消が必要だと思いますが、その点は、区の考えをお答えください。そして、目黒川について、区の今後の考え、水質改善と活用、五反田ふれあい水辺広場もありますが、その点、今後の区の方針をお知らせをください。","respondent":"溝口都市開発課長、武藤河川下水道課長","answer":"コーディネート業務に対して、区の役割ですが、あくまでも地元との調整役、また、区としても五反田周辺のにぎわいゾーンについては活性化を図っていきたい、まちづくりを進めていきたいという思いがありますので。河川に入った水質をきれいにするという面につきましては、平成２３年度までいろいろ進めておりました目黒川の水質改善の検討としまして、さまざまな高濃度酸素溶解水の対策だとか、海水導水だとか、さまざまな検討して。","voiceIndex":318,"id":"exchange-123"},{"speaker":"石田（慎）委員","kind":"確認","question":"健康促進の面も一部あるのかなと思いますので、そういった点も含めてぜひご検討をよろしくお願いいたします。次に、中央環状品川線についてお伺いをします。そこの委員会のメンバーに当該区として品川区も参加をしてほしいというような話があったと思うんですが、どのように区として今後、委員会が設置をされたときに、区として地元として取り組まれるのか、お考えがありましたら、お答えください。","respondent":"藤田都市計画課長","answer":"その検討委員の中には、品川区の職員として現都市環境事業部長のほうも入るような形で行われてございましたので、そういった意味で、景観のチェックをしっかりやってきたと考えてきてあります。","voiceIndex":321,"id":"exchange-124"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"そうした中で、五反田でもさまざまな要望や、特に脱硝装置については、以前ほかのところで事故もあったというのも非常に地元の方は気にしているところなので、そういった五反田の合同連絡会を含む地元の人たちの声をぜひ聞いていただいて、委員会がもし実際に設置をされたときには、地元代表としてぜひ声を上げていっていただければなと思います。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":323,"id":"exchange-125"},{"speaker":"須貝委員","kind":"質問","question":"私は１６７ページ、都市計画全般についてと、そして１７０ページの都市防災まちづくり全般について、絡めてお聞きしたいと思います。お聞きしたいのは、東日本大震災は、その被害の甚大さから関東大地震と比較されることが多いようで、先日テレビでも特集が組まれていました。関東大震災では、都市計画担当の役人の献身的な努力もあり、およそ３カ月で復興計画がまとめられたということです。","respondent":"藤田都市計画課長","answer":"品川区についても、今後いつ起こるかわからないというようなこともありますので、区としても復興のあり方については十分視野に入れていかなければいけないと考えています。","voiceIndex":325,"id":"exchange-126"},{"speaker":"須貝委員","kind":"質問","question":"今そういうふうに、まあ、関東大震災のときは国が約３カ月でそういうふうに素早く対応した。で、お金の出所がなかなか決まらない。予算が組めない。そして、今公表されているように、マグニチュード７.９クラスの首都直下型大地震が発生した場合、品川区は復旧復興に向けて、都市計画像をあらかじめここで決めているんでしょうか、用意しているんでしょうか、青写真を。それについてちょっと教えてください。","respondent":"山崎マスタープラン担当課長","answer":"今回マスタープランのほうでも、防災まちづくりの観点で、これからまちづくりを行っていくことは非常に今回のマスタープランでも目玉にしておりまして、そうしたあらかじめの復興計画についても、恐れ入ります、長くなって恐縮ですけれども、視点を入れさせていただいて。","voiceIndex":327,"id":"exchange-127"},{"speaker":"須貝委員","kind":"質問・要望","question":"仮設ならいい。出ていくしかないという状況になると思うんですが、この状況、都市計画法云々もあるんですが、これについて、区としてはやはり上からおりてくるそういう法律なり何なりがある以上、進めないというふうに考えているしかないんでしょうか。要は、復旧復興事業を進められないというふうに考えざるを得ないんですか。それとも、区が独自に進められる、そういうものがあるんでしょうかね、法律が。","respondent":"藤田都市計画課長","answer":"なかなか震災を想定しながら議論するというのは非常に難しいところがあります。どの程度の被害が起きて、その中でどんな対応ができるか。その辺については整理をしなければいけないのかなと考えています。","voiceIndex":329,"id":"exchange-128"},{"speaker":"須貝委員","kind":"質問","question":"減災ということを考えれば、私は都市計画の理論や制度というのはやはり用意しておくべきではないかと思うんですね。国任せ、都任せの対応、対策というのは、それは確かに法律の壁はあると思うんですが、私は品川区としてしっかりしたそういう指針なり、目標なり、計画というのを持つべきだと思うんですが、特段都市計画の理論や制度というのはまだ確立されてないと考えといてよろしいでしょうか。","respondent":"藤田都市計画課長","answer":"こういった動きの中も見ながら、やはり進めていかなければいけないのかなと思ってございまして、私ども区のほうとしても、都の動きを注視しながら、その中で復興についても、復興マニュアル等もありますので、その辺を活用しながら次のステップにつなげていきたいと考えています。","voiceIndex":331,"id":"exchange-129"},{"speaker":"須貝委員","kind":"質問・要望","question":"やはり区民からすれば、それは自助もわかります。共助もわかります。まして、本当に高齢者、それから、幼児もいるわけですから、そういういろんな方たちを考えれば、弱者に対しては、やはり皆さんにすがるという気持ちが、この品川区にすがるという気持ちが多いので、区長の双肩はね、肩にのしかかる重みは大きいと思いますが、どうぞ皆さんもよろしくお願いいたします。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":333,"id":"exchange-130"},{"speaker":"若林委員","kind":"質問・要望","question":"１６７ページの五反田ふれあい水辺広場クレーンの件と、同じページのまちづくりマスタープランの中の住宅の件についてお聞きします。なお、プレス発表等では、資料で天王洲桟橋のほうは、水門を入って、東品川海上公園のすぐ右手のほうに設置をするというふうに、写真、地図等が載っていますけれども、ここら辺についての確認をさせていただきたいと思います。","respondent":"武藤河川下水道課長","answer":"もう１点のご質問で、天王洲のほうに今年度設置する桟橋の件についてのご質問ですけれども、これは委員ご指摘のとおり、当初は天王洲運河の水門の内側、内陸のほうになります、そこの東品川海上公園のところに設置する予定で進めておりましたが。","voiceIndex":335,"id":"exchange-131"},{"speaker":"若林委員","kind":"提案","question":"いずれにしても、こういう桟橋、浮桟橋、タラップ等が、この目黒川、また天王洲にも新たに設置をされるということで、昨年の決算特別委員会でも提案させていただきましたけれども、ここら辺についての船のそもそも係留する場所ということの目的が１つありますので、この船の保有計画についての確認をさせていただきたいと思います。","respondent":"武藤河川下水道課長","answer":"船舶の件につきましてですけれども、まずは区としましては、今申しましたようなまず水辺との接点である桟橋の設置を行いながら、設置の調整を進めながら、船の保有につきましても、現在一体的に検討を進めているところです。","voiceIndex":337,"id":"exchange-132"},{"speaker":"若林委員","kind":"質問・要望","question":"期待をしております。これは国とか都のいわゆる特区構想も絡んでくるということで。１分になりました。すいません、まちづくりマスタープランの住宅のほうでは、これも大きな１つのこれから政策になると思いますけれども、いわゆる民間住宅のストックを活用した今後の住宅政策の方針について、時間がありませんけれども、マスタープラン策定後の進め方について一言意見をいただけますか。","respondent":"山崎マスタープラン担当課長","answer":"住宅の量の供給という観点から、そうした既存のストックをなるべく区民の皆様に長く提供していくために、長寿命化、あるいは予防、修繕を計画的に実施していくなど、ストック活用を重視しながら政策のほうの展開を柱として考えてまいりたいと、このような考えです。","voiceIndex":339,"id":"exchange-133"},{"speaker":"大沢委員","kind":"質問・要望","question":"１６２ページ、地籍調査事業、１６７ページ、まちづくりマスタープラン策定費、１７０ページ、武蔵小山駅周辺地域整備事業、それであと、土木費について聞かせていただきたいと思います。進んでないやにちょっと伺いました。この地籍調査事業については、都からの委託ということで理解をしておりますけれども、都の動向、この地籍調査についてはどう考え、どう今後運んでいくのか、教えていただきたい。","respondent":"小林土木管理課長","answer":"お尋ねいただきました地籍調査なんですが、現在第６次１０カ年計画ということで、最終年次、平成３１年度を目標に計画を進めているです。","voiceIndex":342,"id":"exchange-134"},{"speaker":"大沢委員","kind":"質問・要望","question":"先ほどの、次、１６３ページの道路新設というところの質問します。先ほど石田秀男委員より放射２号線と２９号線の話がございました。僕の仕入れた情報では、制度設計のところにおいては、まだしっかりと、年度末には決まらないというような、非常にそこ、都と区のばらけたような情報があるんですけれども、そこのところ、一体どっちを信じながらこれを理解していったらいいのか教えていただきたいと思います。","respondent":"藤田都市計画課長","answer":"制度設計のほうですけれども、これまで東京都のほうと話をしてきている中では、もともとの実施方針の中でも、平成２４年度、第３四半期について、その制度についての枠組みについてお示しをし、第４四半期、３月までにはその制度を構築するということで。","voiceIndex":344,"id":"exchange-135"},{"speaker":"大沢委員","kind":"質問・要望","question":"ましてや断言をしてしまうということは、当事者にとって、これはまさにお役所のお話ですから、天の声、神の声に聞こえるわけ、お墨付きがつくわけですから、そこのところはしっかりと情報の交錯したところはあろうかと思いますけれども、言い方にお気をつけいただきながらこの説明会や何かを進めていっていただきたいと思うんですけれども、いかがでしょう。","respondent":"藤田都市計画課長","answer":"区民の皆様に正確な情報を速やかに伝える、これはもう私ども仕事を進める上で基本的なことだと考えています。そういう考えの中で、東京都としっかり連携を図りながら、地域の皆様についての説明も連携を図りながら進めていきたいと考えます。","voiceIndex":346,"id":"exchange-136"},{"speaker":"大沢委員","kind":"質問・要望","question":"そこのところもちょっとある方面といいますか、いろんなところからのほうの話も聞いておりますので、そこは情報を、要は違っていてもいいので、後の説明がつくように、情報の流し方、工夫をしていただきたいなと考えています。本当当事者にしてみれば、これは本当に、自分の、先ほども話をしたように、資産の問題ですから、しっかりと情報の伝達だけはいろいろな方法を用いてやっていただきたい。","respondent":"溝口都市開発課長","answer":"地域への周知につきましては、これまでも同様、開発計画につきましては、個別に計画が決まった中でご説明をしているところでありますし、マスタープラン等におきましては、皆さんにパブリックコメントを打って、武蔵小山のところだけでなく。","voiceIndex":348,"id":"exchange-137"},{"speaker":"大沢委員","kind":"質問・要望","question":"時間もあれなので、この質問はここまでにしますけれども、ぜひとも西の玄関口としてふさわしく生まれ変わるように。ローマも一日にしてならずですので、まちづくりは国家をつくるのと一緒で非常に長い年月、時間がかかりますので、それを加味しながら、この計画をしっかりと進めていただきたい。要望して終わります。では、最後の質問です。","respondent":"本城企画財政課長","answer":"基本的に土木費について、いわゆる投資的経費ということで多くは位置づけられているわけですが、社会資本の形成にかかわるということで、基本的にはそれが第一義的な目標だとは思いますが、ただ、社会資本の形成を通じて。","voiceIndex":352,"id":"exchange-138"},{"speaker":"大沢委員","kind":"質問","question":"具体的に社会資本の整備ということはお話しいただかなくても、それはもうわかっているわけで、では、具体的にどんな事業が社会資本整備のために、具体的に行われている、現状は景気刺激対策として公の事業、公共事業というのが区内で今行われているんですかという質問させていただきました。","respondent":"本城企画財政課長","answer":"そういう意味では、平成２３年度決算に即して申し上げれば、今回、昨年に比べて再開発事業が大きく増えたとか、そういう都市基盤の整備ということが、そういうことを基本として実施しています。","voiceIndex":354,"id":"exchange-139"},{"speaker":"大沢委員","kind":"質問・要望","question":"いずれにしても、景気、なかなか上向かない。いろんな部分で策を講じていただきたい、お願いをして質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":356,"id":"exchange-140"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1364#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":115167,"voices":357}}]);
